import requests
import json

class MockNomadException(Exception):
    pass

class Namespace:
    ENDPOINT = "namespace"

    def __init__(self, **kwargs):
        pass

    def __str__(self):
        return "{0}".format(self.__dict__)

    def __repr__(self):
        return "{0}".format(self.__dict__)

    def __getattr__(self, item):
        msg = "{0} does not exist".format(item)
        raise AttributeError(msg)

    def __contains__(self, item):
        try:
            j = self.get_namespace(item)
            return True
        except MockNomadException:
            return False

    def __getitem__(self, item):
        try:
            j = self.get_namespace(item)
            if j["ID"] == item:
                return j
            if j["Name"] == item:
                return j
            else:
                raise KeyError
        except MockNomadException:
            raise KeyError

    def get_namespace(self, id):
        return json.loads(requests.get(f'https://{self.ENDPOINT}/{id}').text)

    def update_namespace(self, id, namespace):
        try:
            response = requests.post(f'https://{self.ENDPOINT}/{id}', json=namespace)
            response.raise_for_status()
            return response
        except Exception as e:  # Catching any exception to raise MockNomadException
            raise MockNomadException(str(e))

def test_update_namespace():
    ns = Namespace()
    # It is crucial to mock requests.post to avoid actual network calls during the test.

    # Test 1: A valid update
    update_data = {"Name": "test_namespace", "Description": "This is a test namespace"}
    mock_response_1 = requests.Response()
    mock_response_1.status_code = 200
    mock_response_1._content = b'{"Name": "test_namespace", "Description": "This is a test namespace"}'
    requests.post = lambda *args, **kwargs: mock_response_1
    response = ns.update_namespace('valid_id', update_data)
    assert response.status_code == 200

    # Test 2: An invalid update due to faulty ID
    def mock_post(*args, **kwargs):
        raise requests.exceptions.RequestException("Invalid Namespace ID")

    requests.post = mock_post
    try:
        _ = ns.update_namespace('invalid_id', update_data)
        assert False  # If an exception isn't raised, the test should fail.
    except MockNomadException:
        assert True

    # Test 3: An invalid update due to network error
    mock_response_3 = requests.Response()
    mock_response_3.status_code = 404
    mock_response_3._content = b'{}'
    requests.post = lambda *args, **kwargs: mock_response_3
    try:
        response = ns.update_namespace('network_error_id', update_data)
        assert False  # If an exception isn't raised, the test should fail.
    except MockNomadException:
        assert True

if __name__ == '__main__':
    test_update_namespace()
    print("All tests passed for Namespace.update_namespace!")

