import optparse

class OptionsProviderMixIn:
    """Mixin to provide options to an OptionsManager"""

    def __init__(self):
        self.options = ()

    def get_option_def(self, opt):
        """return the dictionary defining an option given its name"""
        assert self.options
        for option in self.options:
            if option[0] == opt:
                return option[1]
        raise optparse.OptionError(
            "no such option %s" % opt, opt
        )

def test_get_option_def():
    optionsProvider = OptionsProviderMixIn()
    optionsProvider.options = [("example_option", {"type": "int", "default": 10})]

    # Test valid option
    assert optionsProvider.get_option_def("example_option") == {"type": "int", "default": 10}

    # Test invalid option
    try:
        optionsProvider.get_option_def("nonexistent_option")
    except optparse.OptionError:
        assert True
    else:
        assert False

    # Test empty option
    try:
        optionsProvider = OptionsProviderMixIn() # Resetting optionsProvider to have no options
        optionsProvider.get_option_def("example_option")
    except AssertionError:
        assert True
    else:
        assert False

if __name__ == "__main__":
    test_get_option_def()

