import re
import logging
from difflib import SequenceMatcher

# Custom made error class for handling sanity check errors.
class SanityError(Exception):
    pass

# Placeholder for the colored print functionality.
# We are defining a simple print statement for this isolated environment.
def colored_print(msg, color='white'):
    print(msg)

# Logger setup
logger = logging.getLogger("main.sanity_checks")
logger.setLevel(logging.INFO)
handler = logging.StreamHandler()
formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)

# Set the tokens used for the main syntax
FORK_TOKEN = "("
LANE_TOKEN = "|"
CLOSE_TOKEN = ")"

# Define sanity check functions here since they are used in insanity_checks
def empty_tasks(p_string):
    if any(len(task.strip()) == 0 for task in re.split('\||\(|\)', p_string)):
        raise SanityError("Empty task found")

def brackets_but_no_lanes(p_string):
    if FORK_TOKEN in p_string and LANE_TOKEN not in p_string:
        raise SanityError("Pipeline has brackets but no lane separator")

def brackets_insanity_check(p_string):
    if p_string.count(FORK_TOKEN) != p_string.count(CLOSE_TOKEN):
        raise SanityError("Mismatched number of opening and closing brackets")

def lane_char_insanity_check(p_string):
    lane_split = p_string.split(LANE_TOKEN)
    if any(FORK_TOKEN in portion or CLOSE_TOKEN in portion for portion in lane_split[1:-1]):
        raise SanityError("Incorrect '|' character inside forks")

def final_char_insanity_check(p_string):
    last_char = p_string[-1]
    if last_char in [FORK_TOKEN, LANE_TOKEN]:
        raise SanityError("Pipeline ends with improper character")

def insanity_checks(pipeline_str):
    # Performing sanity checks on the pipeline string
    p_string = pipeline_str.replace(" ", "").strip()
    for check in [empty_tasks, brackets_but_no_lanes, brackets_insanity_check,
                  lane_char_insanity_check, final_char_insanity_check]:
        check(p_string)

def test_insanity_checks():
    # Test 1: Check for valid pipeline string
    try:
        insanity_checks("processA ( processB | processC ) processD")
