class OrderedBidictBase:
    def _isdupitem(self, key, val, dedup_result):
        isdupkey, isdupval, nodeinv, nodefwd = dedup_result
        isdupitem = nodeinv is nodefwd
        if isdupitem:
            assert isdupkey
            assert isdupval
        return isdupitem


def test__isdupitem():
    ob = OrderedBidictBase()

    # Test when the key and value are not duplicates (nodeinv is not nodefwd)
    test_dedup_result_1 = (False, False, _Node(), _Node())
    assert not ob._isdupitem('key', 'val', test_dedup_result_1), "Failed test case where key and value are unique"

