    from urllib2 import urlopen

class RateNotFoundError(Exception):
    """Custom exception when data is missing in the rates file."""
    pass

class CurrencyConverter:
    def __init__(self, url="https://www.ecb.europa.eu/stats/eurofxref/eurofxref-hist.zip"):
        self._rates = defaultdict(dict)
        self.load_data_from_url(url)

    def load_data_from_url(self, url):
        content = urlopen(url).read()
        zip_file = ZipFile(BytesIO(content))
        lines = zip_file.read(zip_file.namelist()[0]).decode('utf-8').splitlines()
        header = lines[0].strip().split(',')[1:]

        for line in lines[1:]:
            line = line.strip().split(',')
            date = datetime.strptime(line[0], '%Y-%m-%d')
            for currency, rate in zip(header, line[1:]):
                if rate and rate != 'N/A':  # Check if rate is not empty and not 'N/A'
                    self._rates[currency][date] = float(rate)

    def _get_rate(self, currency, date):
        if currency == 'EUR':
            return 1.0

        if date not in self._rates[currency]:
            raise RateNotFoundError(f"{currency} has no rate for {date}")

        return self._rates[currency][date]

    def convert(self, amount, currency, new_currency='EUR', date=None):
        if date is None:
            date = max(self._rates[currency].keys())

        r0 = self._get_rate(currency, date)
        r1 = self._get_rate(new_currency, date)

        return float(amount) / r0 * r1

