    def set_compiler_channels(self, channel_list, operator="mix"):
        if not channel_list:
            raise ValueError("At least one status channel must be provided to include this process in the pipeline")

        if len(channel_list) == 1:
            compile_channels = channel_list[0]
        else:
            first_status = channel_list[0]
            if operator == "mix":
                lst = ",".join(channel_list[1:])
                compile_channels = "{}.mix({})".format(first_status, lst)
            elif operator == "join":
                compile_channels = first_status
                for ch in channel_list[1:]:
                    compile_channels += ".join({})".format(ch)
                compile_channels += ".map{ ot -> [ ot[0], ot[1..-1] ] }"
            else:
                raise ValueError("Operator must be 'mix' or 'join'")

        self.compile_channels = compile_channels

def test_set_compiler_channels():
    # Test when using "mix" operator and multiple channels
    c1 = Compiler(template="template")
    c1.set_compiler_channels(["STATUS_A", "STATUS_B", "STATUS_C"], operator="mix")
    assert c1.compile_channels == "STATUS_A.mix(STATUS_B,STATUS_C)"

    # Test when using "join" operator and multiple channels
    c2 = Compiler(template="template")
    c2.set_compiler_channels(["STATUS_X", "STATUS_Y"], operator="join")
    assert c2.compile_channels == "STATUS_X.join(STATUS_Y).map{ ot -> [ ot[0], ot[1..-1] ] }"

    # Test with single status channel
    c3 = Compiler(template="template")
    c3.set_compiler_channels(["SINGLE_STATUS"])
    assert c3.compile_channels == "SINGLE_STATUS"

    # Test raising ValueError for empty channel list
    try:
        c4 = Compiler(template="template")
        c4.set_compiler_channels([], operator="mix")
    except ValueError as e:
        assert str(e) == "At least one status channel must be provided to include this process in the pipeline"
    else:
        assert False, "ValueError not raised for empty channel_list"

    # Test raising ValueError for invalid operator
    try:
        c5 = Compiler(template="template")
        c5.set_compiler_channels(["STATUS_A", "STATUS_B"], operator="invalid_operator")
    except ValueError as e:
        assert str(e) == "Operator must be 'mix' or 'join'"
    else:
        assert False, "ValueError not raised for invalid operator"

if __name__ == '__main__':
