Position = namedtuple("Position", ["z"])
Component = namedtuple("Component", ["description"])
# Ensure defaults are correctly set for each field of the Interval named tuple.
Interval = namedtuple("Interval", ["top", "base", "components", "description", "data"])
Interval.__new__.__defaults__ = (None, None, None, None, None)

class StriplogError(Exception):
    pass

class Striplog(object):
    def __init__(self, list_of_Intervals, source=None, order='auto'):
        self.__list = list_of_Intervals
        self.source = source
        self.order = order

    def __str__(self):
        s = [str(i) for i in self.__list]
        return '\n'.join(s)

    def __getitem__(self, key):
        return self.__list[key]

    def __len__(self):
        return len(self.__list)

    def plot_tops(self, ax, field=None, **kwargs):
        if field is None:
            raise StriplogError('You must provide a field to plot.')

        ys = [iv.top.z for iv in self]

        try:
            ts = [getattr(iv.components[0], field) for iv in self]
        except:
            ts = [iv.data.get(field) for iv in self]

        for y, t in zip(ys, ts):
            ax.axhline(y, color='lightblue', lw=3, zorder=0)
            ax.text(0.1, y - max(ys) / 200, t, ha='left')

        return ax

def test_plot_tops():
    sandstone = Component(description="Sandstone")
    shale = Component(description="Shale")
    iv1 = Interval(top=Position(z=100), base=Position(z=150), components=[sandstone], data=None)
    iv2 = Interval(top=Position(z=150), base=Position(z=200), components=[shale], data=None)
    iv3 = Interval(top=Position(z=200), base=Position(z=300), components=[sandstone], data=None)
    striplog = Striplog([iv1, iv2, iv3], order='depth')

    fig, ax = plt.subplots(figsize=(3, 6))
    assert striplog.plot_tops(ax, field='description') == ax
    assert len(striplog) == 3
    assert striplog[0] == iv1

if __name__ == '__main__':
    test_plot_tops()

