import math

def boolean_arg(ctx, obj):
    '''
    Handles LiteralObjects as well as computable arguments
    '''
    if hasattr(obj, 'compute'):
        obj = next(obj.compute(ctx), False)
    return to_boolean(obj)

def to_boolean(obj):
    '''
    Convert obj to its boolean representation and yield it.

    * False if the obj is an empty sequence
    * False if the obj is a boolean and False
    * False if the obj is a number and positive or negative zero or NaN
    * False if the obj is a string and ''
    * True in all other cases
    '''
    if isinstance(obj, str):
        return obj != ''
    elif isinstance(obj, bool):
        return obj
    elif isinstance(obj, (int, float)):
        return bool(obj) and not math.isnan(obj)
    else:
        return bool(obj)

class Context:
    def __init__(self, item):
        self.item = item

def test_boolean_arg():
    ctx = Context(None)
    assert boolean_arg(ctx, "non-empty string") == True, "String should be True"
    assert boolean_arg(ctx, "") == False, "Empty string should be False"
    assert boolean_arg(ctx, True) == True, "True should be True"
    assert boolean_arg(ctx, False) == False, "False should be False"
    assert boolean_arg(ctx, 1) == True, "1 should be True"
    assert boolean_arg(ctx, 0) == False, "0 should be False"
    assert boolean_arg(ctx, 0.1) == True, "0.1 should be True"
    assert boolean_arg(ctx, math.nan) == False, "NaN should be False"
    assert boolean_arg(ctx, None) == False, "None should be False"
    assert boolean_arg(ctx, [1, 2, 3]) == True, "Non-empty list should be True"
    assert boolean_arg(ctx, []) == False, "Empty list should be False"

if __name__ == '__main__':
    test_boolean_arg()

