import re

class Client:

    def __init__(self):
        self.job = 'build'

    def _parse_image_name(self, image, retry=True):
        try:
            parts = image.split(',')
            if len(parts) == 3:
                job_id, collection, job_name = parts
            elif len(parts) == 2:
                job_id, collection = parts
                job_name = self.job
            else:
                raise ValueError
        except:
            if retry:
                return self._parse_image_name("%s,%s" % (image, self.job), retry=False)
            raise ValueError('Malformed image string! Please provide: job_id,collection (or) job_id,collection,job_name')
        return job_id, collection, job_name

def test__parse_image_name():
    client = Client()
    # Test with correctly formatted three parts
    image = "1,collection_name,job_name"
    assert client._parse_image_name(image) == ("1", "collection_name", "job_name")

    # Test with correctly formatted two parts where retry is implicitly true
    image = "2,collection_name"
    assert client._parse_image_name(image) == ("2", "collection_name", "build")

    # Test with malformed image string and retry is false
    malformed_image = "3"
    try:
        client._parse_image_name(malformed_image, retry=False)
        assert False, "ValueError was expected but not raised."
    except ValueError:
        assert True

    # Extra case: well-formatted two parts, where it should not retry and therefore not reach the exception
    assert client._parse_image_name("4,collection_name", retry=False) == ("4", "collection_name", "build")

if __name__ == '__main__':
    test__parse_image_name()

