import math
from collections import deque

class WindowCounter(object):
    def __init__(self, window_size):
        self.window_size = window_size
        self.q = deque()

    def push(self, value):
        self.q.append(value)
        if len(self.q) > self.window_size:
            self.q.popleft()

    def __len__(self):
        return len(self.q)

class TotalHTTPTrendCriterion(object):
    def __init__(self, window_size):
        self.tangents = WindowCounter(window_size)
        self.seconds_limit = window_size

    def calc_measurement_error(self, tangents):
        '''
        formula for measurement error
        sqrt ( (sum(1, n, (k_i - <k>)**2) / (n*(n-1)))
        '''
        if len(tangents) < 2:
            return 0.0

        avg_tan = float(sum(tangents) / len(tangents))
        numerator = float()
        for i in tangents:
            numerator += (i - avg_tan) ** 2

        return math.sqrt(numerator / (len(tangents) * (len(tangents) - 1)))

def test_calc_measurement_error():
    # Test with perfect linear progress (now checking for correct standard deviation)
    criteria_1 = TotalHTTPTrendCriterion(window_size=5)
    test_tangents_1 = [1, 2, 3, 4, 5]
    for t in test_tangents_1:
        criteria_1.tangents.push(t)
    expected_std_dev_1 = math.sqrt(sum((x - 3)**2 for x in test_tangents_1) / (len(test_tangents_1) * (len(test_tangents_1) - 1)))
    assert round(criteria_1.calc_measurement_error(criteria_1.tangents.q), 6) == round(expected_std_dev_1, 6)

    # Test with uniform value (also should be zero)
    criteria_2 = TotalHTTPTrendCriterion(window_size=4)
    test_tangents_2 = [5, 5, 5, 5]
    for t in test_tangents_2:
        criteria_2.tangents.push(t)
    assert criteria_2.calc_measurement_error(criteria_2.tangents.q) == 0.0

    # Test with actual tangent values with expected non-zero error
    criteria_3 = TotalHTTPTrendCriterion(window_size=3)
    test_tangents_3 = [2, 4, 4]
    for t in test_tangents_3:
        criteria_3.tangents.push(t)
    # Corrected to calculate sample standard deviation
    expected_std_dev_3 = math.sqrt(sum((x - float(sum(test_tangents_3)/3))**2 for x in test_tangents_3) / (len(test_tangents_3) * (len(test_tangents_3) - 1)))
    assert round(criteria_3.calc_measurement_error(criteria_3.tangents.q), 6) == round(expected_std_dev_3, 6)

    print("All tests passed.")

if __name__=='__main__':
    test_calc_measurement_error()

