# -*- coding: utf-8 -*-

"""
The CX direction rearranges the direction of the cx nodes to make the circuit
compatible with the coupling map.
"""

class MockGate:
    def __init__(self, name):
        self.name = name

class MockDAGCircuit:
    def __init__(self):
        self.qregs = {}
        self.gate_nodes = []

    def add_qreg(self, qreg):
        self.qregs[qreg] = None

    def apply_operation_back(self, op, qargs, cargs):
        self.gate_nodes.append((op.name, qargs, cargs))

    def apply_operation_front(self, op, qargs, cargs):
        self.gate_nodes = [(op.name, qargs, cargs)] + self.gate_nodes

    def extend_back(self, dag):
        self.gate_nodes.extend(dag.gate_nodes)

    def named_nodes(self, *args):
        return [n for n in self.gate_nodes if n[0] in args]

    def serial_layers(self):
        yield {'graph': self}


class MockLayout:
    def __init__(self, mapping):
        self.mapping = mapping

    def __getitem__(self, key):
        return self.mapping[key]

class MockCouplingMap:
    def __init__(self, edges):
        self.edges = edges

    def get_edges(self):
        return self.edges

    def distance(self, physical_q0, physical_q1):
        return 1 if (physical_q0, physical_q1) in self.edges or \
                     (physical_q1, physical_q0) in self.edges else float('inf')


class CXDirection:
    def __init__(self, coupling_map, initial_layout=None):
        self.coupling_map = coupling_map
        self.layout = initial_layout

    def run(self, dag):
        new_dag = MockDAGCircuit()
        if self.layout is None:
            raise NotImplementedError("Layout must be provided")

        for layer in dag.serial_layers():
            subdag = layer['graph']
            for gate_name, qargs, cargs in subdag.named_nodes('cx'):
                control = qargs[0]
                target = qargs[1]
                physical_q0 = self.layout[control]
                physical_q1 = self.layout[target]
                if self.coupling_map.distance(physical_q0, physical_q1) != 1:
                    raise Exception('The circuit requires a connection between physical ' \
                                    'qubits %s and %s' % (physical_q0, physical_q1))
                if (physical_q0, physical_q1) not in self.coupling_map.get_edges():
                    subdag.apply_operation_back(MockGate('h'), [target], [])
                    subdag.apply_operation_back(MockGate('h'), [control], [])
                    subdag.apply_operation_front(MockGate('h'), [target], [])
                    subdag.apply_operation_front(MockGate('h'), [control], [])
                    qargs[0], qargs[1] = target, control
            new_dag.extend_back(subdag)
        return new_dag

def test_run():
    # Define the coupling map to be used in tests
    coupling_map = MockCouplingMap([(0, 1), (1, 2)])

    # Case 1: CX within the coupling map
    layout = MockLayout({'qr[0]': 0, 'qr[1]': 1})
    input_dag = MockDAGCircuit()
