class PrefilterManager:
    def __init__(self):
        self._handlers = {}
        self._esc_handlers = {}
        self.init_handlers()

    def init_handlers(self):
        # Assume that init_handlers is supposed to set these keys for testing
        self._handlers['shell'] = 'shell_handler'
        self._handlers['magic'] = 'magic_handler'
        self._handlers['normal'] = 'normal_handler'

    @property
    def handlers(self):
        """Return a dict of all the handlers."""
        return self._handlers

    def register_handler(self, name, handler, esc_strings):
        self._handlers[name] = handler

    def unregister_handler(self, name, handler, esc_strings):
        try:
            del self._handlers[name]
        except KeyError:
            pass

    def get_handler_by_name(self, name):
        return self._handlers.get(name)

    def prefilter_line_info(self, line_info):
        handler = self.find_handler(line_info)
        return handler.handle(line_info)

    def find_handler(self, line_info):
        if line_info.startswith('!'):
            return self._handlers['shell']
        elif line_info.startswith('%'):
            return self._handlers['magic']
        else:
            return self._handlers['normal']


