import hashlib
import base64
from django.utils import timezone
from django.conf import settings
from django.core.signing import dumps

# Configuring Django settings before using timezone functionality
settings.configure(USE_TZ=True, SECRET_KEY='your-secret-key')

HASH_MINUTES_VALID = {
    'password_reset': 1440,
    'resume_login': 240
}

class HashPurpose:
    PASSWORD_RESET = 'password_reset'
    RESUME_LOGIN = 'resume_login'

def iter_auth_hashes(user, purpose, minutes_valid):
    now = timezone.now().replace(microsecond=0, second=0)
    for minute in range(minutes_valid + 1):
        yield hashlib.sha1(
            f"{now - datetime.timedelta(minutes=minute)}:{user.password}:{purpose}:{user.pk}:{settings.SECRET_KEY}".encode('utf-8')
        ).hexdigest()

def get_auth_hash(user, purpose):
    return next(iter_auth_hashes(user, purpose, minutes_valid=1))

def calc_expiry_time(minutes_valid):
    return (
        timezone.now() + datetime.timedelta(minutes=minutes_valid + 1)
    ).replace(second=0, microsecond=0)

def get_user_token(user, purpose, minutes_valid):
    serialized_data = dumps([
        user.get_username(),
        get_auth_hash(user, purpose),
    ])
    encoded_data = base64.b64encode(serialized_data.encode()).decode()
    token = ''.join(encoded_data.split('\n'))
    return {
        'id': user.pk,
        'token': token,
        'tokenExpires': calc_expiry_time(minutes_valid),
    }

class Auth:
    def validated_user(self, resume_token, purpose, minutes_valid):
        pass

    def do_login(self, user):
        pass

    def login_with_resume_token(self, params):
        user = self.validated_user(
            params['resume'], purpose=HashPurpose.RESUME_LOGIN,
            minutes_valid=HASH_MINUTES_VALID[HashPurpose.RESUME_LOGIN],
        )

        self.do_login(user)

        # The change is here: we transform the token to base64 manually
        # instead of using the non-existent `encode('base64')`
        user_token_info = get_user_token(
            user=user, purpose=HashPurpose.RESUME_LOGIN,
            minutes_valid=HASH_MINUTES_VALID[HashPurpose.RESUME_LOGIN],
        )
        user_token_info['token'] = base64.b64encode(user_token_info['token'].encode()).decode()
        return user_token_info

def test_login_with_resume_token():
    auth_instance = Auth()
    mock_user = Mock()
    mock_user.get_username.return_value = 'mock_username'
    mock_user.password = 'mock_password'
    mock_user.pk = 'mock_pk'

    with patch.object(Auth, 'validated_user', return_value=mock_user) as valid_user_mock:
        with patch.object(Auth, 'do_login') as do_login_mock:

            resume_token = 'valid_token'
            params = {'resume': resume_token}
            result = auth_instance.login_with_resume_token(params)

            valid_user_mock.assert_called_once_with(
                resume_token, purpose=HashPurpose.RESUME_LOGIN,
                minutes_valid=HASH_MINUTES_VALID[HashPurpose.RESUME_LOGIN],
            )
            do_login_mock.assert_called_once_with(mock_user)

            assert 'id' in result
