import string

def make_fuzzy(word, max=1):
    """Naive neighborhoods algo."""
    # inversions
    neighbors = []
    for i in range(0, len(word) - 1):
        neighbor = list(word)
        neighbor[i], neighbor[i+1] = neighbor[i+1], neighbor[i]
        neighbors.append(''.join(neighbor))
    # substitutions
    for letter in string.ascii_lowercase:
        for i in range(0, len(word)):
            neighbor = list(word)
            if letter != neighbor[i]:
                neighbor[i] = letter
                neighbors.append(''.join(neighbor))
    # insertions
    for letter in string.ascii_lowercase:
        for i in range(0, len(word) + 1):
            neighbor = list(word)
            neighbor.insert(i, letter)
            neighbors.append(''.join(neighbor))
    if len(word) > 3:
        # removal
        for i in range(0, len(word)):
            neighbor = list(word)
            del neighbor[i]
            neighbors.append(''.join(neighbor))
    return neighbors

def preprocess_query(query):
    return query.strip().lower()

def do_fuzzy(word):
    """Compute fuzzy extensions of word."""
    word = preprocess_query(word)
    if word:  # Only call make_fuzzy if the word isn't empty
        return make_fuzzy(word)
    else:
        return []  # Return an empty list for empty input

def test_do_fuzzy():
    # Test with a word starting with letter 'l'
    results = do_fuzzy("lilas")
    for letter in string.ascii_lowercase:
        if letter != 'l':
            # Should generate substitutions with every letter except 'l'
            assert (letter + 'ilas') in results
        # Should generate insertions with every letter
        assert (letter + 'lilas') in results
    # Test with empty string
    assert do_fuzzy("") == []
    # Test with a single character
    single_letter_results = do_fuzzy("a")
    for letter in string.ascii_lowercase:
        if letter != 'a':
            assert letter in single_letter_results

if __name__ == "__main__":
    test_do_fuzzy()
    # Example usage as before
    word = "lilas"
    fuzzy_words = do_fuzzy(word)
    print(fuzzy_words)

