from typing import Any, Iterable, Iterator, Optional, TypeVar

T = TypeVar("T")

class _EmptySequence:
    def __repr__(self):
        return "()"

    def __bool__(self):
        return False

    @property
    def is_empty(self) -> bool:
        return True

    @property
    def first(self) -> Optional[T]:
        return None

    @property
    def rest(self) -> '_EmptySequence':
        return self

    def cons(self, elem):
        return Cons(elem, self)

EMPTY = _EmptySequence()

class Cons:
    __slots__ = ("_first", "_rest")

    def __init__(self, first=None, seq: Optional[_EmptySequence] = None) -> None:
        self._first = first
        self._rest = seq or EMPTY

    @property
    def is_empty(self) -> bool:
        return False

    @property
    def first(self) -> Optional[T]:
        return self._first

    @property
    def rest(self) -> '_EmptySequence':
        return self._rest

    def cons(self, elem: T) -> '_EmptySequence':
        return Cons(elem, self)

class _Sequence:
    def __init__(self, s: Iterator, first: T) -> None:
        self.x = s
        self.prev = None
        self._first = first
        self._rest: Optional[_EmptySequence] = None

    @property
    def is_empty(self) -> bool:
        return False

    @property
    def first(self) -> Optional[T]:
        return self._first

    @property
    def rest(self) -> '_EmptySequence':
        if self._rest:
            return self._rest
        try:
            n = next(self.x)
            self._rest = _Sequence(self.x, n)
        except StopIteration:
            self._rest = EMPTY
        return self._rest

    def cons(self, elem):
        return Cons(elem, self)

def sequence(s: Iterable[T]) -> _EmptySequence:
    try:
        i = iter(s)
        return _Sequence(i, next(i))
    except StopIteration:
        return EMPTY

def test_sequence():
    # Test non-empty sequence creation
    seq = sequence([1, 2, 3])
    assert seq.first == 1
    assert not seq.is_empty

    # Test iterating through a sequence
    elements = []
    while not seq.is_empty:
        elements.append(seq.first)
        seq = seq.rest
    assert elements == [1, 2, 3]

    # Test empty sequence creation
    empty_seq = sequence([])
    assert empty_seq.is_empty

if __name__ == "__main__":
    test_sequence()

