class GroupBy(object):
    def __init__(self, fr, by):
        self._fr = fr
        self._by = by
        self._aggs = {}
        self._res = None

        if isinstance(by, str):
            self._by = [self._fr.names.index(by)]
        elif isinstance(by, list):
            self._by = [self._fr.names.index(b) if isinstance(b, str) else b for b in by]
        else:
            self._by = [self._by]

    def get_frame(self):
        if self._res is None:
            aggs = []
            cols_operated = []
            for k in self._aggs:
                aggs += (self._aggs[k])
                col_used = self._aggs[k][1]
                if col_used not in cols_operated:
                    cols_operated.append(col_used)

            for cind in cols_operated:
                if cind not in self._by:
                    self._check_string_columns(cind)
            print("Groupby Frame: by={}, aggs={}".format(self._by, aggs))
            self._res = "groupby_frame"

        return self._res

    def _add_agg(self, op, col, na):
        if op == "nrow":
            col = 0
        if col is None:
            for i in range(self._fr.ncol):
                if i not in self._by:
                    self._add_agg(op, i, na)
            return self
        elif isinstance(col, str):
            cidx = self._fr.names.index(col)
        elif isinstance(col, int):
            cidx = col
        elif isinstance(col, list):
            for i in col:
                self._add_agg(op, i, na)
            return self
        else:
            raise ValueError("col must be a column name or index.")
        name = "{}_{}".format(op, self._fr.names[cidx])
        self._aggs[name] = [op, cidx, na]
        return self

    def _check_string_columns(self, colIndex):
        if self._fr[colIndex].isstring()[0]:
            print("Column {0} is a string column. No groupby operation will be performed on it.".format(self._fr.names[colIndex]))

    def __repr__(self):
        print("GroupBy: ")
        print("  Frame: {}; by={}".format(self._fr.frame_id, str(self._by)))
        print("  Aggregates: {}".format(str(self._aggs.keys())))
        print("*** Use get_frame() to get groupby frame ***")
        return ""


