    dialog1 = Dialog()
    dialog2 = Dialog()
    # Set the id of dialog2 to simulate a different dialog by using the setter
    dialog2.id = "dialog_id_2"

    await dialog_set.add(dialog1)
    assert await dialog_set.find(dialog1.id) == dialog1, "Error: Dialog not found after being added."

