class CompletionHtml:
    def __init__(self):
        self._items = ()
        self._index = (0, 0)
        self._size = (1, 1)

    def _select_index(self, row, col):
        nr, nc = self._size
        nr = nr - 1
        nc = nc - 1

        if (row > nr and col >= nc) or (row >= nr and col > nc):
            self._select_index(0, 0)
        elif (row <= 0 and col < 0) or (row < 0 and col <= 0):
            self._select_index(nr, nc)
        elif row > nr:
            self._select_index(0, col + 1)
        elif row < 0:
            self._select_index(nr, col - 1)
        elif col > nc:
            self._select_index(row + 1, 0)
        elif col < 0:
            self._select_index(row - 1, nc)
        elif 0 <= row and row <= nr and 0 <= col and col <= nc:
            self._index = (row, col)
        else:
            raise NotImplementedError("you're trying to go where no completion have gone before : %d:%d (%d:%d)" % (row, col, nr, nc))

    def select_right(self):
        r, c = self._index
        self._select_index(r, c + 1)

def test_select_right():
    completion_widget = CompletionHtml()
    completion_widget._size = (2, 3)  # Set size manually for testing purposes

    completion_widget._index = (0, 0)
    completion_widget.select_right()
    assert completion_widget._index == (0, 1)

    completion_widget._index = (1, 2)
    completion_widget.select_right()
    assert completion_widget._index == (0, 0)

    completion_widget._index = (1, 1)
    completion_widget.select_right()
    assert completion_widget._index == (1, 2)

if __name__ == '__main__':
