    def __init__(self, name, **kwargs):
        self.name = name
        self.kwargs = kwargs  # remove 'dest' from here

    def add_to_parser(self, subparsers):
        subparsers.add_parser(self.name, **self.kwargs)

def test_add_subparsers():
    # Create main parser for testing
    test_parser = Parser()

    # Create subparsers and add them to the test_parser
    echo_subparser = SubParser('echo', help='Echo command')
    test_parser.add_subparser(echo_subparser)

    list_subparser = SubParser('list', help='List command')
    test_parser.add_subparser(list_subparser)

    # Add subparsers to the argparse subparsers structure
    test_parser.add_subparsers(test_parser.parser)

    # Test to check if subparsers are added properly
    test_parser.parse_args(['echo'])
    known_subparsers = ['echo', 'list']
    subs = [choice for choice in test_parser.parser._subparsers._actions[-1].choices.keys()]
    assert all(sub in known_subparsers for sub in subs)

    # Test with defined arguments
    echo_args = test_parser.parse_args(['echo'])
    assert echo_args.command == 'echo'

    # Test for help text in subparsers
    assert echo_subparser.kwargs['help'] == 'Echo command'
    assert list_subparser.kwargs['help'] == 'List command'

