import contextlib
from functools import wraps
import time
import sys
import io

class MetricsInterface:
    def __init__(self, name):
        self.name = name.strip('.')

    def _full_stat(self, stat):
        if self.name:
            return self.name + '.' + stat
        else:
            return stat

    def timing(self, stat):
        full_stat = self._full_stat(stat)
        print("Timing stat: ", full_stat)

    @contextlib.contextmanager
    def timer(self, stat):
        start_time = time.perf_counter()
        yield
        end_time = time.perf_counter()
        delta = end_time - start_time
        self.timing(stat)

    def timer_decorator(self, stat):
        def _inner(fun):
            @wraps(fun)
            def _timer_decorator(*args, **kwargs):
                with self.timer(stat):
                    return fun(*args, **kwargs)
            return _timer_decorator
        return _inner

def test_timer_decorator():
    metrics = MetricsInterface("test")

    @metrics.timer_decorator("decorated_function")
    def decorated_function(x):
        return x**2

    # Capture the output
    captured_output = io.StringIO()
    sys.stdout = captured_output
    result = decorated_function(4)
    sys.stdout = sys.__stdout__

    assert "Timing stat: " in captured_output.getvalue(), "The timing stat should be printed."
    assert result == 16, "The decorated_function should return the correct result."
    assert "test.decorated_function" in captured_output.getvalue(), "Timing stat should contain the full stat."

    # Test with a function taking no arguments
    @metrics.timer_decorator("no_arg_function")
    def no_arg_function():
        return "No arguments here"

    captured_output = io.StringIO()
    sys.stdout = captured_output
    result = no_arg_function()
    sys.stdout = sys.__stdout__

    assert "Timing stat: " in captured_output.getvalue(), "The timing stat should be printed for no_arg_function."
    assert result == "No arguments here", "The no_arg_function should return the correct result."

    # Test with a function taking multiple arguments
    @metrics.timer_decorator("multi_arg_function")
    def multi_arg_function(a, b, c=1):
        return a + b + c

    captured_output = io.StringIO()
    sys.stdout = captured_output
    result = multi_arg_function(2, 3, c=4)
    sys.stdout = sys.__stdout__

    assert "Timing stat: " in captured_output.getvalue(), "The timing stat should be printed for multi_arg_function."
    assert result == 9, "The multi_arg_function should return the correct result."

if __name__ == '__main__':
    test_timer_decorator()

