class HdlStatement:
    def __init__(self, parentStm=None, sensitivity=None,
                 is_completly_event_dependent=False):
        self._is_completly_event_dependent = is_completly_event_dependent
        self._now_is_event_dependent = is_completly_event_dependent
        self.parentStm = parentStm
        self._inputs = []
        self._outputs = []
        self._enclosed_for = None

        self._sensitivity = sensitivity
        self.rank = 0

    def _destroy(self):
        try:
            ctx = self._get_rtl_context()
        except HwtSyntaxError:
            return

        for i in self._inputs:
            i['endpoints'].discard(self)

        for o in self._outputs:
            o['drivers'].discard(self)

        ctx['statements'].discard(self)  # Use discard instead of remove to avoid KeyError

    def _get_rtl_context(self):
        """
        get RtlNetlist context from signals
        """
        for sig in self._inputs + self._outputs:
            if hasattr(sig, 'ctx'):
                return sig.ctx

        raise HwtSyntaxError(
            "Statement does not have any signal in any context", self)

def test__destroy():
    # Setup a mock HdlStatement and its context
    stm = HdlStatement()
    input_signal = {'endpoints': {stm}}
    output_signal = {'drivers': {stm}}
    stm._inputs = [input_signal]
    stm._outputs = [output_signal]

    # Create a context that won't re-add stm to 'statements' on each call
    context = {'statements': {stm}}
    stm._get_rtl_context = lambda: context

    # Test _destroy function
    stm._destroy()

    # Assertions to ensure that _destroy works correctly
    assert input_signal['endpoints'] == set(), "input endpoints should be an empty set after destruction"
    assert output_signal['drivers'] == set(), "output drivers should be an empty set after destruction"

    # The statement itself should be removed from the context's statements
    assert stm not in stm._get_rtl_context()['statements'], "statement should be removed from context's statements set"

if __name__ == '__main__':
    test__destroy()

