import os
import pickle
from functools import partial

# Dictionary that maps file extensions to serialization formats
known_extensions = {
    'pkl': 'pickle',
}

class Serializable:
    """ Class that implements shortcuts to serialize an object.

        Serialization is done by various formats. At the moment, only 'pickle'
        is supported.

        author: Tom Schaul, tom@idsia.ch; Justin Bayer, bayerj@in.tum.de
    """
    def save_to_file_like(self, flo, format="pickle", **kwargs):
        """ Save the object to a given file like object in the given format. """
        save = getattr(self, "save_%s" % format, None)
        if save is None:
            raise ValueError("Unknown format '%s'." % format)
        save(flo, **kwargs)

    @classmethod
    def load_from_file_like(cls, flo, format="pickle"):
        """ Load the object to a given file like object with the given protocol. """
        load = getattr(cls, "load_%s" % format, None)
        if load is None:
            raise ValueError("Unknown format '%s'." % format)
        return load(flo)

    def save_to_file(self, filename, format=None, **kwargs):
        """ Save the object to file given by filename. """
        if format is None:
            # try to derive protocol from file extension
            format = format_from_extension(filename)
        with open(filename, 'wb') as fp:
            self.save_to_file_like(fp, format=format, **kwargs)

    @classmethod
    def load_from_file(cls, filename, format=None):
        """ Return an instance of the class that is saved in the file with the given filename in the specified format. """
        if format is None:
            # try to derive protocol from file extension
            format = format_from_extension(filename)
        with open(filename, 'rb') as fp:
            obj = cls.load_from_file_like(fp, format)
            obj.filename = filename
            return obj

    def save_pickle(self, flo, protocol=0):
        pickle.dump(self, flo, protocol)

    @classmethod
    def load_pickle(cls, flo):
        return pickle.load(flo)

def format_from_extension(fname):
    """ Tries to infer a protocol from the file extension. """
    _base, ext = os.path.splitext(fname)
    if not ext:
        return None
    try:
        format = known_extensions[ext.replace('.','')]
    except KeyError:
        format = None
    return format

class TestSerializable(Serializable):
    def __init__(self, attribute):
        self.attribute = attribute

def test_save_to_file():      
    # Create an instance to be saved
    instance = TestSerializable('Serializable instance')

    # Save the instance to a file
    filename = 'test_save_to_file.pkl'
    instance.save_to_file(filename)

    # Load the instance from the file
    loaded_instance = TestSerializable.load_from_file(filename)

    # Test if the loaded instance has the same attribute as the saved instance
    assert loaded_instance.attribute == instance.attribute, "Failed load/save matching attributes test"

    # Ensure that the filename is set and saved correctly in the loaded instance
    assert loaded_instance.filename == filename, "Failed filename attribute test in loaded instance"

    # Test if the file was actually created
    assert os.path.isfile(filename), "File was not created"

    # Clean up the test by removing the created file
    os.remove(filename)

if __name__ == '__main__':
    test_save_to_file()

