def format_task_numbers_with_links(tasks, data={'asana-project': '123456789012'}):
    """Returns formatting for the tasks section of asana."""

    ASANA_SECTION_RE = re.compile(r'## Asana Tasks:\s+(.*#(\d{12,}))+', re.M)
