    uninitialized_pkey = PKey()
    uninitialized_pkey._pkey = None

    try:
        uninitialized_pkey.to_cryptography_key()
        assert False, "An exception should have been raised for uninitialized keys"
    except AttributeError:
        assert True, "AttributeError expected for uninitialized keys"

if __name__ == '__main__':
    test_to_cryptography_key()

