import random
import string
import math

class PJFMutators(object):

    def __init__(self, configuration):
        self.random_chars = string.printable[:-5]
        self.config = configuration

        self.string_mutator = {
            0: lambda x: False,
            1: lambda x: self.json_fuzzer(self.get_string_polyglot_attack(x)),
            6: lambda x: 0,
        }

        self.polyglot_attacks = {
            14: "".join(self.random_chars[random.randint(0, 94)]
                        for _ in range(0, random.randint(1, 30))).replace("%", "%%") + "%s"
        }

    def _get_random(self, obj_type):
        # The list of keys is not guaranteed to be sorted in Python < 3.7
        keys = sorted(self.string_mutator.keys())
        # Find the maximum key that is less than or equal to the level
        key = max(k for k in keys if k <= self.config.level)
        return self.string_mutator[key]

    def get_mutator(self, obj, obj_type):
        return self._get_random(obj_type)(obj)

    def get_string_polyglot_attack(self, obj):
        return self.polyglot_attacks[random.choice(self.config.techniques)] % obj

    def json_fuzzer(self, obj):
        buf = list(obj)
        # Ensure there's at least one character to fuzz
        if len(buf) == 0:
            return obj

        # Make sure FuzzFactor is never zero
        FuzzFactor = max(1, random.randrange(len(buf)))
        numwrites = random.randrange(math.ceil((float(len(buf)) / FuzzFactor))) + 1

        for j in range(numwrites):
            self.random_action(buf)
        return "".join(buf)

    def random_action(self, buf):
        # For the sake of this example, let's mimic a random action
        index = random.randint(0, len(buf) - 1)
        buf[index] = random.choice(self.random_chars)

class Config:
    def __init__(self, level, techniques):
        self.level = level
        self.techniques = techniques

def test__get_random():
    # Test the function three times to ensure reproducibility within randomness bounds
    for _ in range(3):
        # Level 0 - should always return False
        config_level_0 = Config(level=0, techniques=[14])
        pjf_level_0 = PJFMutators(configuration=config_level_0)
        assert pjf_level_0._get_random(str)("dummy") is False

        # Level 1 - cannot guarantee the exact return but should not return 0 or False
        config_level_1 = Config(level=1, techniques=[14])
        pjf_level_1 = PJFMutators(configuration=config_level_1)
        result_level_1 = pjf_level_1._get_random(str)("dummy")
        assert result_level_1 not in [False, 0, "dummy"]

        # Level 6 - should always return 0
        config_level_6 = Config(level=6, techniques=[14])
        pjf_level_6 = PJFMutators(configuration=config_level_6)
        assert pjf_level_6._get_random(str)("dummy") == 0

if __name__=='__main__':
    test__get_random()

