    bench_funcs = {
        'bm_one': lambda x: x,
        'bm_two': lambda x: x ** 2,
        'bm_python2': lambda x: x // 2,
    }
    setattr(bench_funcs['bm_python2'], '_python2_only', True)
    benchmarks = {'bm_one', 'bm_two', 'bm_python2'}

    # Test case 1: Exclude Python2-only benchmark for Python 3
    filtered_benchmarks = filter_benchmarks(benchmarks.copy(), bench_funcs, (3, 0))
    assert filtered_benchmarks == {'bm_one', 'bm_two'}

