import re

def check_frame_id(frame_id):
    """Check that the provided frame id is valid in Rapids language."""
    _id_allowed_characters = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")

    if frame_id is None:
        return
    if frame_id.strip() == "":
        raise ValueError("Frame id cannot be an empty string: %r" % frame_id)
    for i, ch in enumerate(frame_id):
        # '$' character has special meaning at the beginning of the string; and prohibited anywhere else
        if ch == "$" and i == 0: continue
        if ch not in _id_allowed_characters:
            raise ValueError("Character '%s' is illegal in frame id: %s" % (ch, frame_id))
    if re.match(r"-?[0-9]", frame_id):
        raise ValueError("Frame id cannot start with a number: %s" % frame_id)

def test_check_frame_id():
    # Test with a valid frame id
    assert check_frame_id("valid_frame_id") is None

    # Test with a frame id that starts with a number should raise ValueError
    try:
        check_frame_id("1invalid_frame_id")
    except ValueError as e:
        assert str(e) == "Frame id cannot start with a number: 1invalid_frame_id"
    else:
        assert False, "Expected ValueError for frame_id starting with a number"

    # Test with a frame id with illegal characters should raise ValueError
    try:
        check_frame_id("invalid_frame$id")
    except ValueError as e:
        assert "Character '$' is illegal in frame id: invalid_frame$id" in str(e)
    else:
        assert False, "Expected ValueError for frame_id with illegal character"

if __name__ == '__main__':
    test_check_frame_id()

