class InteractiveShell:
    exit_now = False

    def __init__(self):
        self.identifiers = {}

    def run_cell(self, raw_cell):
        try:
            compiled_code = compile(raw_cell, "<string>", "exec")
            exec(compiled_code, self.identifiers)
        except Exception as e:
            print("Error executing the code:", str(e))

    def raw_input(self, prompt=''):
        return input(prompt)

    def ask_exit(self):
        self.exit_now = True


class TerminalInteractiveShell(InteractiveShell):

    def interact(self, display_banner=None):

        if display_banner is not None:
            print(display_banner)

        while not self.exit_now:
            try:
                prompt = 'In [{}]: '.format(len(self.identifiers) + 1)
                line = self.raw_input(prompt)
            except EOFError:
                self.ask_exit()
            else:
                self.run_cell(line)

            if self.exit_now:
                print('Exiting the Interactive Shell.')

