class DirectoryStructure:
    def __init__(self, base, *args, **kwargs):
        self.base = base

    @classmethod
    def _create_directory(cls, directory, loop=False):
        if not loop and os.sep in directory:
            # The directory separator is in the given directory.
            # We split the directory separator.
            splited_directory = directory.split(os.sep)

            # We initiate a full path variable.
            full_path_to_create = ""

            for single_directory in splited_directory:
                # Loop through each directory and append to full path.
                full_path_to_create += single_directory + os.sep
                cls._create_directory(full_path_to_create, True)

        if not os.path.isdir(directory):
            # Create the directory if it does not exist.
            os.makedirs(directory, exist_ok=True)

    def create_directory_structure(self, structure):
        parent_path = list(structure.keys())[0]

        if not parent_path.endswith(os.sep):
            parent_path += os.sep

        structure = structure[parent_path]

        for directory in structure:
            base = self.base + parent_path + directory

            if not base.endswith(os.sep):
                base += os.sep

            self._create_directory(base)


