import collections

class OptionsProviderMixIn:
    """Mixin to provide options to an OptionsManager"""

    priority = -1
    name = "default"
    options = ()
    level = 0

    def __init__(self):
        # Create an empty class to simulate Option-like behavior
        self.config = type('Config', (object,), {})()
        self.load_defaults()

    def load_defaults(self):
        """initialize the provider using default values"""
        for opt, optdict in self.options:
            action = optdict.get("action")
            if action != "callback":
                if optdict is None:
                    optdict = self.get_option_def(opt)
                default = optdict.get("default")
                self.set_option(opt, default, action, optdict)

    def option_attrname(self, opt, optdict=None):
        if optdict is None:
            optdict = self.get_option_def(opt)
        return optdict.get("dest", opt.replace("-", "_"))

    def option_value(self, opt):
        return getattr(self.config, self.option_attrname(opt), None)

    def set_option(self, optname, value, action=None, optdict=None):
        """method called to set an option (registered in the options list)"""
        if optdict is None:
            optdict = self.get_option_def(optname)
        if value is not None:
            value = self.validate(value)
        if action is None:
            action = optdict.get("action", "store")
        if action == "store":
            if value is not None:  # Ensuring that value is not None before setting it
                setattr(self.config, self.option_attrname(optname, optdict), value)
        else:
            print("{} method is not supported".format(action))

    def validate(self, value):
        # Here is where validation of `value` would occur
        # Default interpretation is pass-thru
        return value

    def get_option_def(self, opt):
        """Return the dictionary defining an option given its name"""
        assert self.options
        for option in self.options:
            if option[0] == opt:
                return option[1]
        print(f"No such option {opt} in section {self.name}")

def test_set_option():
    provider = OptionsProviderMixIn()
    provider.options = [
        ("option1", {"action": "store", "dest": "option1_dest"}),
        ("option2", {"action": "store", "dest": "option2_dest"}),
        ("option3", {"action": "store", "dest": "option3_dest"}),
    ]

    # Setting an option that exists should reflect in the config Option instance
    provider.set_option("option1", "test_value1")
    assert getattr(provider.config, "option1_dest") == "test_value1"

    # Setting an option that does not exist with a default dest name derivation
    provider.set_option("option2", "test_value2")
    assert getattr(provider.config, "option2_dest") == "test_value2"

    # Verify that setting an option to `None` should not change the dest value
    current_value = getattr(provider.config, "option3_dest", "default")
    provider.set_option("option3", None)
    assert getattr(provider.config, "option3_dest", "default") == current_value

if __name__ == '__main__':
    test_set_option()

