    graph = Graph()

    # Before drawing, graph should have only one child
    assert len(graph.root.getchildren()) == 1

    label_height = graph.field_height()
    y_labels_count = len(graph.get_y_labels())
    graph.draw_y_guidelines(label_height, y_labels_count)

    # After drawing, graph should have one 'g' child plus the number of guidelines minus one since count starts from 1
    assert len(graph.root.getchildren()[0].getchildren()) == y_labels_count - 1

    # Check if the 'path' elements have the class 'guideLines'
    for guideline in graph.root.getchildren()[0].getchildren():
        assert 'class' in guideline.attrib and guideline.attrib['class'] == 'guideLines'


