import re

class ExpectationNotMet(Exception):
    pass

class CurrentPathQuery:
    def __init__(self, session, path, **kwargs):
        self.session = session
        self.path = path
        self.kwargs = kwargs

    def resolves_for(self):
        current_path = self.session.current_path
        if isinstance(self.path, str):
            return current_path == self.path
        elif hasattr(self.path, "search"):
            return bool(self.path.search(current_path))
        else:
            return False

    @property
    def failure_message(self):
        return f"expected current path to be {self.path}, but it is {self.session.current_path}"

    @property
    def negative_failure_message(self):
        return f"expected current path not to be {self.path}, but it is {self.session.current_path}"

class Document:
    @staticmethod
    def synchronize(func):
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

class Session:
    def __init__(self, current_path):
        self.current_path = current_path
        self.document = Document()

class SessionMatchersMixin(object):
    def assert_current_path(self, path, **kwargs):
        query = CurrentPathQuery(self, path, **kwargs)

        @self.document.synchronize
        def assert_current_path():
            if not query.resolves_for():
                raise ExpectationNotMet(query.failure_message)

        assert_current_path()

        return True

def test_assert_current_path():
    session = Session("/my-path")
    mixin = SessionMatchersMixin()
    mixin.document = session.document
    mixin.current_path = session.current_path

    # Test with exact path match
    assert mixin.assert_current_path("/my-path") == True

    # Test with regex path match
    assert mixin.assert_current_path(re.compile(r"/my-.*")) == True

    # Test assertion failure with non-matching path
    raised = False
    try:
        mixin.assert_current_path("/wrong-path")
    except ExpectationNotMet:
        raised = True
    assert raised == True

if __name__ == "__main__":
    test_assert_current_path()

