from collections.abc import MutableMapping

_VALID_NAME = re.compile('[A-z][A-z0-9_]*$')

class Bidict(MutableMapping):
    # Simplified Bidict class for testing purposes
    def __init__(self):
        self._fwd = {}
        self._bwd = {}

    def __getitem__(self, key):
        return self._fwd[key]

    def __setitem__(self, key, value):
        self._fwd[key] = value
        self._bwd[value] = key

    def __delitem__(self, key):
        value = self._fwd.pop(key)
        del self._bwd[value]

    def __iter__(self):
        return iter(self._fwd)

    def __len__(self):
        return len(self._fwd)

    @property
    def inverse(self):
        return self._bwd

def namedbidict(typename, keyname, valname, base_type=Bidict):
    if not issubclass(base_type, MutableMapping):
        raise TypeError(base_type)
    names = (typename, keyname, valname)
    if not all(map(_VALID_NAME.match, names)) or keyname == valname:
        raise ValueError(names)

    class _Named(base_type):
        __slots__ = ()
        def __reduce__(self):
            return (_make_empty, (typename, keyname, valname, base_type), None)

    _Named.__name__ = typename
    return _Named

def _make_empty(typename, keyname, valname, base_type):
    cls = namedbidict(typename, keyname, valname, base_type=base_type)
    return cls  # Change here: return the class itself, not an instance of it

