    serialized_configured_units = {}

    # Unit with custom serialize decision
    unit1 = Unit("unit1")
    unit1._serializeDecision = custom_serialize_decision
    ent1 = Entity("ent1", unit1)
    assert GenericSerializer.serializationDecision(ent1, serialized_classes, serialized_configured_units) is True

    # Unit without custom serialize decision
    unit2 = Unit("unit2")
    ent2 = Entity("ent2", unit2)
    assert GenericSerializer.serializationDecision(ent2, serialized_classes, serialized_configured_units) is True

    # Object that is neither Entity nor Architecture
    random_object = "some_string"
    assert GenericSerializer.serializationDecision(random_object, serialized_classes, serialized_configured_units) is True


def custom_serialize_decision(unit, obj, is_declaration, prev_priv):
