class LineInfo(object):
    """Simple class to store the information about an input line."""
    def __init__(self, line, continue_prompt=False):
        self.line = line
        self.continue_prompt = continue_prompt

class PrefilterChecker(object):
    """Base class for prefilter checkers."""

    def check(self, line_info):
        """Check a line of input and determine if it should be handled specially."""
        raise NotImplemented

class EscCharsChecker(PrefilterChecker):
    """Check for escape character handling."""

    def check(self, line_info):
        # Regular expressions for escape characters
        ESC_SHELL = '!'
        ESC_HELP = '?'
        # Check if the line ends with '?' and not a shell escape '!'
        if line_info.line.endswith(ESC_HELP) and not line_info.line.startswith(ESC_SHELL):
            return "Help requested for: " + line_info.line.strip(ESC_HELP)
        else:
            return None

def prefilter_line(line, continue_prompt):
    """Prefilter an input line."""
    line_info = LineInfo(line, continue_prompt)
    checker = EscCharsChecker()
    return checker.check(line_info)

def test_check():
    checker = EscCharsChecker()
    assert checker.check(LineInfo("hello?")) == "Help requested for: hello"
    assert checker.check(LineInfo("help?")) == "Help requested for: help"
    assert checker.check(LineInfo("!ls")) == None  # No special handling for lines starting with '!'

if __name__ == "__main__":
    test_check()

