class XiaomiGatewayDiscovery:
    MULTICAST_ADDRESS = '224.0.0.50'
    MULTICAST_PORT = 9898
    SOCKET_BUFSIZE = 1024

    def __init__(self):
        self._listening = False
        self._mcastsocket = None
        self._threads = []

    def _create_mcast_socket(self):
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        sock.settimeout(0.5)  # Here's the new timeout
        if platform.system() != "Windows":
            sock.bind((self.MULTICAST_ADDRESS, self.MULTICAST_PORT))
        else:
            sock.bind(('', self.MULTICAST_PORT))
        mreq = struct.pack("=4sl", socket.inet_aton(self.MULTICAST_ADDRESS), socket.INADDR_ANY)
        sock.setsockopt(socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP, mreq)
        return sock

    def listen(self):
        self._mcastsocket = self._create_mcast_socket()
        self._listening = True
        thread = Thread(target=self._listen_to_msg, args=())
        self._threads.append(thread)
        thread.daemon = True
        thread.start()

    def stop_listen(self):
        self._listening = False
        for thread in self._threads:
            thread.join()
        if self._mcastsocket is not None:
            try:
                self._mcastsocket.shutdown(socket.SHUT_RDWR)  # Shutdown before closing
            except:
                pass  # Handle any exceptions when shutting down
            self._mcastsocket.close()
            self._mcastsocket = None

    def _listen_to_msg(self):
        while self._listening:
            try:
                data, (ip_add, _) = self._mcastsocket.recvfrom(self.SOCKET_BUFSIZE)
                if data:
                    print("Received message:", data, "from", ip_add)
            except socket.timeout:
                pass  # Ignore timeouts and loop back to check if listening should stop

def test_stop_listen():
    discovery = XiaomiGatewayDiscovery()
    discovery.listen()  # Start listening to set up the socket and thread
    discovery.stop_listen()  # Stop listening should close the socket and join the thread

    assert not discovery._listening, "Listening flag was not set to False"
    assert discovery._mcastsocket is None, "Multicast socket was not closed"
    assert len(discovery._threads) == 0 or not discovery._threads[0].is_alive(), "Thread was not joined"

if __name__ == '__main__':
    test_stop_listen()

