        )

class CommandSession(object):
    def __init__(self, stream=False, env=None, cwd=None, force_shell=False):
        self.log = []
        self._stream = sys.stdout if stream else None
        self._env = env
        self._cwd = cwd
        self._shell = force_shell

    @property
    def last_returncode(self):
        try:
            return self.log[-1][1]
        except IndexError:
            raise RuntimeError('Nothing executed')

    @property
    def last_command(self):
        if not len(self.log):
            raise RuntimeError('Nothing executed')

        return self.log[-1][0]

    @property
    def last_output(self):
        if not len(self.log):
            raise RuntimeError('Nothing executed')

        return self.log[-1][2]

    def _stream_write(self, line):
        if self._stream:
            self._stream.write(line)
            self._stream.write(os.linesep)

    def _exec(self, cmd):
        shell = self._shell
        if isinstance(cmd, six.string_types):
            shell = True

        popen_kwargs = {
            'shell': shell,
            'stdout': subprocess.PIPE,
            'stderr': subprocess.STDOUT
        }
        if self._env:
            popen_kwargs['env'] = self._env

        if self._cwd:
            popen_kwargs['cwd'] = self._cwd

        p = subprocess.Popen(
            cmd, **popen_kwargs
        )

        output, _ = p.communicate()

        output = output.decode('utf-8').strip().splitlines()

        self._stream_write('\n'.join(output))

        log = [
            ' '.join(cmd) if isinstance(cmd, list) and not shell else cmd,
            p.returncode,
            '\n'.join(output) # Store it as single string as per required in the assert statement
        ]
        self.log.append(log)

        return p.returncode, '\n'.join(output)

    def check_call(self, cmd):
        ret, _ = self._exec(cmd)
        if ret != 0:
            raise CommandError(self)

        return ret

