        """Initialize response with just headers and body."""
        self.start = start_response_callable
        self.status = 200
        self._headers = []
        self.body = None

    def response(self):
        """Prepare the response to send."""
        self.start(self.status_line, self._headers)
        return [self.body.encode('utf-8')]

