try:
    text_type = unicode
except NameError:
    text_type = str

def u2str(data):
    """Recursively converts unicode objects to UTF-8 encoded byte strings."""
    if isinstance(data, dict):
        return {k: u2str(v) for k, v in data.items()}
    elif isinstance(data, list):
        return [u2str(x) for x in data]
    elif isinstance(data, text_type):
        return data.encode('utf-8')
    else:
        return data

def websafe_decode(data):
    if isinstance(data, text_type):
        data = data.encode('ascii')
    data += b'=' * (-len(data) % 4)
    return urlsafe_b64decode(data)

def websafe_encode(data):
    if isinstance(data, text_type):
        data = data.encode('ascii')
    return urlsafe_b64encode(data).replace(b'=', b'').decode('ascii')

def test_u2str():
    # Test with a dictionary
    test_dict = {'key1': 'value1', 'key2': u'value2', 'key3': {'subkey1': u'subvalue1'}}
    assert u2str(test_dict) == {'key1': b'value1', 'key2': b'value2', 'key3': {'subkey1': b'subvalue1'}}

    # Test with a list
    test_list = ['item1', u'item2', {'key4': u'value4'}]
    assert u2str(test_list) == [b'item1', b'item2', {'key4': b'value4'}]

    # Test with a string
    test_str = u'Test string'
    assert u2str(test_str) == b'Test string'

if __name__ == '__main__':
