class Similar:
    """finds copy-pasted lines of code in a project"""

    def __init__(
        self,
        min_lines=4,
        ignore_comments=False,
        ignore_docstrings=False,
        ignore_imports=False,
    ):
        self.min_lines = min_lines
        self.ignore_comments = ignore_comments
        self.ignore_docstrings = ignore_docstrings
        self.ignore_imports = ignore_imports
        self.linesets = []

    def append_stream(self, streamid, stream, encoding=None):
        """append a file to search for similarities"""
        if hasattr(stream, 'readlines'):
            lines = stream.readlines()
        else:
            lines = stream
        self.linesets.append(LineSet(streamid, lines, self.ignore_comments, self.ignore_docstrings, self.ignore_imports))

    def run(self):
        """start looking for similarities and display results on stdout"""
        self._display_sims(self._compute_sims())

    def _compute_sims(self):
        """compute similarities in appended files"""
        no_duplicates = defaultdict(list)
        for num, lineset1, idx1, lineset2, idx2 in self._iter_sims():
            duplicate = no_duplicates[num]
            for couples in duplicate:
                if (lineset1, idx1) in couples or (lineset2, idx2) in couples:
                    couples.add((lineset1, idx1))
                    couples.add((lineset2, idx2))
                    break
            else:
                duplicate.append({(lineset1, idx1), (lineset2, idx2)})
        sims = [(num, couples) for num, ensembles in no_duplicates.items() for couples in ensembles]
        sims.sort(reverse=True)
        return sims

    def _display_sims(self, sims):
        """display computed similarities on stdout"""
        for num, couples in sims:
            print(f"\n{num} similar lines in {len(couples)} files")
            for lineset, idx in sorted(couples):
                print(f"=={lineset.name}:{idx}")
                for line in lineset._real_lines[idx : idx + num]:
                    print(f"  {line.rstrip()}")

    def _iter_sims(self):
        for idx, lineset1 in enumerate(self.linesets[:-1]):
            for lineset2 in self.linesets[idx + 1:]:
                index1 = 0
                while index1 < len(lineset1):
                    skip = 1
                    for index2 in lineset2.find(lineset1[index1]):
                        num, skip = self._find_num_common(lineset1, index1, lineset2, index2)
                        if num > self.min_lines:
                            yield num, lineset1, index1, lineset2, index2
                    index1 += skip

    def _find_num_common(self, lineset1, index1, lineset2, index2):
        num = non_blank = 0
        skip = 1
        for ((_, line1), (_, line2)) in zip(lineset1.enumerate_stripped(index1), lineset2.enumerate_stripped(index2)):
            if line1 != line2:
                break
            if line1:
                non_blank += 1
            num += 1
        return num, max(skip, num)

class LineSet:
    def __init__(
        self,
        name,
        lines,
        ignore_comments=False,
        ignore_docstrings=False,
        ignore_imports=False
    ):
        self.name = name
        self._real_lines = lines
        self._stripped_lines = [line.strip() for line in lines]
        self._index = self._mk_index()

    def __getitem__(self, index):
        return self._stripped_lines[index]

    def enumerate_stripped(self, start_at=0):
        for idx in range(start_at, len(self._stripped_lines)):
            yield idx, self._stripped_lines[idx]

    def find(self, stripped_line):
        return self._index.get(stripped_line, ())

    def _mk_index(self):
        index = defaultdict(list)
        for line_no, line in enumerate(self._stripped_lines):
            if line:
                index[line].append(line_no)
        return index

