        self.annotated_params = {}
        self._has_self = False

        docstring = func.__doc__

        if inspect.isclass(func):
            if name is None:
                name = func.__name__

            func = func.__init__

            if hasattr(func, 'metadata'):
                self.annotated_params = func.metadata.annotated_params

        try:
            if sys.version_info.major >= 3:
                spec = inspect.getfullargspec(func)
                args, varargs, kwargs, defaults = spec[:4]
            else:
                args, varargs, kwargs, defaults = inspect.getargspec(func)

            if len(args) > 0 and args[0] == 'self':
                args = args[1:]
                self._has_self = True

            if defaults is None:
                defaults = []

            self.varargs = varargs
            self.kwargs = kwargs
            self.arg_names = args
            self.arg_defaults = defaults
        except TypeError:
            self.varargs = None
            self.kwargs = None
            self.arg_names = []
            self.arg_defaults = []

        self.return_info = ReturnInfo(None, None, False, None)

        if name is None:
