class Layout():
    """Two-ways dict to represent a Layout."""

    def __init__(self, input_dict=None):
        self._p2v = {}
        self._v2p = {}
        if input_dict is not None:
            self.from_dict(input_dict)

    @staticmethod
    def is_virtual(value):
        return value is None or isinstance(value, tuple) and len(value) == 2 and isinstance(value[0], Register) and isinstance(value[1], int)

    @staticmethod
    def from_tuplelist(tuple_list):
        out = Layout()
        for physical, virtual in enumerate(tuple_list):
            if virtual is None:
                continue
            elif Layout.is_virtual(virtual):
                if virtual in out._v2p:
                    raise LayoutError('Duplicate values not permitted; Layout is bijective.')
                out[virtual] = physical
            else:
                raise LayoutError("The list should contain elements of the form"
                                  " (Register, integer) or None")
        return out

    # The __setitem__ and __getitem__ methods are assumed to be part of the Layout class
    def __setitem__(self, key, value):
        self._p2v[key] = value
        self._v2p[value] = key

    def __getitem__(self, key):
        return self._p2v.get(key, None)

    # This method is added to aid the assertion in tests to verify the correctness.
    def get_virtual(self, value):
        return self._v2p.get(value, None)

    def __str__(self):
        return f"Physical to Virtual: {self._p2v}, Virtual to Physical: {self._v2p}"


