def date_default(obj):
    if isinstance(obj, datetime):
        return obj.isoformat()
    elif isinstance(obj, uuid.UUID):
        return str(obj)
    raise TypeError(f"Type {type(obj)} not serializable")

# Utility functions
def json_packer(obj):
    return jsonapi.dumps(obj, default=date_default)

def json_unpacker(s):
    return jsonapi.loads(s)

def pickle_packer(o):
    return pickle.dumps(o, -1)

def pickle_unpacker(s):
    return pickle.loads(s)

# Message header function
def msg_header(msg_id, msg_type, username, session):
    date = datetime.now()
    return locals()

# Session class
class Session:
    def __init__(self):
        self.pack = json_packer
        self.unpack = json_unpacker
        self.debug = False
        self.auth = None
        self.username = os.environ.get("USER", "username")
        self.session = str(uuid.uuid4())

    def msg(self, msg_type, content=None, parent=None, ident=None, subheader=None, header=None):
        msg = {}
        header = msg_header(uuid.uuid4(), msg_type, self.username, self.session) if header is None else header
        msg["header"] = header
        msg["msg_id"] = header["msg_id"]
        msg["msg_type"] = header["msg_type"]
        msg["parent_header"] = {} if parent is None else parent["header"]
        msg["content"] = {} if content is None else content

        return msg

    def send(self, stream, msg_or_type, content=None):
        if not isinstance(stream, zmq.Socket):
            raise TypeError("stream must be Socket, not %r" % type(stream))

        if isinstance(msg_or_type, dict):
            msg = msg_or_type
        else:
            msg = self.msg(msg_or_type, content=content)

        header = self.pack(msg["header"])
        parent_header = self.pack(msg["parent_header"])
        content = self.pack(msg["content"])

        stream.send_multipart([header, parent_header, content])
        return msg

# Test the Session.send function
def test_send():
    context = zmq.Context()
    socket = context.socket(zmq.PUSH)
    # Mock the send_multipart method of the socket to test send function
    socket.send_multipart = Mock()

    session = Session()
    msg = session.send(socket, "test_message", {"example_key": "example_value"})

    socket.send_multipart.assert_called_once()
    assert msg["header"]["msg_type"] == "test_message"
    assert "example_key" in msg["content"]
    assert msg["header"]["username"] == session.username

if __name__ == "__main__":
