                if old_ref:
                    self._update_ref(ref)
                else:
                    self.current_refs.append(ref)

        # Remove refs that are not in the new list
        for old_ref in self._discover_refs():
            if not old_ref.refname.startswith('refs/heads/'):
                continue
            if old_ref.refname not in new_refs_dict:
                self.current_refs = [r for r in self.current_refs if r.refname != old_ref.refname]

