from typing import Any, Callable, Generic, Optional, TypeVar

T = TypeVar("T")
DispatchFunction = Callable[..., T]
Method = Callable[..., Any]

class MultiFunction(Generic[T]):
    def __init__(self, name: str, dispatch: DispatchFunction, default: T) -> None:
        self._name = name
        self._default = default
        self._dispatch = dispatch
        self._methods = {}

    def __call__(self, *args, **kwargs):
        key = self._dispatch(*args, **kwargs)
        method = self._methods.get(key)
        if method:
            return method(*args, **kwargs)
        else:
            # If method is not found for the key, return the default value
            return self._default

    def add_method(self, key: T, method: Method) -> None:
        self._methods[key] = method

    def get_method(self, key: T) -> Optional[Method]:
        return self._methods.get(key)

    def remove_method(self, key: T) -> Optional[Method]:
        return self._methods.pop(key, None)

    def remove_all_methods(self) -> None:
        self._methods.clear()

    @property
    def default(self) -> T:
        return self._default

    @property
    def methods(self) -> dict:
        return self._methods

def multifn(dispatch: DispatchFunction, default=None) -> MultiFunction[T]:
    name = f"{dispatch.__module__}/{dispatch.__qualname__}"
    return MultiFunction(name, dispatch, default)

