class OptBucket(object):
    def __init__(self, doc=None, prog='nosetests'):
        self.opts = []
        self.doc = doc or ''
        self.prog = prog

    def __iter__(self):
        return iter(self.opts)

    def format_help(self):
        return self.doc.replace('%prog', self.prog).replace(':\n', '::\n')

    def add_option(self, *args, **kwargs):
        self.opts.append(Opt(*args, **kwargs))


class Opt(object):
    def __init__(self, *args, **kwargs):
        self.opts = args
        self.action = kwargs.pop('action', None)
        self.default = kwargs.pop('default', None)
        self.metavar = kwargs.pop('metavar', None)
        self.help = kwargs.pop('help', None)

    def options(self):
        options_description = []
        for optstring in self.opts:
            description = optstring
            if self.action not in ('store_true', 'store_false'):
                description += '=%s' % (self.metavar or 'VALUE')
            options_description.append(description)
        return '.. cmdoption :: ' + ', '.join(options_description)


def autohelp_directive():
