import os

class Directory:       
    def __init__(self, directory):
        self.directory = directory

    def fix_path(self, splited_path=None):
        if not splited_path:
            split_path = []
            if self.directory:
                if "/" in self.directory: split_path = self.directory.split("/")
                elif "\\" in self.directory: split_path = self.directory.split("\\")
                else: split_path = [self.directory]
                return self.fix_path(splited_path=[x for x in split_path if x])
            return self.directory
        return os.sep.join(splited_path) + os.sep

