class PJFMutation(object):
    """
    A class that represents a Mutation object used to mutate different types
    """

    def __init__(self, configuration):
        self.config = configuration

    def _mutate_obj(self, obj):
        if isinstance(obj, (int, float)):
            return obj + 1
        elif isinstance(obj, str):
            if len(obj) > 0:
                return obj[:-1]
            else:
                return "a"
        elif isinstance(obj, list):
            if len(obj) > 0:
                return obj[:-1]
            else:
                return [0]
        elif isinstance(obj, dict):
            if len(obj) > 0:
                return {k: v for k, v in obj.items() if k != list(obj.keys())[0]}
            else:
                return {0: 0}
        else:
            return obj

    def fuzz(self, obj):
        """
        Generic fuzz mutator, use a mutation for the given type
        """
        return self._mutate_obj(obj)

