    assert fuzzer.fuzz(3.5) == 4.5, "Failed to mutate float"
    assert fuzzer.fuzz("abc") == "ab", "Failed to mutate string"
    assert fuzzer.fuzz([1, 2, 3]) == [1, 2], "Failed to mutate list"
    assert fuzzer.fuzz({'a': 1, 'b': 2}) == {'b': 2}, "Failed to mutate dictionary"

