        self.name = name
        self.kwargs = kwargs
        self._params = []
        self._input_shapes = {}
        self._output_shapes = {}

    def find(self, key):
        name = '{}.{}'.format(self.name, key)
        for i, p in enumerate(self._params):
            if key == i or name == p.name:
                return p
        raise KeyError(key)


class Input(Layer):
    def __init__(self, name='in', **kwargs):
        super(Input, self).__init__(name=name, **kwargs)
        self.input = TT.matrix(name)

    def transform(self, inputs):
        return self.input, []


