    input_layer = Input(name="input1")
    np.random.seed(42)
    # Initialize weights with a known seed to have a reproducible test case
    w1 = np.random.normal(0, 1, (3, 3))
    # Create a Theano shared variable with a specific name
    p1 = theano.shared(w1, name="input1.0")
    input_layer._params = [p1]

    # Check if the find method correctly returns the parameter based on index
    assert input_layer.find(0) == p1, "Find by index failed."
    # Check if the find method correctly returns the parameter based on name
    assert input_layer.find("0") == p1, "Find by name failed."
    # Test that the appropriate exception is raised for a missing key
    try:
        input_layer.find("non_existent_key")
        assert False, "KeyError not raised."
