import sys
import os
import imp

MODULE_PATH_SEP = '.'


class LoaderError(ImportError):
    def __init__(self, msg):
        self.msg = msg


class ModuleLoader(object):
    def __init__(self, module_path, module_name, load_target, is_pkg):
        self.module_path = module_path
        self.module_name = module_name
        self.load_target = load_target
        self.is_pkg = is_pkg

    def load_module_py_path(self, module_name, path):
        file_ext = os.path.splitext(path)[1]
        module = None
        if file_ext.lower() == '.py':
            module = imp.load_source(module_name, path)
        elif file_ext.lower() == '.pyc':
            module = imp.load_compiled(module_name, path)

        return module

    def load_module(self, module_name):
        if module_name != self.module_name:
            raise LoaderError('Requesting a module that the loader is unaware of.')

        if module_name in sys.modules:
            return sys.modules[module_name]

        module = self.load_module_py_path(module_name, self.load_target)
        if self.is_pkg:
            module.__path__ = [self.module_path]
            module.__package__ = module_name
        else:
            module.__package__ = module_name.rpartition('.')[0]

        sys.modules[module_name] = module
        return module


class ModuleFinder(object):
    def __init__(self, paths=None):
        self.paths = paths if paths else list()

    def add_path(self, path):
        if path not in self.paths:
            self.paths.append(path)

    def find_module(self, module_name, path=None):
        module_path = os.path.join(*module_name.split(MODULE_PATH_SEP))

        for search_root in self.paths:
            target_path = os.path.join(search_root, module_path)
            is_pkg = False

            if os.path.isdir(target_path):
                target_file = os.path.join(target_path, '__init__.py')
                is_pkg = True
            else:
                target_file = '{}.py'.format(target_path)

            if os.path.exists(target_file):
                return ModuleLoader(target_path, module_name, target_file, is_pkg)
        return None


def test_add_path():
    finder = ModuleFinder()

    # Test initial state
    assert len(finder.paths) == 0, "Finder paths should be initially empty."

    test_path = '/some/test/path'
    another_test_path = '/another/test/path'

    # Add a path and check if it is added
    finder.add_path(test_path)
    assert test_path in finder.paths
    assert len(finder.paths) == 1, "Finder paths should contain one path."

    # Add another path and check if it also gets added
    finder.add_path(another_test_path)
    assert another_test_path in finder.paths
    assert len(finder.paths) == 2, "Finder paths should contain two paths."

    # Test adding a duplicate path (should not be added again)
    finder.add_path(test_path)
    assert finder.paths.count(test_path) == 1, "Duplicate paths should not be added."

    print("All tests for add_path passed.")


if __name__ == '__main__':
