def _iterate_flattened_values(value):
  if isinstance(value, str):
    yield value
    return

  if isinstance(value, dict):
    # Convert the dictionary values to a list for iteration.
    value = list(value.values())

  if isinstance(value, list):
    for nested_value in value:
      # Recursively yield from nested structures within the list.
      for nested_nested_value in _iterate_flattened_values(nested_value):
        yield nested_nested_value
    return  # This return statement ensures we don't yield the list itself

