import pandas as pd
import re  # Required for re.match in the search_features method

class FeatureTable(object):
    """ A FeatureTable instance stores a matrix of studies x features,
    along with associated manipulation methods. """

    def __init__(self, dataset):
        self.dataset = dataset
        self.data = pd.DataFrame()

    def add_features(self, features):
        if isinstance(features, pd.DataFrame):
            self.data = features
        else:
            raise ValueError("Input must be a pandas DataFrame")

    def search_features(self, search):
        if isinstance(search, str):
            search = [search]
        search = [s.replace('*', '.*') for s in search]
        cols = list(self.data.columns)
        results = []
        for s in search:
            results.extend([f for f in cols if re.match(s + '$', f)])
        return list(set(results))

def test_search_features():
    # Create a mock FeatureTable instance with some test data
    test_features = pd.DataFrame({
        'feature1': [1, 0, 1],
        'feature2': [0, 1, 0],
        'some_feature3': [1, 1, 1],
