import numpy as np

class QiskitError(Exception):
    pass

class BaseOperator:
    MAX_TOL = 1e-4

    def __init__(self, rep, data, input_dims, output_dims):
        self._rep = rep
        self._data = data
        self._input_dims = tuple(input_dims)
        self._output_dims = tuple(output_dims)
        self._input_dim = np.product(input_dims)
        self._output_dim = np.product(output_dims)

    def _reshape(self, input_dims=None, output_dims=None):
        if input_dims is not None:
            if np.product(input_dims) != self._input_dim:
                raise QiskitError(
                    "Reshaped input_dims are incompatible with combined input dimension."
                )
            self._input_dims = tuple(input_dims)
        if output_dims is not None:
            if np.product(output_dims) != self._output_dim:
                raise QiskitError(
                    "Reshaped output_dims are incompatible with combined output dimension."
                )
            self._output_dims = tuple(output_dims)
        return self

    def input_dims(self):
        return self._input_dims

    def output_dims(self):
        return self._output_dims


class SimpleOperator(BaseOperator):
    def __init__(self, data, input_dims, output_dims):
        super().__init__("simple", data, input_dims, output_dims)

def test__reshape():
    test_data = np.array([[1, 0], [0, 1]])
    input_dims = (2,)
    output_dims = (2,)

    operator = SimpleOperator(test_data, input_dims, output_dims)

    # Test reshaping to the same dimensions should be valid
    operator_reshaped = operator._reshape(input_dims=input_dims, output_dims=output_dims)
    assert operator_reshaped.input_dims() == input_dims
    assert operator_reshaped.output_dims() == output_dims

    # Test reshaping to the valid different dimensions
    new_input_dims = (1, 2)
    new_output_dims = (2, 1)
    operator_reshaped = operator._reshape(input_dims=new_input_dims, output_dims=new_output_dims)
    assert operator_reshaped.input_dims() == new_input_dims
    assert operator_reshaped.output_dims() == new_output_dims

    # Test reshaping with dimensions that don't match the size of the operator should raise QiskitError
    invalid_dims = (4,)
    try:
        operator_reshaped = operator._reshape(input_dims=invalid_dims)
    except QiskitError:
        pass
    else:
        raise AssertionError("Reshaping to invalid input dimensions did not raise QiskitError")

if __name__ == '__main__':
    test__reshape()

