            {'id': 4, 'course_id': 2, 'assignment_id': 3, 'user_id': 1, 'score': 100},
            {'id': 5, 'course_id': 2, 'assignment_id': 4, 'user_id': 2, 'score': 45},
        ]
        return submissions

    def _sis_id(self, sis_id, sis_type):
        if sis_type == 'section':
            return 1 if sis_id == 'sis_section_1' else None
        elif sis_type == 'course':
            return 1 if sis_id == 'sis_course_1' else 2

    def get_submissions_multiple_assignments(
            self, is_section, course_id, students=None, assignments=None,
            **params):
        data = self._get_paged_resource('', params=params)
        submissions = []

        for submission in data:
            if submission['course_id'] == course_id:
                if students is None or submission['user_id'] in students:
                    if assignments is None or submission['assignment_id'] in assignments:
                        submissions.append(Submission(data=submission))

        return submissions


