import re
from collections import Iterable
from itertools import islice

RE_UUID = '[a-z0-9]{8}-(?:[a-z0-9]{4}-){3}[a-z0-9]{12}'
UUID_WITH_EFFECTS_REGEX = re.compile(
    r'''
    (?P<uuid>{uuid})  # required
    (?:
        /
        (?:-/(?P<effects>.+))?/
        [^/]*  # filename
    )?
    '''.format(uuid=RE_UUID), re.VERBOSE)

GROUP_ID_REGEX = re.compile(
    r'(?P<group_id>[a-z0-9]{8}-(?:[a-z0-9]{4}-)[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{12}~\d+)', re.VERBOSE)

class File(object):
    """File resource for working with user-uploaded files."""

    def __init__(self, cdn_url_or_file_id):
        matches = UUID_WITH_EFFECTS_REGEX.match(cdn_url_or_file_id)
        if not matches:
            raise ValueError("Couldn't find UUID")
        self.uuid = matches.group('uuid')
        self.default_effects = matches.group('effects')

    def __repr__(self):
        return '<File {uuid}>'.format(uuid=self.uuid)

    @classmethod
    def construct_from(cls, file_info):
        """Constructs File instance from file information."""
        return cls(file_info['uuid'])

    # Minimalistic methods accessing instance properties (simplified examples).
    def get_cdn_url(self):
        """Returns file's CDN url."""
        return 'https://ucarecdn.com/{uuid}/'.format(uuid=self.uuid)


class FileGroup(object):
    """File Group resource for working with user-uploaded group of files."""

    def __init__(self, cdn_url_or_group_id):
        matches = GROUP_ID_REGEX.match(cdn_url_or_group_id)
        if not matches:
            raise ValueError("Couldn't find group id")
        self.id = matches.group('group_id')
        self.files = []

    def __repr__(self):
        return '<FileGroup {id}>'.format(id=self.id)

    @classmethod
    def construct_from(cls, group_info):
        """Constructs FileGroup instance from group information."""
        group = cls(group_info['id'])
        group.files = [File.construct_from(file_info) for file_info in group_info['files']]
        return group

    # Minimalistic methods accessing instance properties (simplified examples).
    def get_cdn_url(self):
        """Returns group's CDN url."""
        return 'https://ucarecdn.com/{group_id}/'.format(group_id=self.id)


def test_construct_from():
    # Test with valid file group information
    group_info = {
        'id': '0513dda0-582f-447d-846f-096e5df9e2bb~2',
        'files': [{'uuid': 'a771f854-c2cb-408a-8c36-71af77811f3b'}]
    }
    file_group = FileGroup.construct_from(group_info)
    assert file_group.id == group_info['id']
    assert len(file_group.files) == 1
    assert all(isinstance(file, File) for file in file_group.files)

    # Test where 'files' list is empty
    empty_group_info = {
        'id': '0513dda0-582f-447d-846f-096e5df9e2bb~3',
        'files': []
    }
    empty_file_group = FileGroup.construct_from(empty_group_info)
    assert empty_file_group.id == empty_group_info['id']
    assert len(empty_file_group.files) == 0

    # Test with multiple files
    multi_file_info = {
        'id': '0513dda0-582f-447d-846f-096e5df9e2bb~4',
        'files': [
            {'uuid': 'a771f854-c2cb-408a-8c36-71af77811f3b'},
