import uuid
import os
import collections

def get_type_level(value):
    if value is None:  # lowest type
        return 0

    if isinstance(value, str):
        return 1

    if isinstance(value, (int, float)):  # highest type
        return 2

    raise AssertionError(f"type not managed: {type(value)} ({value})")

class Record:

    def __init__(self, table, data=None):
        self._table = table
        self._data = {}

        if data is not None:
            self._update_inert(data)

    def _field_key_to_index(self, ref_or_index):
        if isinstance(ref_or_index, int):
            return ref_or_index
        return self._table._dev_descriptor.get_field_index(ref_or_index)

    def _update_inert(self, data):
        data = dict([(self._field_key_to_index(k), v) for (k, v) in data.items()])

        for k, v in sorted(data.items()):
            self._update_value_inert(k, v)

    def _update_value_inert(self, index, value):
        self._data[index] = value

    def get_serialized_value(self, ref_or_index):
        index = (
            self._table._dev_descriptor.get_field_index(ref_or_index) if isinstance(ref_or_index, str)
            else ref_or_index
        )
        value = self._data.get(index)
        return value

    def to_json_data(self, model_name=None):
        return collections.OrderedDict([(k, self.get_serialized_value(k)) for k in self._data])

class MockDevDescriptor:
    def get_field_index(self, field_ref):
        return field_ref  # In this mock, simply return the field reference as the index.

class MockTable:
    def __init__(self):
        self._dev_descriptor = MockDevDescriptor()

def test_to_json_data():
    # Mock data and table with descriptor set up for testing
    dummy_table = MockTable()

    # Record with an integer and string field
    record1 = Record(dummy_table, data={'field1': 123, 'field2': 'test'})
    assert record1.to_json_data() == collections.OrderedDict([('field1', 123), ('field2', 'test')])

    # Record with a None value
    record2 = Record(dummy_table, data={'field3': None})
    assert record2.to_json_data() == collections.OrderedDict([('field3', None)])

    # Record with multiple types of fields
    record3 = Record(dummy_table, data={'field4': 456, 'field5': 78.9, 'field6': 'hello'})
    assert record3.to_json_data() == collections.OrderedDict([('field4', 456), ('field5', 78.9), ('field6', 'hello')])

if __name__ == '__main__':
    test_to_json_data()

