class QuitCommand:
    def nothread_quit(self, arg):
        raise Exception("Quit")

    def threaded_quit(self, arg):
        threading_list = threading.enumerate()
        mythread = threading.currentThread()
        for t in threading_list:
            if t != mythread:
                try:
                    ctype_async_raise(t, Exception("Quit"))
                except ValueError:
                    pass
        raise Exception("Quit")

    def run(self, args):
        confirmed = True  # We assume we have confirmation to avoid user input requirement.
        if confirmed:
            threading_list = threading.enumerate()
            if len(threading_list) == 1 and threading_list[0].getName() == 'MainThread':
                return self.nothread_quit(args)
            else:
                return self.threaded_quit(args)
        return

