import json

class JSONData(object):

    def __init__(self, filename, version=None):
        self.version = version
        self.filename = filename
        self.data = {}

    def apply(self, key, value=None, prompt=None,
              on_load=lambda a: a, on_save=lambda a: a):

        # Check if an empty value is provided to delete the key
        if value == '':
            if key in self.data:
                del self.data[key]
            return None

        if value is not None:
            value = on_load(value)
            if key:
                self.data[key] = on_save(value)
            return value
        elif not key or key not in self.data:
            if callable(prompt):
                value = prompt()
            # Removed the NotImplementedError line as it's no longer necessary
            self.data[key] = on_save(value)
            return value

        return on_load(self.data[key])


def test_apply():
    # Mock the open function to avoid file I/O.
    json_data = JSONData('test.json')
    json_data.data = {
        "test_key": "test_value"
    }

    # Test updating an existing key
    assert json_data.apply('test_key', 'new_value') == 'new_value'
    assert json_data.data['test_key'] == 'new_value'

    # Test inserting a new key
    assert json_data.apply('new_key', 'new_entry') == 'new_entry'
