class SkypeConnection:
    Auth = type('SkypeEnumAuth', (), {"SkypeToken": 1, "Authorize": 2, "RegToken": 3})

    def __init__(self):
        self.tokens = {}
        self.tokenExpiry = {}
        self.sess = requests.Session()

    def __call__(self, method, url, codes=(200, 201, 202, 204, 207), auth=None, **kwargs):
        if not kwargs.get('headers'):
            kwargs['headers'] = {}
        if auth == self.Auth.SkypeToken:
            kwargs['headers']["X-SkypeToken"] = self.tokens["skype"]
        elif auth == self.Auth.Authorize:
            kwargs['headers']["Authorization"] = "skype_token {0}".format(self.tokens["skype"])
        elif auth == self.Auth.RegToken:
            kwargs['headers']["RegistrationToken"] = self.tokens["reg"]

        resp = self.sess.request(method, url, **kwargs)

        if resp.status_code not in codes:
            raise Exception("{0} response from {1} {2}".format(resp.status_code, method, url), resp)
        return resp


class SkypeRegistrationTokenProvider:
    def __init__(self, conn):
        self.conn = conn

    def auth(self, skypeToken):
        token, expiry = 'dummy_reg_token', datetime.max
        return token, expiry, None, None


class SkypeApiClient(SkypeConnection):
    API_LOGIN = "https://login.skype.com/login"

    def __init__(self):
        super(SkypeApiClient, self).__init__()
        self.getSkypeToken = MethodType(self.dummy_getSkypeToken, self)

    def dummy_getSkypeToken(self):
        self.tokens["skype"], self.tokenExpiry["skype"] = 'dummy_skype_token', datetime.max

    def getRegToken(self):
        self.getSkypeToken()
        token, expiry, _, _ = SkypeRegistrationTokenProvider(self).auth(self.tokens["skype"])
        self.tokens["reg"], self.tokenExpiry["reg"] = token, expiry

