    def __init__(self):
        self._previous_prompt_obj = None
        self._prompt = None

    def _show_prompt(self, prompt: str, html=False):
        self._prompt = prompt
        print(prompt, end='')

    def _show_interpreter_prompt_for_reply(self, msg: dict):
        content = msg.get('content', {})
        if content['status'] == 'aborted':
            if self._previous_prompt_obj:
                previous_prompt_number = self._previous_prompt_obj.number
            else:
                previous_prompt_number = 0
        else:
            previous_prompt_number = content['execution_count']

        if self._previous_prompt_obj and \
                self._previous_prompt_obj.number != previous_prompt_number:
            block = self._previous_prompt_obj.block

            if block.isValid() and block.text():
                self._prompt = self._make_in_prompt(previous_prompt_number)

        # Replace the incorrect call with _show_prompt
        new_prompt = self._make_in_prompt(previous_prompt_number + 1)
        self._show_prompt(new_prompt)

    def _make_in_prompt(self, number: int) -> str:
        return f"In [{number}]: "

    def set_previous_prompt_obj(self, prompt: Tuple[int, str]):
