import uuid

class MockKernelManager:
    base_port = 12345  # Base port number that will be incremented for each kernel

    def __init__(self):
        # Increment ports from the base port number for each new kernel
        self.shell_port = MockKernelManager.base_port
        self.iopub_port = MockKernelManager.base_port + 1
        self.stdin_port = MockKernelManager.base_port + 2
        self.hb_port = MockKernelManager.base_port + 3
        # Increment the base port for the next kernel that will be created
        MockKernelManager.base_port += 4

class MultiKernelManager:
    def __init__(self):
        self._kernels = {}

    def start_kernel(self):
        kernel_id = str(uuid.uuid4())
        self._kernels[kernel_id] = MockKernelManager()
        return kernel_id

    def get_kernel(self, kernel_id):
        km = self._kernels.get(kernel_id)
        if km is not None:
            return km
        else:
            raise KeyError("Kernel with id not found: %s" % kernel_id)

    def get_kernel_ports(self, kernel_id):
        km = self.get_kernel(kernel_id)
        return {
            'shell_port': km.shell_port,
            'iopub_port': km.iopub_port,
            'stdin_port': km.stdin_port,
            'hb_port': km.hb_port,
        }

def test_get_kernel_ports():
    manager = MultiKernelManager()
    # Start a kernel and get the kernel_id
    kernel_id = manager.start_kernel()
    km = manager.get_kernel(kernel_id)

    # Get the ports and validate them
    ports = manager.get_kernel_ports(kernel_id)

    for port_name in ports:
        expected_port = getattr(km, port_name)
        assert ports[port_name] == expected_port, f"Expected {port_name} to be {expected_port}, got {ports[port_name]}"

    # Test a non-existent kernel
    try:
        manager.get_kernel_ports("invalid-id")
        assert False, "Expected a KeyError for a non-existent kernel id"
    except KeyError:
        pass  # Test passed as KeyError is expected

    # Start another kernel to ensure that each kernel has separate ports (assuming port numbers are sequential for simplicity)
    new_kernel_id = manager.start_kernel()
    new_km = manager.get_kernel(new_kernel_id)
    new_ports = manager.get_kernel_ports(new_kernel_id)

    for port_name in new_ports:
        expected_new_port = getattr(new_km, port_name)
        assert new_ports[port_name] == expected_new_port, f"Expected {port_name} to be {expected_new_port}, got {new_ports[port_name]}"
        assert new_ports[port_name] != ports[port_name], f"Expected different ports for new kernel, but got same for {port_name}"

if __name__ == "__main__":
    test_get_kernel_ports()

