    assert safe_decode(sample_utf8, "utf-8") == "Hello, World! ☃"

    # Test decoding with Latin-1 encoding
    assert safe_decode(sample_latin1, "latin-1") == "Hello, Mundo! ¡"

    # Test decoding with a default encoding when an invalid one is provided
    # Since it depends on the system default encoding, we cannot assume a certain output.
    # Therefore, we only check if it does not raise an exception.
    try:
        safe_decode(sample_utf8, "invalid_encoding")
        assert True  # If it doesn't raise an exception, pass the test
    except Exception:
        assert False  # If it raises any exception, fail the test

if __name__ == "__main__":
    test_safe_decode()

