    # _TestCaseB starts with '_', even though it's a unittest.TestCase subclass, it should not be wanted.
    assert selector.wantClass(_TestCaseB) == False

    # SimpleClass is not a unittest.TestCase subclass and does not match test name requirements, also has __test__ == False, so it should not be wanted.
    assert selector.wantClass(SimpleClass) == False

