    # Test the Prefix.real function with negative operator
    operator_node_neg = UnaryOperator('-')
    expression_node = Expression('3.14')
    prefix_expression_neg = Prefix([operator_node_neg, expression_node])
    assert prefix_expression_neg.real() == -3.14

    # Test the Prefix.real function with positive operator (identity)
    operator_node_pos = UnaryOperator('+')
    prefix_expression_pos = Prefix([operator_node_pos, expression_node])
    assert prefix_expression_pos.real() == 3.14

