import json


def ensurelist(data):
    return [data] if not isinstance(data, list) else data


def make_data_response(data, status=200):
    ''' Return a response with a list of jsonapi data objects
    '''
    content = {'data': ensurelist(data)}
    return json.dumps(content), status


def test_make_data_response():
    # Test a single dictionary, expected to be wrapped in a list
    single_data = {'id': 1, 'type': 'event', 'attributes': {'status': 'upcoming'}}
    response, status = make_data_response(single_data)
    assert json.loads(response) == {'data': [single_data]}
    assert status == 200

    # Test a list of dictionaries, which should be unchanged
    list_data = [
        {'id': 1, 'type': 'event', 'attributes': {'status': 'upcoming'}},
        {'id': 2, 'type': 'event', 'attributes': {'status': 'completed'}}
    ]
    response, status = make_data_response(list_data)
    assert json.loads(response) == {'data': list_data}
    assert status == 200

    # Test status code customization
    custom_status = 404
    response, status = make_data_response(single_data, custom_status)
    assert status == custom_status


