    packed_point_record_success = PackedPointRecord.from_stream(stream_success, point_format, 2)
    assert len(packed_point_record_success) == 2, "from_stream should successfully create two point records"

    # Test for handling an empty buffer
    stream_empty = io.BytesIO(b'')
    try:
        packed_point_record_empty = PackedPointRecord.from_stream(stream_empty, point_format, 1)
    except ValueError as e:
        assert str(e) == "The byte stream does not contain enough bytes.", "from_stream should raise a ValueError for an empty buffer."

    # Test for handling a partially filled buffer
