from base64 import urlsafe_b64encode
import binascii
import os
import json

class TokenMixin(object):
    """Mix-in class for token serializers."""

    def dumps(self, data):
        """Serialize data to JSON formatted str."""
        return json.dumps(data)

    def loads(self, data):
        """Deserialize data from JSON formatted str."""
        return json.loads(data)

    def create_token(self, obj_id, extra_data):
        """Create a token referencing the object id with extra data."""
        return self.dumps(
            dict(
                id=obj_id,
                data=extra_data,
                rnd=binascii.hexlify(os.urandom(4)).decode('utf-8')
            )
        )

    def validate_token(self, token, expected_data=None):
        """Validate secret link token."""
        try:
            data = self.load_token(token)
            if expected_data:
                for k in expected_data:
                    if expected_data[k] != data["data"].get(k):
                        return None
            return data
        except BadData:
            return None

    def load_token(self, token, force=False):
        pass

class EncryptedTokenMixIn(TokenMixin):
    """Mix-in class for token serializers that generate encrypted tokens."""

    def __init__(self, secret_key, digest_algorithm='HS256'):
        self._secret_key = secret_key
        self._digest_algorithm = digest_algorithm

    @property
    def engine(self):
        """Get cryptographic engine."""
        if not hasattr(self, '_engine'):
            from cryptography.fernet import Fernet
            from cryptography.hazmat.backends import default_backend
            from cryptography.hazmat.primitives import hashes

            digest = hashes.Hash(hashes.SHA256(), backend=default_backend())
            digest.update(self._secret_key.encode('utf8'))
            fernet_key = urlsafe_b64encode(digest.finalize())
            self._engine = Fernet(fernet_key)
        return self._engine

    def create_token(self, obj_id, extra_data):
        """Create a token referencing the object id with extra data."""
        token_data = super(EncryptedTokenMixIn, self).create_token(obj_id, extra_data)
        return self.engine.encrypt(token_data.encode('utf-8'))

    def load_token(self, token, force=False):
        """Load data in a token."""
        decrypted_token = self.engine.decrypt(token).decode('utf-8')
        return super(EncryptedTokenMixIn, self).loads(decrypted_token)

def test_create_token():
    secret_key = 'abcdefgh'
    digest_algorithm = 'HS256'
    obj_id = "123"
    extra_data = {"key": "value"}

    mixin = EncryptedTokenMixIn(secret_key, digest_algorithm)

    # Test that a token can be created
    token = mixin.create_token(obj_id, extra_data)
    assert token is not None, "The token should not be None"

    # Test that the token is not equal to the plaintext data
    assert token != f"{obj_id}{extra_data}", "The token should be encrypted and different from the plaintext data"

    # Test that decrypting the created token retrieves the original data
    decrypted = mixin.load_token(token)
    assert decrypted == {"id": obj_id, "data": extra_data, "rnd": decrypted['rnd']}, "Decrypting the token should retrieve the original data"

if __name__ == "__main__":
    test_create_token()

