from astroid import nodes

def decorated_with(func, qnames):
    """Determine if the `func` node has a decorator with the qualified name `qname`."""
    if not hasattr(func, 'decorators') or not func.decorators:
        return False
    for decorator in func.decorators.nodes:
        if isinstance(decorator, nodes.Name) and decorator.name in qnames:
            return True
    return False

