from signal import SIGTERM, SIGINT

class Launcher:
    def notify(self, data):
        print(data)

    def on_stop(self, data):
        print(f"Process exited: {data}")

class LocalProcessLauncher(Launcher):
    def __init__(self):
        self.process = None

    def start(self):
        print("Starting process")
        self.process = subprocess.Popen(["echo", "hello"], stdout=subprocess.PIPE)
        self.notify(f"Process {self.process.pid} started")

    def interrupt_then_kill(self, delay=1.0):
        try:
            print("Sending interrupt signal")
            self.process.send_signal(SIGINT)
        except Exception:
            print("Interrupt failed")
            try:
                print("Killing process")
                self.process.send_signal(SIGTERM)
            except Exception:
                print("Kill failed")

    def stop(self):
        print("Stopping process")
        self.interrupt_then_kill()
        self.process.wait()
        self.on_stop({'exit_code': self.process.returncode, 'pid': self.process.pid})

class LocalEngineSetLauncher(LocalProcessLauncher):
    def __init__(self, n):
        self.launchers = []
        for _ in range(n):
            launcher = LocalProcessLauncher()
            self.launchers.append(launcher)

    def start(self):
        print("Starting set of processes")
        for launcher in self.launchers:
            launcher.start()

    def interrupt_then_kill(self, delay=1.0):
        for launcher in self.launchers:
            launcher.interrupt_then_kill(delay)

    def stop(self):
        print("Stopping set of processes")
        for launcher in self.launchers:
            launcher.stop()

def test_start():
    num_processes = 3
    launcher_set = LocalEngineSetLauncher(num_processes)
    launcher_set.start()

    # Assert that the number of launcher processes is as expected
    assert len(launcher_set.launchers) == num_processes, "Incorrect number of launchers initiated."

    # Assert that each launcher has a process that is actually started
    for launcher in launcher_set.launchers:
        assert launcher.process is not None, "Process was not started."
        assert launcher.process.pid is not None, "Process has no PID."

    launcher_set.stop()  # Stop processes after testing

if __name__ == '__main__':
    test_start()

