class Image(object):
    def __init__(self, width=None, height=None, content_scale=None, handle=None):
        self._handle = handle
        self._width = width
        self._height = height
        self._content_scale = content_scale

    def get_region(self, x1, y1, x2, y2):
        handle = c_int()
        # Ensuring x2 and y2 do not exceed the image boundaries by using min function
        x2 = min(x2, self._width)
        y2 = min(y2, self._height)
        return Image(width=x2 - x1, height=y2 - y1, content_scale=self._content_scale, handle=handle)

    @property
    def width(self):
        return self._width

    @property
    def height(self):
        return self._height

    @property
    def content_scale(self):
        return self._content_scale

    @property
    def handle(self):
        return self._handle

