class Dict:
    """
    Dictionary manipulations.

    :param main_dictionary: The dict we are working with.
    :type main_dictionary: dict
    """

    def __init__(self, main_dictionary=None):
        if main_dictionary is None:
            # A dictionary is not parsed.

            # We set the main dictionary as an empty dictionary.
            self.main_dictionary = {}
        else:
            # A dictionary is parsed.

            # We set the main dictionary as the parsed dictionary.
            self.main_dictionary = main_dictionary

    def remove_key(self, key_to_remove):
        """
        Remove a given key from a given dictionary.

        :param key_to_remove: The key(s) to delete.
        :type key_to_remove: list|str

        :return: The dict without the given key(s).
        :rtype: dict|None
        """

        if isinstance(self.main_dictionary, dict):
            # The main dictionary is a dictionary

            if isinstance(key_to_remove, list):
                # The parsed key to remove is a list.

                for key in key_to_remove:
                    # We loop through the list of key to remove.

                    # We delete the key from the dictionary.
                    self.main_dictionary.pop(key, None)
            else:
                # The parsed key to remove is not a list.

                # We delete the given key from the dictionary.
                self.main_dictionary.pop(key_to_remove, None)

            # We return the final dictionary.
            return self.main_dictionary

        # The main dictionary is not a dictionary.

        # We return None.
        return None

