class Receiver:
    def __init__(self):
        self.running = False
        self.last_received = None
        self._used = threading.Event()
        self.receiver_shutdown = False

    def _can_run(self):
        if self._used.is_set():
            raise Exception("Receiver has already closed.")
        if self.receiver_shutdown:
            raise Exception("Receiver has already closed.")
        if not self.running:
            self.open()

    def open(self):
        self.running = True

    def close(self):
        self.running = False
        self.receiver_shutdown = True
        self._used.set()

    def fetch_next(self, max_batch_size=None, timeout=None):
        self._can_run()
        time.sleep(1)  # Simulate receiving messages
        return [f"Message {i}" for i in range(max_batch_size)]


def test_fetch_next():
    receiver = Receiver()
    assert len(receiver.fetch_next(max_batch_size=5)) == 5
    assert len(receiver.fetch_next(max_batch_size=10)) == 10
    assert receiver.fetch_next(max_batch_size=3)[-1] == "Message 2"
    receiver.close()


if __name__ == "__main__":
    test_fetch_next()

