import ctypes
import io

NULL_BYTE = b"\x00"


class RawVLRHeader(ctypes.LittleEndianStructure):
    _fields_ = [
        ("_reserved", ctypes.c_uint16),
        ("user_id", ctypes.c_char * 16),
        ("record_id", ctypes.c_uint16),
        ("record_length_after_header", ctypes.c_uint16),
        ("description", ctypes.c_char * 32),
    ]

    @classmethod
    def from_stream(cls, stream):
        return cls.from_buffer(bytearray(stream.read(ctypes.sizeof(cls))))

VLR_HEADER_SIZE = ctypes.sizeof(RawVLRHeader)
MAX_VLR_RECORD_DATA_LEN = (1 << 16) - 1  # Max value of ctypes.c_uint16


class RawVLR:

    def __init__(self):
        self.header = RawVLRHeader()
        self.record_data = b""

    @property
    def record_data(self):
        return self._record_data

    @record_data.setter
    def record_data(self, value):
        if len(value) > MAX_VLR_RECORD_DATA_LEN:
            raise OverflowError(
                "VLR record data length ({}) exceeds maximum ({})".format(len(value), MAX_VLR_RECORD_DATA_LEN)
            )
        self.header.record_length_after_header = len(value)
        self._record_data = value

    def size_in_bytes(self):
        return VLR_HEADER_SIZE + self.header.record_length_after_header

    def write_to(self, out):
        out.write(bytes(self.header))
        out.write(self.record_data)

    @classmethod
    def read_from(cls, data_stream):
        raw_vlr = cls()
        header = RawVLRHeader.from_stream(data_stream)
        raw_vlr.header = header
        raw_vlr.record_data = data_stream.read(header.record_length_after_header)
        return raw_vlr

    def __repr__(self):
        return "<RawVLR(user_id: {}, record_id: {}, len: {})>".format(
            self.header.user_id,
            self.header.record_id,
            self.header.record_length_after_header,
        )

def test_write_to():
    raw_vlr = RawVLR()
    raw_vlr.header.user_id = b"test_user_id\x00\x00\x00"  # Should be 16 chars
    raw_vlr.header.record_id = 42
    raw_vlr.header.description = b"test_description\x00\x00\x00\x00\x00\x00\x00"  # Should be 32 chars
    raw_vlr.record_data = b"some_binary_data"

    with io.BytesIO() as f:
        raw_vlr.write_to(f)
        f.seek(0)
        output = f.getvalue()

        assert len(output) == raw_vlr.size_in_bytes(), "Incorrect size for resulting byte string"
        assert output[:VLR_HEADER_SIZE] == bytes(raw_vlr.header), "Header not written correctly"
        assert output[VLR_HEADER_SIZE:] == raw_vlr.record_data, "Record data not written correctly"

if __name__ == "__main__":
    test_write_to()

