    defaults = {
        "push": {
            "pull_repo": True,
            "actions": ["echo 'push'"]
        }
    }

    config = {
        "token": "1234",
        "directory": "/tmp",
        "push": {
            "actions": ["echo 'extra push action'"]
        }
    }

    command_set = CommandSet.from_yaml(defaults, **config)
    assert command_set.token == "1234"
    assert command_set.directory == "/tmp"
    assert command_set.push.actions == ["echo 'push'", "echo 'extra push action'"]

if __name__ == "__main__":
