import urllib.parse
from unittest import mock

class RestSession(object):
    def __init__(self, access_token, base_url):
        self._base_url = base_url
        self._access_token = access_token
        self._req_session = requests.session()
        self.update_headers({'Authorization': 'Bearer ' + access_token,
                             'Content-type': 'application/json;charset=utf-8'})

    def update_headers(self, headers):
        self._req_session.headers.update(headers)

    def abs_url(self, url):
        parsed_url = urllib.parse.urlparse(url)
        if not parsed_url.scheme and not parsed_url.netloc:
            return urllib.parse.urljoin(self._base_url, url)
        else:
            return url

    def request(self, method, url, **kwargs):
        abs_url = self.abs_url(url)
        response = self._req_session.request(method, abs_url, **kwargs)
        return response

    def delete(self, url, **kwargs):
        return self.request('DELETE', url, **kwargs)

def test_delete():
    access_token = "your_access_token_here"
    base_url = "https://api.example.com/v1/"
    session = RestSession(access_token, base_url)

    with mock.patch("requests.Session.request") as mock_request:
        mock_request.return_value.status_code = 204
        response = session.delete("test_endpoint")
        assert response.status_code == 204

        mock_request.return_value.status_code = 404
        response = session.delete("invalid_endpoint")
        assert response.status_code == 404

        mock_request.return_value.status_code = 401
        response = session.delete("unauthorized_endpoint")
        assert response.status_code == 401

if __name__=='__main__':
    test_delete()

