import logging
from tornado import gen, ioloop

# Define query_params decorator before using it
def query_params(*args, **kwargs):
    def _wrapper(func):
        def _wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return _wrapped
    return _wrapper

class MockTransport:
    @gen.coroutine
    def perform_request(self, method, url, params=None, body=None):
        raise gen.Return((200, {}))

class AsyncElasticsearch:
    def __init__(self):
        self.transport = MockTransport()

    # Use query_params decorator
    @gen.coroutine
    @query_params()
    def clear_scroll(self, scroll_id, params=None):
        if not isinstance(scroll_id, list):
            scroll_id = [scroll_id]

        body = {
            "scroll_id": scroll_id
        }

        if params and "scroll_id" in params.keys():
            params.pop("scroll_id")

        response = yield self.transport.perform_request('DELETE',
                                                       '/_search/scroll',
                                                       body=body,
                                                       params=params)
        raise gen.Return(response)  # Return the entire response (status_code, data)

@gen.coroutine
def test_clear_scroll():
    es = AsyncElasticsearch()
    result = yield es.clear_scroll(scroll_id='dummy_scroll_id')
    assert result == (200, {}), "Clear scroll failed"

    result = yield es.clear_scroll(scroll_id=['dummy_scroll_id_1', 'dummy_scroll_id_2'])
    assert result == (200, {}), "Clear scroll failed"

    result = yield es.clear_scroll(scroll_id=[])
    assert result == (200, {}), "Clear scroll failed"

if __name__=='__main__':
    ioloop.IOLoop.current().run_sync(test_clear_scroll)

