from marshmallow.validate import Validator

class BaseModelTypeValidator(Validator):
    """Validator for checking the type of a model."""

    def _not_expected_type(self, value, expected_types, fields, field_names, data):
        return ValidationError(
            f'Value "{value}" is not valid for field "{field_names}" of type "{type(value).__name__}"; expected types are "{expected_types}".',
            field_names=field_names)

    def check_type(self, value, field_names=None, data=None):
        raise NotImplementedError

class ModelTypeValidator(BaseModelTypeValidator):
    """Validator for checking the type of a model instance."""

    default_error_messages = {
        'invalid': '{value} is not a valid {model_cls}.'
    }

    def __init__(self, model_cls, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.model_cls = model_cls
        self.expected_types = (model_cls,)

    def check_type(self, value, field_names=None, data=None):
        if not isinstance(value, self.model_cls):
            raise self._not_expected_type(
                value, self.expected_types, fields=[self], field_names=field_names, data=data)

        return value

    def __call__(self, value, field_names=None, data=None):
        return self.check_type(value, field_names, data)

class ByType(BaseModelTypeValidator):
    """Validator for checking the type of a field based on a list of types."""

    default_error_messages = {
        'invalid': 'Value {value} does not fit any of the types {types}.'
    }

    def __init__(self, choices, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.choices = [ModelTypeValidator(choice) for choice in choices]

    def check_type(self, value, field_names=None, data=None):
        for validator in self.choices:
            try:
                return validator.check_type(value, field_names, data)
            except ValidationError:
                continue
        raise self._not_expected_type(
            value, [v.model_cls for v in self.choices],
            fields=self.choices, field_names=field_names, data=data)

    def __call__(self, value, field_names=None, data=None):
        return self.check_type(value, field_names, data)

def test_check_type():
    by_type = ByType([int, list, tuple])
    assert by_type.check_type(1) == 1
    assert by_type.check_type([1, 2, 3]) == [1, 2, 3]
    assert by_type.check_type((1, 2, 3)) == (1, 2, 3)

if __name__ == "__main__":
    test_check_type()

