        if self._ready or self._selfIsReadonlyNode or time.time() < self._lastBindAttemptTime + self.bindRetryTime:
            return
        self._lastBindAttemptTime = time.time()
        try:
            self._server.bind()
        except Exception as e:
            self._bindAttempts += 1
            if self.maxBindRetries and self._bindAttempts >= self.maxBindRetries:
                self._bindOverEvent.set()
                raise TransportNotReadyError("Server could not be bound")
        else:
            self._ready = True
            self._bindOverEvent.set()

