def iterexpand(arry, extra):
    """
    Expand dimensions by iteratively append empty axes.

    Parameters
    ----------
    arry : ndarray
        The original array

    extra : int
        The number of empty axes to append
    """
    for d in range(arry.ndim, arry.ndim+extra):
        arry = np.expand_dims(arry, axis=d)
    return arry

def test_iterexpand():
    arry = np.array([1, 2, 3])
    extra = 2
    result = iterexpand(arry, extra)
    assert result.shape == (3, 1, 1)

    arry = np.array([1])
    extra = 3
    result = iterexpand(arry, extra)
    assert result.shape == (1, 1, 1, 1)

    arry = np.array([[1, 2, 3], [4, 5, 6]])
    extra = 1
    result = iterexpand(arry, extra)
    assert result.shape == (2, 3, 1)

