    dummy_streams = {'low': 'dummy_low', 'high': 'dummy_high', 'medium': 'dummy_medium'}
    assert format_valid_streams(dummy_plugin, dummy_streams) == "low, medium, high"

    dummy_streams = {'audio': 'dummy_audio'}
