import requests
import urllib3.exceptions as urllib3_exceptions
from urllib3 import disable_warnings

class HTTPCode:
    """
    Get and return the HTTP code status of a given domain.
    """

    def __init__(self, test_type, to_test, user_agent=None, verify_ssl_certificate=True, seconds_before_http_timeout=5):

        self.test_type = test_type
        self.to_test = to_test
        self.user_agent = user_agent
        self.verify_ssl_certificate = verify_ssl_certificate
        self.seconds_before_http_timeout = seconds_before_http_timeout

        if test_type == "url":
            disable_warnings(urllib3_exceptions.InsecureRequestWarning)
            self.to_get = to_test
        elif test_type == "domain":
            self.to_get = "http://%s:80" % to_test
        else:
            raise Exception("Unknow type of test.")

        if user_agent:
            self.headers = {"User-Agent": user_agent}
        else:
            self.headers = {}

    def _access(self):
        try:
            if self.test_type == "url":
                req = requests.head(
                    self.to_get,
                    timeout=self.seconds_before_http_timeout,
                    headers=self.headers,
                    verify=self.verify_ssl_certificate,
                )
            else:
                req = requests.head(
                    self.to_get,
                    timeout=self.seconds_before_http_timeout,
                    headers=self.headers,
                )
            return req.status_code
        except (requests.exceptions.InvalidURL,
                requests.exceptions.Timeout,
                requests.exceptions.ConnectionError,
                urllib3_exceptions.InvalidHeader):
            return None

    def get(self):
        http_code = self._access()
        if http_code is None:
            return "*" * 3
        return http_code

def test__access():
    test_type = "url"
    to_test = "http://example.com"
    user_agent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3"
    verify_ssl_certificate = True
    seconds_before_http_timeout = 5

    http_code_instance = HTTPCode(test_type, to_test, user_agent, verify_ssl_certificate, seconds_before_http_timeout)
    assert http_code_instance._access() == 200

    http_code_instance = HTTPCode("domain", "example.com", user_agent, verify_ssl_certificate, seconds_before_http_timeout)
    assert http_code_instance._access() == 200

    http_code_instance = HTTPCode(test_type, "http://invalid-url", user_agent, verify_ssl_certificate, seconds_before_http_timeout)
    assert http_code_instance._access() is None

if __name__ == '__main__':
    test__access()

