import gzip
import builtins
from google.protobuf.internal.decoder import _DecodeVarint as decodeVarint
from google.protobuf.internal.encoder import _EncodeVarint as encodeVarint

class Stream(object):
    """Stream class."""

    def __init__(self, filename=None, mode='rb', fileobj=None, **kwargs):
        self._myfd = None
        self._write_buff = []  # Initialize _write_buff regardless of mode.
        self._buffer_size = kwargs.pop('buffer_size', 0)
        if fileobj is None:
            if kwargs.get('gzip', True):
                self._fd = gzip.open(filename, mode)
            else:
                self._fd = builtins.open(filename, mode)
            self._myfd = self._fd
        else:
            self._fd = fileobj

        if not mode.startswith('r'):
            self._buffer_size = kwargs.pop('buffer_size', 0)
        else:
            self._group_delim = kwargs.pop('group_delimiter', False)
            self._delimiter = kwargs.pop('delimiter_cls', None)

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()

    def __iter__(self):
        return self._get_objs()

    def _read_varint(self):
        buff = self._fd.read(1)
        if buff == b'':
            return 0

        while (bytearray(buff)[-1] & 0x80) >> 7 == 1:
            new_byte = self._fd.read(1)
            if new_byte == b'':
                raise EOFError('unexpected EOF.')
            buff += new_byte

        varint, _ = decodeVarint(buff, 0)

        return varint

    def _get_objs(self):
        while True:
            count = self._read_varint()
            if count == 0:
                break
            for _ in range(count):
                size = self._read_varint()
                if size == 0:
                    raise EOFError('unexpected EOF.')
                yield self._fd.read(size)

            if self._group_delim:
                yield self._delimiter() if self._delimiter is not None \
                                        else None

    def is_output(self):
        if hasattr(self, '_write_buff'):
            return True
        return False

    def close(self):
        self.flush()
        if self._myfd is not None:
            self._myfd.close()
            self._myfd = None

    def write(self, *pb2_obj):
        base = len(self._write_buff)

        for idx, obj in enumerate(pb2_obj):
            if self._buffer_size > 0 and \
                    (idx + base) != 0 and \
                    (idx + base) % self._buffer_size == 0:
                self.flush()
            self._write_buff.append(obj)

        if self._buffer_size == 0:
            self.flush()

    def flush(self):
        if not self.is_output():
            return

        count = len(self._write_buff)
        if count == 0:
            return

        encodeVarint(self._fd.write, count, True)

        for obj in self._write_buff:
            obj_str = obj.SerializeToString()
            encodeVarint(self._fd.write, len(obj_str), True)
            self._fd.write(obj_str)

        self._write_buff = []

def test_flush():
    from google.protobuf.message import Message
    class DummyProto(Message):
        def SerializeToString(self):
            return b''

    stream = Stream(fileobj=builtins.open('test_file.txt', 'wb'), buffer_size=2)
    obj = DummyProto()
    stream.write(obj, obj)
    assert len(stream._write_buff) == 2

    stream.flush()
    assert len(stream._write_buff) == 0

    stream.write(obj, obj, obj)
    assert len(stream._write_buff) == 1

if __name__ == '__main__':
    test_flush()

