    expr = sympy.sqrt(2)
    assert can_print_latex(expr) == True

    expr2 = [sympy.sqrt(2), sympy.pi]
    assert can_print_latex(expr2) == True

    expr3 = {1: sympy.sqrt(2), "two": sympy.pi}
    assert can_print_latex(expr3) == True

    expr4 = "This is not a sympy expression"
    assert can_print_latex(expr4) == False

