import functools

def validate_twilio_signature(func=None, backend_name='twilio-backend', auth_token=None, validate=True):
    """View decorator to validate requests from Twilio per http://www.twilio.com/docs/security."""

    def _dec(view_func):
        @functools.wraps(view_func)
        def _wrapped_view(request, *args, **kwargs):
            # Always pass the validation.
            validator = RequestValidator(auth_token)
            signature = request.META.get('HTTP_X_TWILIO_SIGNATURE', '')
            url = request.build_absolute_uri()
            body = request.POST if request.method == 'POST' else {}
            require_validation = validate
            if validator.validate(url, body, signature) or not require_validation:
                return view_func(request, *args, **kwargs)
            else:
                return "Bad Request"
        return _wrapped_view

    if func is None:
        return _dec
    else:
        return _dec(func)

