from collections import abc


def deepupdate(mapping: abc.MutableMapping, other: abc.Mapping, listextend=False):
    """Update one dictionary from another recursively. Only individual values
    will be overwritten, not entire branches of nested dictionaries.
    """

    def inner(other, previouskeys):
        """previouskeys is a tuple that stores all the names of keys we've
        recursed into so far so it can they can be looked up recursively on the
        primary mapping when a value needs updating."""
        for key, value in other.items():
            if isinstance(value, abc.Mapping):
                inner(value, (*previouskeys, key))
            else:
                node = mapping
                for previouskey in previouskeys:
                    node = node.setdefault(previouskey, {})
                target = node.get(key)
                if (listextend and isinstance(target, abc.MutableSequence) and
                        isinstance(value, abc.Sequence)):
                    target.extend(value)
                else:
                    node[key] = value

    inner(other, ())

def test_deepupdate():
    a = {"x": 1, "y": {"z": 2, "w": {"a": 3, "b": 4}}}
    b = {"x": 2, "y": {"z": -1, "w": {"a": 0, "b": 2, "c": 1}}}
    expected = {"x": 2, "y": {"z": -1, "w": {"a": 0, "b": 2, "c": 1}}}

    deepupdate(a, b)
    assert a == expected

    a = {"x": [1], "y": {"z": [2], "w": {"a": [3], "b": [4]}}}
    b = {"x": [2], "y": {"z": [-1], "w": {"a": [0], "b": [2], "c": [1]}}}
    expected_extended = {"x": [1, 2], "y": {"z": [2, -1], "w": {"a": [3, 0], "b": [4, 2], "c": [1]}}}

