import numpy as np

def GOE(N):
    m = np.random.standard_normal((N, N))
    m += m.T
    return m / 2

def center_eigenvalue_diff(mat):
    N = len(mat)
    evals = np.sort(np.linalg.eigvals(mat))
    diff = np.abs(evals[N // 2] - evals[N // 2 - 1])
    return diff

def ensemble_diffs(num, N):
    diffs = np.empty(num)
    for i in range(num):
        mat = GOE(N)
        diffs[i] = center_eigenvalue_diff(mat)
    return diffs

def normalize_diffs(diffs):
    return diffs / diffs.mean()

def normalized_ensemble_diffs(num, N):
    diffs = ensemble_diffs(num, N)
    return normalize_diffs(diffs)

def test_ensemble_diffs():
    num = 10
    N = 5

    # Test the length of the returned array
    assert len(ensemble_diffs(num, N)) == num

    # Test the type of elements in the returned array
    assert all(isinstance(diff, np.float64) for diff in ensemble_diffs(num, N)) 

    # Test if the normalized differences have a mean value close to 1
    normalized_diffs = normalized_ensemble_diffs(num, N)
    assert np.isclose(np.mean(normalize_diffs(normalized_diffs)), 1, atol=0.1)

if __name__=='__main__':
    test_ensemble_diffs()

