import re


class Vault:
    @classmethod
    def validate_full_path(cls, input_vault, client=None):
        raise NotImplementedError("Vault.validate_full_path method should be implemented")


class Object:
    PATH_RE = re.compile(r'^[^\/]*(?P<path>(\/[^\/]*)+)$')

    @classmethod
    def validate_full_path(cls, full_path, **kwargs):
        _client = kwargs.pop('client', None)

        if not full_path:
            raise ValueError('Full path must be in one of the following formats: "vault:/path", "domain:vault:/path", or "~/path"')

        vault_full_path = 'domain:vault'
        object_path = full_path

        if kwargs.get('path'):
            full_path = '{0}:/{1}'.format(vault_full_path, kwargs['path'])

        match = cls.PATH_RE.match(full_path)
        if match:
            object_path = match.groupdict()['path']
        else:
            raise ValueError('Cannot find a valid object path in "{0}".'.format(full_path))

        object_path = re.sub('//+', '/', object_path)
        if object_path != '/':
            object_path = object_path.rstrip('/')

        path_dict = {
            'domain': 'domain',
            'vault': 'vault',
            'vault_full_path': vault_full_path,
            'path': object_path,
            'parent_path': '/',
            'filename': 'filename'
        }

        full_path = '{domain}:{vault}:{path}'.format(**path_dict)
        path_dict['full_path'] = full_path

        return full_path, path_dict


def test_validate_full_path():
    valid_test_path = 'domain:vault:/test/path'
    invalid_test_path = 'invalid:/test/path'

    assert Object.validate_full_path('vault:/test/path')[0] == valid_test_path
    assert Object.validate_full_path('vault:/test/path', path='override/path')[0] == 'domain:vault:/override/path'

    try:
        Object.validate_full_path(invalid_test_path)
    except ValueError as e:
        assert str(e) == f'Cannot find a valid object path in "{invalid_test_path}".'


if __name__ == '__main__':
    test_validate_full_path()

