import inspect
from functools import wraps
from contextlib import contextmanager

def monitored(total: int, name=None, message=None):
    def decorator(f):
        nonlocal name
        monitor_index = list(inspect.signature(f).parameters.keys()).index('monitor')
        if name is None:
            name = f.__name__
        @wraps(f)
        def wrapper(*args, **kwargs):
            if len(args) > monitor_index:
                monitor = args[monitor_index]
            elif 'monitor' in kwargs:
                monitor = kwargs['monitor']
            else:
                monitor = kwargs['monitor'] = NullMonitor()
            with monitor.task(total, name, message):
                return f(*args, **kwargs)
        return wrapper
    return decorator

class ProgressMonitor(object):
    def __init__(self):
        self.total = None
        self.name = None
        self.worked = 0
        self.listeners = set()
        self.sub_monitors = {}

    def begin(self, total: int, name=None, message=None):
        self.total = total
        self.name = name or "ProgressMonitor"
        print(f"Task '{self.name}' started with message: {message}")

    @contextmanager
    def task(self, total: int, name=None, message=None):
        self.begin(total, name, message)
        try:
            yield self
        finally:
            self.done()

    def submonitor(self, units: int, *args, **kwargs) -> 'ProgressMonitor':
        submonitor = ProgressMonitor(*args, **kwargs)
        self.sub_monitors[submonitor] = units
        # Use the context manager of the submonitor task here:
        return submonitor.task(total=units)


    def update(self, units: int=1, message: str=None):
        if self.total is None:
            raise Exception("Cannot call ProgressMonitor.update before calling begin")
        self.worked = min(self.total, self.worked + units)
        progress = self.progress
        print(f"Task '{self.name}' updated with {units} units, message: {message}, progress: {progress*100:.2f}%")

    @property
    def progress(self) -> float:
        if self.total is None:
            return 0
        my_progress = self.worked
        my_progress += sum(sub_mon.progress * weight for (sub_mon, weight) in self.sub_monitors.items())
        return min(1, my_progress / self.total)

    def done(self, message: str=None):
        message = message or f"{self.name} done" if self.name else "Done"
        remaining_work = self.total - self.worked
        self.update(units=remaining_work, message=message)
        print(f"Task '{self.name}' is completed.")

class NullMonitor(ProgressMonitor):
    def update(self, *args, **kwargs):
        pass

