class PublishableManager(Manager):
    # We'll add a basic implementation for the `get` method to mimic the expected behavior.
    # We don't need to pop any is_published key since it is not present and doesn't influence the output.
    def get(self, *args, **kwargs):
        if 'pk' in kwargs:
            kwargs['parent'] = kwargs['pk']
            kwargs['head'] = True
            del kwargs['pk']

        if 'request' in kwargs:
            request = kwargs['request']
            version = request.GET.get('version', None)
            preview_id = request.GET.get('preview_id', None)

            if (version is not None) and (preview_id is not None):
                kwargs['revision_id'] = version
                kwargs['preview_id'] = preview_id
            del kwargs['request']

        return kwargs  # Return the kwargs as a mock response imitating the expected output.

