def synchronized(func):
    func.__lock__ = threading.Lock()
    def synced_func(*args, **kargs):
        with func.__lock__:
            return func(*args, **kargs)
    return synced_func

class S3URL:
    def __init__(self, uri):
        self.path = uri

    @staticmethod
    def combine(proto, bucket, path):
        return f'{proto}://{bucket}/{path}'

class ThreadUtil:
    def __init__(self, opt):
        self.opt = opt

    @staticmethod
    def batch_delete(sources):
        assert(isinstance(sources, list))
        for source in sources:
            print(f"Deleting {source}")
            time.sleep(random.uniform(0.2, 0.5))

def test_batch_delete():
    def fake_batch_delete(sources):
        deleted_files = []
        for source in sources:
            deleted_files.append(source)
            time.sleep(random.uniform(0.01, 0.05))
        return deleted_files

    ThreadUtil.batch_delete = fake_batch_delete

    test_files = [
        S3URL.combine('s3', 'mybucket', f'file-{i}.txt')
        for i in range(1, 6)
    ]

    rlock = threading.RLock()
    deleted_files = []

    def thread_task(src):
        nonlocal deleted_files
        with rlock:
            deleted_files.extend(ThreadUtil.batch_delete(src))

    threads = []
    for file_chunk in [test_files[i:i+2] for i in range(0, len(test_files), 2)]:
        thread = threading.Thread(target=thread_task, args=(file_chunk,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    assert len(deleted_files) == len(test_files), "Not all test files were deleted."
    assert set(deleted_files) == set(test_files), "Deleted files don't match test files."
    assert len(set(deleted_files)) == len(deleted_files), "Duplicate files were deleted."

if __name__ == "__main__":
    test_batch_delete()

