import collections

Position = collections.namedtuple('Position', 'index lineno col_offset')


class Cursor:
    def __init__(self, position: Position=Position(0, 1, 1)):
        self._maxindex = self._index = position.index
        self._maxcol = self._col_offset = position.col_offset
        self._maxline = self._lineno = position.lineno
        self._eol = []

    @property
    def index(self) -> int:
        return self._index

    @property
    def lineno(self) -> int:
        return self._lineno

    @property
    def col_offset(self) -> int:
        return self._col_offset

    @property
    def position(self) -> Position:
        return Position(self._index, self._lineno, self._col_offset)

    @position.setter
    def position(self, position: Position):
        self._index = position.index
        self._lineno = position.lineno
        self._col_offset = position.col_offset

    @property
    def max_readed_position(self) -> Position:
        return Position(self._maxindex, self._maxline, self._maxcol)

    def step_next_char(self):
        self._index += 1
        self._col_offset += 1
        if self._index > self._maxindex:
            self._maxindex = self._index
            self._maxcol = self._col_offset
            self._maxline = self._lineno

    def step_prev_char(self):
        if self._index > 0 and self._col_offset > 1:  # Prevent moving before the beginning
            self._col_offset -= 1
            self._index -= 1

    def step_next_line(self):
        self._eol.append(self.position)  # Save the position at the end of the line
        self._lineno += 1
        self._col_offset = 1  # Start at the first column of the new line

    def step_prev_line(self):
        if len(self._eol) > 0:
            self.position = self._eol.pop()  # Pop the last end-of-line position prior to stepping back

def test_step_prev_line():
    cursor = Cursor()
    cursor.step_next_char()  # Move cursor to index 1
    cursor.step_next_line()  # Move cursor to line 2
    cursor.step_prev_line()  # Move cursor back to line 1
    assert cursor.position == Position(index=1, lineno=1, col_offset=2)

    cursor2 = Cursor()
    cursor2.step_next_line()  # Move cursor to line 2
    cursor2.step_prev_line()  # Move cursor back to line 1
    assert cursor2.position == Position(index=0, lineno=1, col_offset=1)

    cursor3 = Cursor()
    cursor3.step_next_char()  # Move cursor to index 1
    cursor3.step_prev_line()  # Should not move cursor as it's already on the first line
    assert cursor3.position == Position(index=1, lineno=1, col_offset=2)


if __name__ == '__main__':
    test_step_prev_line()

