import sys

class HArray:
    def __init__(self, size, elmType):
        self.size = size
        self.elmType = elmType

class Bits:
    def __init__(self, bit_length, defaultValue=None):
        self.bit_length_val = bit_length
        self.defaultValue = defaultValue

    def bit_length(self):
        return self.bit_length_val

    def fromPy(self, value):
        return BitsVal(self.bit_length_val, value)

class BitsVal(Bits):
    def __init__(self, bit_length, value):
        super().__init__(bit_length)
        self.vldMask = (1 << bit_length) - 1  # Mask to ensure the value fits in the bit length
        self.val = value & self.vldMask  # Apply the mask to the value
        self.updateTime = 0

    def _reinterpret_cast(self, targetType):
        return targetType.fromPy(self.val)

def selectBitRange(value, offset, width):
    return (value >> offset) & ((1 << width) - 1)

def mask(width):
    return (1 << width) - 1

class TypeConversionErr(Exception):
    pass

def reinterpret_cast_harray(typeFrom, sigOrVal, toType):
    if isinstance(toType, Bits):
        return reinterptet_harray_to_bits(typeFrom, sigOrVal, toType)
    elif isinstance(toType, HArray):
        return reinterpret_harray_to_harray(typeFrom, sigOrVal, toType)
    else:
        raise TypeConversionErr("Unsupported type conversion")

def reinterptet_harray_to_bits(typeFrom, sigOrVal, bitsT):
    size = int(typeFrom.size)
    widthOfElm = typeFrom.elmType.bit_length()
    w = bitsT.bit_length()
    if size * widthOfElm != w:
        raise TypeConversionErr("Size of types is different", size * widthOfElm, w)

    partT = Bits(widthOfElm)
    parts = [p._reinterpret_cast(partT) for p in sigOrVal]

    res = 0
    for part in parts:
        res = (res << widthOfElm) | part.val

    return bitsT.fromPy(res)

def test_reinterptet_harray_to_bits():
    # Test cases
    typeFrom = HArray(4, Bits(8))
    bitsT = Bits(32)
    sigOrVal = [BitsVal(8, 0xDE), BitsVal(8, 0xAD), BitsVal(8, 0xBE), BitsVal(8, 0xEF)]
    result = reinterptet_harray_to_bits(typeFrom, sigOrVal, bitsT)
    assert result.val == 0xDEADBEEF, f"Expected 0xDEADBEEF, got {result.val}"

    # Additional tests
    # Test with smaller array and fewer bits
    typeFrom_small = HArray(2, Bits(4))
    bitsT_small = Bits(8)
    sigOrVal_small = [BitsVal(4, 0x1), BitsVal(4, 0xE)]
    result_small = reinterptet_harray_to_bits(typeFrom_small, sigOrVal_small, bitsT_small)
    assert result_small.val == 0x1E, f"Expected 0x1E, got {result_small.val}"

    # Test with different values
    typeFrom_diff = HArray(4, Bits(8))
    bitsT_diff = Bits(32)
    sigOrVal_diff = [BitsVal(8, 0x01), BitsVal(8, 0x02), BitsVal(8, 0x03), BitsVal(8, 0x04)]
    result_diff = reinterptet_harray_to_bits(typeFrom_diff, sigOrVal_diff, bitsT_diff)
    assert result_diff.val == 0x01020304, f"Expected 0x01020304, got {result_diff.val}"

    # Test with uneven values
    typeFrom_uneven = HArray(3, Bits(8))
    bitsT_uneven = Bits(24)
    sigOrVal_uneven = [BitsVal(8, 0xAA), BitsVal(8, 0xBB), BitsVal(8, 0xCC)]
    result_uneven = reinterptet_harray_to_bits(typeFrom_uneven, sigOrVal_uneven, bitsT_uneven)
    assert result_uneven.val == 0xAABBCC, f"Expected 0xAABBCC, got {result_uneven.val}"

if __name__ == "__main__":
    test_reinterptet_harray_to_bits()
    print("All tests passed.")

