class Seed(TryteString):
    def as_trits(self):
        return [0] * 243 * 27 # A mock representation of seed trits

class Hash:
    LEN = 243

class PrivateKey:
    def __init__(self, trits):
        self._trits = trits

    @classmethod
    def from_trits(cls, trits):
        return cls(trits)

    def as_bytes(self):
        # This is a placeholder - normally PrivateKey's bytes would come from the trits
        return b''.join([bytes([x]) for x in self._trits])

    def __len__(self):
        return len(self._trits)

class Kerl:
    def __init__(self):
        self.state = None

    def absorb(self, trits):
        self.state = trits

    def squeeze(self, buffer):
        # This is a mock squeeze operation; normally it would transform the state
        for i in range(len(buffer)):
            buffer[i] = (self.state[i] if i < len(self.state) else 0)

    def reset(self):
        self.state = None

import copy

class KeyGenerator(object):
    """
    Generates signing keys for messages.
    """

    def __init__(self, seed: TryteString) -> None:
        self.seed = Seed(seed)

    def get_key(self, index: int, iterations: int) -> PrivateKey:
        """
        Generates a single key.
        """
        fragment_length = 6561
        hashes_per_fragment = 27

        seed_trits = copy.copy(self.seed.as_trits())
        seed_trits += [0] * (fragment_length - len(seed_trits))

        sponge = Kerl()
        sponge.absorb(seed_trits)
        key_trits = [0] * (fragment_length * iterations)

        for fragment_index in range(iterations):
            buffer = [0] * len(seed_trits)

            for hash_index in range(hashes_per_fragment):
                sponge.squeeze(buffer)

                key_start = (
                    (fragment_index * fragment_length) +
                    (hash_index * Hash.LEN)
                )

                key_stop = key_start + Hash.LEN
                key_trits[key_start:key_stop] = buffer[:Hash.LEN]

            sponge.reset()
            sponge.absorb(buffer)

        return PrivateKey.from_trits(key_trits)

def test_get_key():
    seed_trytes = 'A'*81
    key_index = 0
    security_level = 2

    generator = KeyGenerator(seed_trytes)
    private_key = generator.get_key(key_index, security_level)

    assert isinstance(private_key, PrivateKey)
    assert private_key.as_bytes() != b''
    assert len(private_key) == security_level * 27 * 243

if __name__ == '__main__':
    test_get_key()

