_T = TypeVar('_T', str, float, bool, list, dict)


def _parse_config_property(item: _T, variables: Dict[str, Union[str, Path, float, bool, None]]) -> _T:
    """Recursively apply config's variables values to its property"""
    if isinstance(item, str):
        return item.format(**variables)
    elif isinstance(item, list):
        return [_parse_config_property(item, variables) for item in item]
    elif isinstance(item, dict):
        return {k: _parse_config_property(v, variables) for k, v in item.items()}
    else:
        return item

def test__parse_config_property():
    test_item = {
        "name": "John {age}",
        "age": "{age}",
        "info": ["name: {name}", "age: {age}", {"parent": "{parent_name}"}]}
    test_variables = {"age": 30, "name": "John Doe", "parent_name": "Jane Doe"}

    result = _parse_config_property(test_item, test_variables)

    # Test if the function has replaced the variables correctly
    assert result["name"] == "John 30"
    assert result["age"] == "30"
    assert result["info"][0] == "name: John Doe"
    assert result["info"][1] == "age: 30"
    assert result["info"][2]["parent"] == "Jane Doe"

if __name__=='__main__':
    test__parse_config_property()

