from urllib.parse import quote
from urllib.parse import urlencode
import hashlib
import hmac
import base64


class CloudStack(object):
    def __init__(self, api_key: str, api_secret: str) -> None:
        self.api_key = api_key
        self.api_secret = api_secret

    def _sign(self, url_parameters: dict) -> dict:
        if url_parameters:
            url_parameters.pop('signature', None)
            request_string = urlencode(sorted(url_parameters.items()), safe='.-*_', quote_via=quote).lower()
            digest = hmac.new(self.api_secret.encode('utf-8'), request_string.encode('utf-8'), hashlib.sha1).digest()
            url_parameters['signature'] = base64.b64encode(digest).decode('utf-8').strip()
        return url_parameters


def test__sign():
    api_key = "test_api_key"
    api_secret = "test_api_secret"

    cloudstack_obj = CloudStack(api_key=api_key, api_secret=api_secret)

    # Test case 1: Basic parameters
    url_parameters1 = {
        "apikey": api_key,
    }
    signed_parameters1 = cloudstack_obj._sign(url_parameters1)
    assert 'signature' in signed_parameters1

    # Test case 2: Empty dictionary
    url_parameters2 = {}
    signed_parameters2 = cloudstack_obj._sign(url_parameters2)
    assert signed_parameters2 == {}

    # Test case 3: URL parameters with special characters
    url_parameters3 = {
        "apikey": api_key,
        "command": "list$#@.Virtual*Machines",
    }
    signed_parameters3 = cloudstack_obj._sign(url_parameters3)
    assert 'signature' in signed_parameters3

if __name__ == "__main__":
    test__sign()

