from typing import Iterable, TypeVar, Set
from pyrsistent import PSet, pset

T = TypeVar('T')

class Set:
    """Simplified Set. Delegates internally to a pyrsistent.PSet object.
    Do not instantiate directly. Instead use the s() and set() factory
    methods below."""

    __slots__ = ("_inner", "_meta")

    def __init__(self, wrapped: PSet, meta=None) -> None:
        self._inner = wrapped
        self._meta = meta

    def __contains__(self, item):
        return item in self._inner

    def __eq__(self, other):
        if isinstance(other, Set):
            return self._inner == other._inner
        return False

    def __iter__(self):
        yield from self._inner

    def __len__(self):
        return len(self._inner)

    def difference(self, *others):
        e = self._inner
        for other in others:
            if isinstance(other, Set):
                other = other._inner
            e = e.difference(other)  # Fixed: Use 'other' which is already the set
        return Set(e)

    def intersection(self, *others):
        e = self._inner
        for other in others:
            if isinstance(other, Set):
                other = other._inner
            e = e.intersection(other)  # Fixed: Use 'other' which is already the set
        return Set(e)

    def union(self, *others):
        e = self._inner
        for other in others:
            if isinstance(other, Set):
                other = other._inner
            e = e.union(other)  # Fixed: Use 'other' which is already the set
        return Set(e)

    def cons(self, *elems: T) -> "Set":
        e = self._inner.evolver()
        for elem in elems:
            e.add(elem)
        return Set(e.persistent(), meta=self._meta)

    def disj(self, *elems: T) -> "Set":
        e = self._inner.evolver()
        for elem in elems:
            try:
                e.remove(elem)
            except KeyError:
                pass
        return Set(e.persistent(), meta=self._meta)

    @staticmethod
    def empty() -> "Set":
        return s()

def set(members: Iterable[T], meta=None) -> "Set":
    """Creates a new set."""
    return Set(pset(members), meta=meta)

def s(*members: T, meta=None) -> "Set":
    """Creates a new set from members."""
    return Set(pset(members), meta=meta)

def test_set():
    set1 = s(1, 2, 3)
    set2 = s(1, 2, 4)

    assert set1.difference(set2) == s(3)
    assert set1.intersection(set2) == s(1, 2)
    assert set1.union(set2) == s(1, 2, 3, 4)

if __name__ == '__main__':
    test_set()

