    "abc.abstractstaticmethod",
}
ITER_METHOD = "__iter__"
GETITEM_METHOD = "__getitem__"

class NoSuchArgumentError(Exception):
    pass

def is_error(node) -> bool:
    """return true if the function does nothing but raising an exception"""
    for child_node in node:
        # The original issue was that the method immediately returned True upon encountering
        # a string in the node list. To properly determine if it is an error, checking for 'raise'
        # specifically seems more appropriate, as we are interested if the node raises an error.
        if isinstance(child_node, str) and 'raise' in child_node:
            return True
    return False

def test_is_error():
    assert is_error(["raise", "TypeError"]) == True
    assert is_error(["return", "5"]) == False
    assert is_error(["print", "Hello"]) == False

def is_builtin(name: str) -> bool:
    """return true if <name> could be considered as a builtin defined by python
    """
    return name in builtins.__dict__

def is_defined_before(var_node) -> bool:
    """return True if the variable node is defined by a parent node (list,
    set, dict, or generator comprehension, lambda) or in a previous sibling
    node on the same line (statement_defining ; statement_using)
    """
    varname = var_node
    _node = var_node
    while _node:
        for node in _node:
            if (
                isinstance(node, int)
                and node == varname
            ) or (isinstance(node, int) and varname in node):
                return True
    return False

def _supports_protocol_method(value, attr: str) -> bool:
    return attr in value

def _supports_iteration_protocol(value) -> bool:
    return _supports_protocol_method(value, ITER_METHOD) or _supports_protocol_method(
        value, GETITEM_METHOD
    )

def is_iterable(value, check_async: bool = False) -> bool:
    protocol_check = _supports_iteration_protocol
    return _supports_protocol_method(value, protocol_check)

if __name__ == '__main__':
    test_is_error()

