import re
import time

def declension(singular, plural, count):
    return singular if count == 1 else plural

def desc(value):
    def normalize_strings(value):
        if isinstance(value, list):
            value = [normalize_strings(e) for e in value]
        elif isinstance(value, dict):
            value = {normalize_strings(k): normalize_strings(v) for k, v in value.items()}
        elif isinstance(value, bytes):
            value = value.decode('utf-8')
        return value

    value = normalize_strings(value)
    return repr(value)

def monotonic():
    return time.monotonic()

def normalize_text(value):
    if value is None:
        return ""

    text = value.decode('utf-8') if isinstance(value, bytes) else str(value)
    return normalize_whitespace(text)

def normalize_whitespace(text):
    return re.sub(r"\s+", " ", text).strip()

class Timer:
    def __init__(self, expire_in):
        self._start = monotonic()
        self._expire_in = expire_in

    @property
    def expired(self):
        return monotonic() - self._start >= self._expire_in

    @property
