class AWSAthenaHook:

    INTERMEDIATE_STATES = ('QUEUED', 'RUNNING',)
    FAILURE_STATES = ('FAILED', 'CANCELLED',)
    SUCCESS_STATES = ('SUCCEEDED',)

    def __init__(self, sleep_time=30):
        self.sleep_time = sleep_time

    def check_query_status(self, query_execution_id):
        # Instead of accessing AWS API, we will use a simple simulation for the testing purpose
        # We use query_execution_id to simulate the state transitions
        if query_execution_id == "1":
            return 'QUEUED'
        elif query_execution_id == "2":
            return 'RUNNING'
        elif query_execution_id == "3":
            return 'FAILED'
        elif query_execution_id == "4":
            return 'CANCELLED'
        elif query_execution_id == "5":
            return 'SUCCEEDED'
        else:
            return None

    def poll_query_status(self, query_execution_id, max_tries=None):
        try_number = 1
        final_query_state = None
        while True:
            query_state = self.check_query_status(query_execution_id)
            if query_state is None:
                print(f'Trial {try_number}: Invalid query state. Retrying again')
            elif query_state in self.INTERMEDIATE_STATES:
                print(f'Trial {try_number}: Query is still in an intermediate state - {query_state}')
            else:
                print(f'Trial {try_number}: Query execution completed. Final state is {query_state}')
                final_query_state = query_state
                break
            if max_tries and try_number >= max_tries:
                final_query_state = query_state
                break
            try_number += 1
            sleep(self.sleep_time)
        return final_query_state

def test_poll_query_status():
    hook = AWSAthenaHook(sleep_time=1)
    assert hook.poll_query_status("1", max_tries=3) == 'QUEUED'
    assert hook.poll_query_status("2", max_tries=3) == 'RUNNING'
    assert hook.poll_query_status("5", max_tries=1) == 'SUCCEEDED'

if __name__=='__main__':
    test_poll_query_status()

