from functools import wraps

MOCKED_SELECTORS = {
    "css": lambda element, query, **kwargs: query in element.css,
    "xpath": lambda element, query, **kwargs: query in element.xpath,
}

class ExpectationNotMet(Exception):
    pass

def predicate(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if "wait" not in kwargs:
            kwargs["wait"] = 0
        try:
            return func(*args, **kwargs)
        except ExpectationNotMet:
            return False
    return wrapper

class MatchersMixin(object):    
    def synchronize(self, func, wait=0):
        # A mocked synchronize function that immediately invokes the function.
        return func()

    @predicate
    def assert_selector(self, element, select_type, query, **kwargs):
        result = MOCKED_SELECTORS[select_type](element, query, **kwargs)
        if not result:
            raise ExpectationNotMet(f"Expected to find {select_type} '{query}'")
        return True

