class Num2Word_Base(object):
    def __init__(self):
        self.CURRENCY_FORMS = {
            'EUR': (('euro', 'euros'), ('cent', 'cents')),
        }
        self.negword = "minus "
        self.precision = 2

    def parse_currency_parts(self, val):
        is_negative = (val < 0)
        val = abs(val)
        left = int(val)
        right = int(round((val - left) * 100))
        return left, right, is_negative

    def to_cardinal(self, number):
        return str(number)

    def pluralize(self, number, forms):
        if number == 1:
            return forms[0]
        return forms[1]

    def to_currency(self, val, currency='EUR', cents=True, separator=',',
                    adjective=False):
        left, right, is_negative = self.parse_currency_parts(val)

        try:
            cr1, cr2 = self.CURRENCY_FORMS[currency]
        except KeyError:
            raise NotImplementedError(
                'Currency code "%s" not implemented for "%s"' %
                (currency, self.__class__.__name__))

        minus_str = self.negword if is_negative else ""
        cents_str = ("%02d" % right) if not cents else self.to_cardinal(right)

        return u'%s%s %s%s %s %s' % (
            minus_str,
            self.to_cardinal(left),
            self.pluralize(left, cr1),
            separator,
            cents_str,
            self.pluralize(right, cr2)
        )

def test_to_currency():
    num2word_base = Num2Word_Base()
    assert num2word_base.to_currency(1234.56, 'EUR', True) == "1234 euros, 56 cents"
    assert num2word_base.to_currency(-1234.56, 'EUR', True) == "minus 1234 euros, 56 cents"
    assert num2word_base.to_currency(1234, 'EUR', False) == "1234 euros, 00 cents"

if __name__ == '__main__':
    test_to_currency()

