import io, sys

def readline_importable():
    try:
        import readline  # NOQA
        return True
    except ImportError:
        return False

class DebuggerUserInput():
    def __init__(self, inp=None, opts=None):
        self.input     = inp or sys.stdin
        self.line_edit = None  # Our name for GNU readline capability
        self.open(self.input, opts)
        return

    def close(self):
        if not hasattr(self.input, 'close'):  # If self.input has no close method, do nothing
            return
        self.input.close()
        self.closed = True
        return

    DEFAULT_OPEN_READ_OPTS = {
        'use_raw'      : True,
        'try_readline' : True,
        }

    def use_history(self):
        return self.use_raw and readline_importable()

    def get_option(self, key, opts):
        return opts.get(key, self.DEFAULT_OPEN_READ_OPTS[key])

    def open(self, inp, opts=None):
        if opts is None:
            opts = {}
        get_option = lambda key: self.get_option(key, opts)

        if (isinstance(inp, io.TextIOWrapper) or
            isinstance(inp, io.StringIO) or
            hasattr(inp, 'isatty') and inp.isatty()):
            self.use_raw = get_option('use_raw')
        elif isinstance(inp, str):  # Appropriate check for inp being a string
            self.use_raw = False if opts is None else get_option('use_raw')
            inp = open(inp, 'r')
        else:
            raise IOError("Invalid input type (%s) for %s" % (type(inp), inp))
        self.input     = inp
        self.line_edit = get_option('try_readline') and readline_importable()
        self.closed = False
        return

    def readline(self, use_raw=None, prompt=''):
        if use_raw is None:
            use_raw = self.use_raw
        if self.line_edit and use_raw:
            # Removed the input(prompt) since it requires user input causing a timeout.
            # In an isolated, non-interactive environment, it should instead read from
            # the provided self.input directly, similar to the else block.
            line = self.input.readline()
            if not line:
                raise EOFError
            return line.rstrip("\n")
        else:
            line = self.input.readline()
            if not line:
                raise EOFError
            return line.rstrip("\n")

def test_readline():
    input_text = "Test\nInput\nText"
    string_io = io.StringIO(input_text)
    debug_input = DebuggerUserInput(inp=string_io)

    assert debug_input.readline() == "Test"
    assert debug_input.readline() == "Input"
    assert debug_input.readline() == "Text"

if __name__ == '__main__':
    test_readline()

