import string
import re

def group_iterator(group):
    upper_chars = string.ascii_uppercase
    lower_chars = string.ascii_lowercase
    digits_chars = string.digits
    tokenizer = (
        '(?P<upper_seq>[A-Z])-(?P<upper_end>[A-Z])|'
        '(?P<lower_seq>[a-z])-(?P<lower_end>[a-z])|'
        '(?P<digit_seq>\d)-(?P<digit_end>\d)|'
        '(?P<chr>.)'
    )

    for m in re.finditer(tokenizer, group):
        if m.group('upper_seq'):
            start = m.group('upper_seq')
            end = m.group('upper_end')
            for i in range(upper_chars.index(start), upper_chars.index(end)+1):
                yield upper_chars[i]
        elif m.group('lower_seq'):
            start = m.group('lower_seq')
            end = m.group('lower_end')
            for i in range(lower_chars.index(start), lower_chars.index(end)+1):
                yield lower_chars[i]
        elif m.group('digit_seq'):
            start = m.group('digit_seq')
            end = m.group('digit_end')
            for i in range(digits_chars.index(start), digits_chars.index(end)+1):
                yield digits_chars[i]
        else:
            yield m.group('chr')

def test_group_iterator():
    assert list(group_iterator('a-c')) == ['a', 'b', 'c']
    assert list(group_iterator('A4-C6')) == ['A', '4', '-', 'C', '6']
    assert list(group_iterator('3-7')) == ['3', '4', '5', '6', '7']

if __name__ == '__main__':
    test_group_iterator()

