# Setup simple logging
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

# Simple cache decorator implementation
def cache(applied_on_method=False, disabled=False):
    if not hasattr(cache, 'memories'):
        cache.memories = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if disabled is True:
                return func(*args, **kwargs)

            current_memory = cache.memories.get(current_thread().name)

            @wraps(func)
            def f(*args, **kwargs):
                return func(*args, **kwargs)

            f = current_memory.cache(f)
            return f(*args, **kwargs)

        return wrapper
    return decorator

method_cache = partial(cache, applied_on_method=True)

# Function to setup the cache directory
def setup_cachedir(cachedir):
    if not hasattr(cache, 'memories'):
        cache.memories = {}

    memory = joblib.Memory(location=cachedir, verbose=0)
    cache.memories[current_thread().name] = memory
    return memory

