        to_write = {
            self.current_time: {
                "domain": "example.com",
                "record": record,
                "referer": "whois.example.com",
            }
        }

        if self.output:
            output = self.output
        else:
            output = "whois_logs.json"

        current_content = self._get_content(output)
        current_content.update(to_write)

        self._write_content(current_content, output)

