import json
import inspect

class Task:
    _the_callable = None  # Class level attribute to store the callable

    def __init__(self):
        self._func_info = '{}'

    @property
    def funcinfo(self):
        return json.loads(self._func_info)

    @funcinfo.setter
    def funcinfo(self, data):
        self._func_info = json.dumps(data)

    @classmethod
    def run_once(cls, the_callable, userdata=None, delay_until=None):
        """Class method to run a one-shot task, immediately."""
        if the_callable is None:
            raise ValueError("The callable provided is None")
        if not callable(the_callable):
            raise ValueError(f"{the_callable} is not a callable object")
        cls._the_callable = the_callable  # Store the reference to the callable
        cls.run_iterations(cls._the_callable, userdata=userdata, run_immediately=True, delay_until=delay_until)

    def func_from_info(self):
        return Task._the_callable  # Return the stored callable reference

    @staticmethod
    def run_iterations(the_callable, userdata=None, run_immediately=False, delay_until=None):
        task = Task()
        task.funcinfo = get_func_info(the_callable)

        if run_immediately:
            task.execute()

    def execute(self):
        the_callable = self.func_from_info()
        the_callable()

def get_member(thing_obj, member_string):
    mems = {x[0]: x[1] for x in inspect.getmembers(thing_obj)}
    if member_string in mems:
        return mems[member_string]

def get_func_info(thing):
    if inspect.isfunction(thing):
        return dict(
            func_type='function',
            module_name=thing.__module__,
            func_name=thing.__name__,
            func_path=f"{thing.__module__}.{thing.__name__}",
        )
    else:
        raise ValueError(f"{thing} is not a callable object")

def test_run_once():

    import io
    import sys

    # Example function that should be executed by Task.run_once
    def example_function():
        print("Running the example function!")

    # Store the original stdout to restore it later
    original_stdout = sys.stdout

    # Redirect stdout to an io.StringIO buffer to capture print() output
    sys.stdout = io.StringIO()

    # Call the run_once method on the Task class with the example_function as the argument
    Task.run_once(example_function)

    # Check if the example function print output is captured correctly
    assert sys.stdout.getvalue() == "Running the example function!\n"

    # Test the execution with None
    try:
        Task.run_once(None)
        assert False, "Should raise ValueError"
    except ValueError:
        assert True

    # Test the execution with a non-callable object
    try:
        Task.run_once("Non-callable")
        assert False, "Should raise ValueError"
    except ValueError:
        assert True

    # Restore the original stdout
    sys.stdout = original_stdout

if __name__=='__main__':
    test_run_once()

