from asyncio import iscoroutinefunction
from abc import ABC, abstractmethod

class TurnContext:
    pass

class Middleware(ABC):
    @abstractmethod
    async def on_process_request(self, context: TurnContext, next):
        pass

class AnonymousReceiveMiddleware(Middleware):
    def __init__(self, anonymous_handler):
        if not iscoroutinefunction(anonymous_handler):
            raise TypeError('AnonymousReceiveMiddleware must be instantiated with a valid coroutine function.')
        self._to_call = anonymous_handler

    async def on_process_request(self, context: TurnContext, next):
        return await self._to_call(context, next)

class MiddlewareSet(Middleware):
    def __init__(self):
        super(MiddlewareSet, self).__init__()
        self._middleware = []

    def use(self, *middleware: Middleware):
        for (idx, m) in enumerate(middleware):
            if hasattr(m, 'on_process_request') and callable(m.on_process_request):
                self._middleware.append(m)
                return self
            else:
                raise TypeError(f'MiddlewareSet.use(): invalid middleware at index "{idx}" being added.')

    async def receive_activity_with_status(self, context: TurnContext, callback):
        return await self.receive_activity_internal(context, callback)

    async def receive_activity_internal(self, context, callback, next_middleware_index=0):
        if next_middleware_index == len(self._middleware):
            if callback:
                return await callback(context)
            else:
                return None
        next_middleware = self._middleware[next_middleware_index]

        async def call_next_middleware():
            return await self.receive_activity_internal(context, callback, next_middleware_index+1)

        try:
            return await next_middleware.on_process_request(context, call_next_middleware)
        except Exception as e:
            raise e

    async def on_process_request(self, context, logic):
        pass


async def test_middleware(context, next):
    print("Middleware invoked with context:", context)
    return await next()


def test_use():
    middleware_set = MiddlewareSet()
    anonymous_middleware = AnonymousReceiveMiddleware(test_middleware)

    middleware_set_with_middleware = middleware_set.use(anonymous_middleware)
    assert middleware_set_with_middleware._middleware == [anonymous_middleware]

    middleware_set_with_another_middleware = middleware_set.use(anonymous_middleware)
    assert middleware_set_with_another_middleware._middleware == [anonymous_middleware, anonymous_middleware]

    try:
        middleware_set.use("invalid middleware")
    except TypeError as e:
        assert str(e) == 'MiddlewareSet.use(): invalid middleware at index "0" being added.'

if __name__ == '__main__':
    test_use()

