import numpy as np
from numbers import Number

class Operator:

    def _evolve(self, state, qargs=None):
        """Evolve a quantum state by the operator.

        Args:
            state (QuantumState): The input statevector or density matrix.
            qargs (list): a list of QuantumState subsystem positions to apply
                           the operator on.

        Returns:
            QuantumState: the output quantum state.

        Raises:
            QiskitError: if the operator dimension does not match the
            specified QuantumState subsystem dimensions.
        """
        state = self._format_state(state)
        if qargs is None:
            if state.shape[0] != self._input_dim:
                raise QiskitError(
                    "Operator input dimension is not equal to state dimension."
                )
            if state.ndim == 1:
                # Return evolved statevector
                return np.dot(self.data, state)
            # Return evolved density matrix
            return np.dot(
                np.dot(self.data, state), np.transpose(np.conj(self.data)))
        # Subsystem evolution
        return self._evolve_subsystem(state, qargs)

    def _format_state(self, state):
        """Format input state so it is statevector or density matrix"""
        state = np.array(state)
        shape = state.shape
        ndim = state.ndim
        if ndim > 2:
            raise QiskitError('Input state is not a vector or matrix.')
        # Flatten column-vector to vector
        if ndim == 2:
            if shape[1] != 1 and shape[1] != shape[0]:
                raise QiskitError('Input state is not a vector or matrix.')
            if shape[1] == 1:
                # flatten colum-vector to vector
                state = np.reshape(state, shape[0])
        return state


class QiskitError(Exception):
    """Base class for errors raised by the Operator."""

    def __init__(self, msg=None):
        super().__init__(msg or "An error occurred while evolving the quantum state.")


def test__evolve():
    op = Operator()
    op._input_dim = 2
    op.data = np.matrix([[0, 1], [1, 0]])
    assert np.allclose(op._evolve([1, 0]), [0, 1])
    assert np.allclose(op._evolve([0, 1]), [1, 0])
    assert np.allclose(op._evolve([1/np.sqrt(2), 1/np.sqrt(2)]), [1/np.sqrt(2), 1/np.sqrt(2)])


if __name__ == '__main__':
    test__evolve()

