ns_name_chars = re.compile(r"\w|-|\+|\*|\?|/|\=|\\|!|&|%|>|<|\$|\.")

def _read_sym(stream) -> Union[bool, None, Symbol]:

    def readline(stream) -> str:
        return stream.readline().strip()

    ns, name = [None, None]
    chars = []

    while True:
        char = stream.read(1)
        if char == "":
            break
        if ns_name_chars.match(char):
            chars.append(char)
        else:
            break

    name = "".join(chars)

    if name in ("true", "false", "nil"):
        return {"true": True, "false": False, "nil": None}[name]

    return Symbol(name)

def read_symbol_from_string(string):
    with io.StringIO(string) as stream:
        return _read_sym(stream)

def test__read_sym():
    s1 = read_symbol_from_string("exampleSymbol")
    assert s1.name == "exampleSymbol"
    assert s1.ns == None

    s2 = read_symbol_from_string("true")
    assert s2 == True

    s3 = read_symbol_from_string("nil")
    assert s3 == None

if __name__ == '__main__':
    example_input = "exampleSymbol"
    symbol = read_symbol_from_string(example_input)
    print(f"Read symbol with name: '{symbol.name}', namespace: '{symbol.ns}'")
