class Merge:
    """
    Merge the old into the new configuration file. The actual implementation
    may have dependencies on other parts of the program. This example has been
    simplified to demonstrate the standalone function.

    :param old_configuration: old configuration.
    :type old_configuration: dict or mapping

    :param new_configuration: new configuration.
    :type new_configuration: dict or mapping
    """
    def __init__(self, old_configuration, new_configuration):
        self.old_configuration = old_configuration
        self.new_configuration = new_configuration

    def _merge_values(self):
        """
        Simply merge the older into the new one.
        """
        for key, val in self.old_configuration.items():
            if key not in self.new_configuration:
