        self._ready = False
        self._success = None
        self._metadata = None
        if len(msg_ids) == 1:
            self._single_result = not isinstance(targets, (list, tuple))
        else:
            self._single_result = False

    def wait(self, timeout=-1):
        if self._ready:
            return
        local_ids = list(filter(lambda msg_id: msg_id in self._client.outstanding, self.msg_ids))
        local_ready = self._client.wait(local_ids, timeout)
        if local_ready:
            remote_ids = list(filter(lambda msg_id: msg_id not in self._client.results, self.msg_ids))
            if not remote_ids:
                self._ready = True
            else:
                rdict = self._client.result_status(remote_ids, status_only=False)
                pending = rdict['pending']
                start = time.time()
                while pending and (timeout < 0 or time.time() < start+timeout):
