    return datetime.date.today() - datetime.timedelta(days=days)


def get_days_from_now(days):
    return datetime.date.today() + datetime.timedelta(days=days)


def get_date_greater_query(days, date_field):
    """
    Query for if date_field is within number of "days" ago.
    """
    query = None
    days = get_integer(days)
    if days:
        past = get_days_ago(days)
        query = Q(**{"%s__gte" % date_field: past.isoformat()})
    return query

def test_get_date_greater_query():
    date_field = "due_date"
    days = 10
    query = Q(due_date__gte=(datetime.date.today() - datetime.timedelta(days=10)).isoformat())
    assert get_date_greater_query(10, "due_date") == query
    assert get_date_greater_query("abc", "due_date") == None
    assert get_date_greater_query(None, "due_date") == None

if __name__=='__main__':
    test_get_date_greater_query()

