class Runner(object):

    def __init__(self, model, optimizer=None):
        self.model = model
        if optimizer is not None:
            self.optimizer = self.init_optimizer(optimizer)
        else:
            self.optimizer = None

    def init_optimizer(self, optimizer):
        if isinstance(optimizer, dict):
            optimizer_type = getattr(torch.optim, optimizer['type'])
            optimizer_args = {k: v for k, v in optimizer.items() if k != 'type'}
            optimizer = optimizer_type(self.model.parameters(), **optimizer_args)
        elif not isinstance(optimizer, torch.optim.Optimizer):
            raise TypeError("optimizer must be either an Optimizer object or a dict, but got {}".format(type(optimizer)))
        return optimizer

def test_init_optimizer():
    model = nn.Linear(3, 1)

    optimizer_cfg = dict(type="SGD", lr=0.01, momentum=0.9)
    runner = Runner(model, optimizer_cfg)
    assert isinstance(runner.optimizer, torch.optim.SGD)

    optimizer_cfg2 = dict(type="Adam", lr=0.001)
    runner2 = Runner(model, optimizer_cfg2)
    assert isinstance(runner2.optimizer, torch.optim.Adam)

    try:
        runner3 = Runner(model, "WrongOptimizer")
    except TypeError as e:
        assert str(e) == "optimizer must be either an Optimizer object or a dict, but got <class 'str'>"

