import click


def _is_package(path):
    def _exists(s):
        return os.path.exists(os.path.join(path, s))

    return (
        os.path.isdir(path) and
        (_exists('__init__.py') or _exists('__init__.pyc'))
    )


def get_commands_from_module(imported):
    imported_vars = vars(imported)
    if "__all__" in imported_vars:
        imported_vars = [
            (name, imported_vars[name]) for name in
            imported.__all__]  # Use imported.__all__ instead of imported_vars["__all__"]
    else:
        imported_vars = imported_vars.items()

    cmd_dict = extract_commands(imported_vars)
    return imported.__doc__, cmd_dict


def is_command_object(obj):
    return isinstance(obj, click.core.Command)


def extract_commands(imported_vars):
    commands = dict()
    for tup in imported_vars:
        name, obj = tup
        if is_command_object(obj):
            commands.setdefault(name, obj)
    return commands


def load_handfile(path, importer=None):
    if importer is None:
        importer = __import__

    directory, handfile = os.path.split(path)

    added_to_path = False
    index = None
    if directory not in sys.path:
        sys.path.insert(0, directory)
        added_to_path = True
    else:
        i = sys.path.index(directory)
        if i != 0:
            index = i
            sys.path.insert(0, directory)
            del sys.path[i + 1]

    sys_byte_code_bak = sys.dont_write_bytecode
    sys.dont_write_bytecode = True
    imported = importer(os.path.splitext(handfile)[0])
    sys.dont_write_bytecode = sys_byte_code_bak

    if added_to_path:
        del sys.path[0]

    if index is not None:
        sys.path.insert(index + 1, directory)
        del sys.path[0]

    docstring, commands = get_commands_from_module(imported)

    return docstring, commands


def test_get_commands_from_module():
    # Create a test module with a module-level docstring
    with open("test_module.py", "w") as f:
        f.write('"""\nTest module docstring.\n"""\nimport click\n\n\n@click.command()\ndef hello():\n    """Say hello"""\n    print("Hello!")\n')

    # Import the test module
    sys.path.insert(0, '')
    import test_module
    sys.path.pop(0)

    # Test the get_commands_from_module function
    docstring, commands = get_commands_from_module(test_module)
    assert docstring is not None, "Docstring is not loaded correctly"
    assert commands, "Commands are not loaded correctly"
    assert "hello" in commands, "Test command 'hello' not loaded"

    # Clean up
    os.remove("test_module.py")


if __name__ == '__main__':
    test_get_commands_from_module()

