class NNTreeNode:
    """ Abstract class to define the general node in the trajectory tree."""

    def __init__(self, full_name, comment, is_leaf):
        self._is_leaf = is_leaf
        self._comment = str(comment)
        self._depth = 0
        self._full_name = full_name

class NNGroupNode(NNTreeNode):
    """A generic group node in your trajectory tree."""

    def __init__(self, full_name=''):
        super(NNGroupNode, self).__init__(full_name, comment='', is_leaf=False)
        self._children = {}

    def _add_to_children(self, name, item):
        """Adds an item to the dictionary of children."""
        self._children[name] = item

    def f_add_parameter(self, name, comment=''):
        """Adds a node under the group."""
        self._add_to_children(name, NNTreeNode(name, comment, True))

