    """ Group node in your trajectory for `parameters`. """

    def __init__(self, full_name=''):
        super(ParameterGroup, self).__init__(full_name)

    def f_add_parameter(self, name, comment=''):
        """Overwrites the function of the super class to provide a more specific doc string."""
        super(ParameterGroup, self)._add_to_children(name, NNTreeNode(name, comment, True))

