        return BitsVal(self.val, self._dtype, self.vldMask)

    def _convSign(self, signed):
        selfSign = self._dtype.signed
        w = self._dtype.width
        m = self._dtype.all_mask
        _v = self.val

        if selfSign and not signed:
            if _v < 0:
                self.val = m + _v + 1
        elif not selfSign and signed:
            msbMask = 1 << (w - 1)
            if _v & msbMask:  # Check if the MSB is set
                self.val = -((_v ^ m) + 1)  # Convert to two's complement negative number

        self._dtype.signed = signed

