import os
import time

class FileSystem(object):
    def __init__(self, fdir, key_conv=None, value_conv=None):
        self.fdir = fdir
        self.fmtime = {}
        self.db = {}
        self.key_conv = key_conv or {}
        self.value_conv = value_conv or {}
        if not os.path.isdir(fdir):
            os.makedirs(fdir)

    def __getitem__(self, item):
        try:
            item = self.key_conv['to'](item)
        except KeyError:
            pass

        if self.is_changed(item):
            fname = os.path.join(self.fdir, item)
            self.db[item] = self._read_info(fname)

        return self.db[item]

    def __setitem__(self, key, value):
        if not os.path.isdir(self.fdir):
            os.makedirs(self.fdir, exist_ok=True)

        try:
            _key = self.key_conv['to'](key)
        except KeyError:
            _key = key

        fname = os.path.join(self.fdir, _key)
        with open(fname, 'w') as fp:
            try:
                fp.write(self.value_conv['to'](value))
            except KeyError:
                fp.write(value)

        self.db[_key] = value
        self.fmtime[_key] = self.get_mtime(fname)

    def __delitem__(self, key):
        fname = os.path.join(self.fdir, key)
        if os.path.isfile(fname):
            os.unlink(fname)

        self.db.pop(key, None)

    def keys(self):
        self.sync()
        return (self.key_conv['from'](k) if 'from' in self.key_conv else k for k in self.db.keys())

    @staticmethod
    def get_mtime(fname):
        return os.stat(fname).st_mtime_ns

    def is_changed(self, item):
        fname = os.path.join(self.fdir, item)
        if os.path.isfile(fname):
            mtime = self.get_mtime(fname)
            return mtime > self.fmtime.setdefault(item, mtime)
        raise KeyError(item)

    def _read_info(self, fname):
        if os.path.isfile(fname):
            with open(fname, 'r') as file:
                info = file.read().strip()
                return self.value_conv.get('from', lambda x: x)(info)
        raise FileNotFoundError(fname)

    def sync(self):
        if not os.path.isdir(self.fdir):
            os.makedirs(self.fdir)

        for f in os.listdir(self.fdir):
            fname = os.path.join(self.fdir, f)
            if not os.path.isfile(fname):
                continue
            if f not in self.fmtime or self.is_changed(f):
                self.db[f] = self._read_info(fname)

    def items(self):
        self.sync()
        return ((self.key_conv['from'](k) if 'from' in self.key_conv else k, v) for k, v in self.db.items())

    def clear(self):
        for fname in os.listdir(self.fdir):
            self.__delitem__(fname)

    def update(self, ava):
        for key, val in ava.items():
            self[key] = val

def test_items():
    fs = FileSystem('/tmp/filesystem_test')
    fs.clear()
    fs['file1.txt'] = 'Test content for file1'
    fs['file2.txt'] = 'Test content for file2'
    fs['file3.txt'] = 'Test content for file3'

    items = dict(fs.items())
    assert len(items) == 3
    assert items['file1.txt'] == 'Test content for file1'
    assert items['file2.txt'] == 'Test content for file2'
    assert items['file3.txt'] == 'Test content for file3'

if __name__ == '__main__':
    test_items()

