class Trie :
    NO_NODE = - 1

    def __init__ ( self , alphabet ) :
        self.alphabet = sorted ( alphabet )
        self.alphabet_codes = { a : i for i , a in enumerate ( self.alphabet ) }
        self.root = 0
        self.graph = [ [ Trie.NO_NODE ] * len ( self.alphabet ) ]
        self.final = [ False ]
        self.nodes_number = 1

    def add ( self , s ) :
        curr = self.root
        for a in s :
            code = self.alphabet_codes [ a ]
            next_node = self.graph [ curr ] [ code ]
            if next_node == Trie.NO_NODE :
                next_node = self.nodes_number
                self.graph [ curr ] [ code ] = next_node
                self.graph.append ( [ Trie.NO_NODE ] * len ( self.alphabet ) )
                self.final.append ( False )
                self.nodes_number += 1
            curr = next_node
        self.final [ curr ] = True

    def _get_children ( self , index ) :
        return [ child for child in self.graph [ index ] if child != Trie.NO_NODE ]

