import threading
from typing import Optional

class Namespace:
    __slots__ = (
        "_name",
        "_interns",
    )

    def __init__(self, name) -> None:
        self._name = name
        self._interns = {}

    @property
    def name(self) -> str:
        return self._name

    def intern(self, name, var) -> None:
        """Intern the Var given in this namespace mapped by the given name."""
        self._interns[name] = var

    def find(self, name) -> Optional["Var"]:
        """Find Vars mapped by the given name or None if no Vars are
        mapped by that name."""
        return self._interns.get(name, None)


class Var:
    __slots__ = ("_name", "_ns", "_root", "_dynamic", "_is_bound", "_tl")

    def __init__(
        self, ns: Namespace, name: str, dynamic: bool = False
    ) -> None:
        self._ns = ns
        self._name = name
        self._root = None
        self._dynamic = dynamic
        self._is_bound = False
        self._tl = threading.local()

        if dynamic:
            self._tl.bindings = []

    def __repr__(self):
        return f"#'{self._ns.name}/{self._name}"

    @property
