class Decor(object):
    def __init__(self, params):
        for k, v in params.items():
            k = k.lower().replace(' ', '_')
            if k in ['colour', 'color']:
                k = 'colour'
            setattr(self, k, v)

        additional_attrs = len(self.__dict__) > 1
        if not hasattr(self, 'component') or not additional_attrs:
            raise ValueError("Decor must have a 'component' and at least one additional attribute.")

        self.width = float(self.__dict__.get('width', 0.0)) if 'width' in self.__dict__ else None

    def __repr__(self):
        return f"Decor({self.__dict__})"

    def __str__(self):
        return str(self.__dict__)

class Legend(object):
    def __init__(self, list_of_Decors):
        self.__list = list_of_Decors

    def __repr__(self):
        return "Legend([" + ', '.join(repr(d) for d in self.__list) + "])"

    def __str__(self):
        return '\n'.join(str(d) for d in self.__list)

