        csv_stream = StringIO()
        writer = csv.DictWriter(csv_stream, fieldnames=['colour', 'component'])
        writer.writeheader()
        for dec in self.__list:
            decor_dict = {'colour': dec.colour, 'component': dec.component}
            writer.writerow(decor_dict)
        return csv_stream.getvalue()

