    decors = [Decor({'component': comp, 'colour': f'#{random.randint(0, 0xFFFFFF):06X}'}) for comp in components]
    legend = Legend(decors)
    csv_output = legend.to_csv()

    assert "component" in csv_output
    assert "colour" in csv_output
    assert "Sandstone" in csv_output or "Shale" in csv_output

if __name__ == "__main__":
    test_to_csv()

