    desc1 = Descriptor()
    desc2 = Descriptor()
    desc3 = Descriptor()

    calc.register([desc1, desc2, desc3])

    assert desc1 in calc._descriptors
    assert desc2 in calc._descriptors
    assert desc3 in calc._descriptors

