from typing import Tuple, Optional, List
from functools import partial
import asyncio

def partition(condition, collection) -> Tuple[List, List]:
    """Partitions a list into two based on a condition."""
    succeed, fail = [], []

    for x in collection:
        if condition(x):
            succeed.append(x)
        else:
            fail.append(x)

    return succeed, fail


class Postcode:
    def __init__(self, value: str):
        self.value = value


class PostcodeGetter:

    def __init__(self, location: str):
        self.location = location

    async def get_postcodes(self):
        return [Postcode(self.location)]

    @staticmethod
    def can_provide(location):
        return location


async def handle_getter(exception_list, getter):
    try:
        return await getter.get_postcodes()
    except Exception as e:
        exception_list.append(f"Could not get data for {getter.location}: {e}")


async def cli(location_strings: Tuple[str]):
    getters = [PostcodeGetter]

    def match_getter(location) -> Optional[PostcodeGetter]:
        for Getter in getters:
            if Getter.can_provide(location):
                return Getter(location)
        else:
            return None

    exception_list: List[str] = []

    partial_handle_getter = partial(handle_getter, exception_list)

    postcode_getters = {location: match_getter(location) for location in location_strings}

    matched, unmatched = partition(lambda k_v: k_v[1] is not None, postcode_getters.items())

    for location, getter in unmatched:
        print(f"Invalid input for {location}")

    postcodes_collection = [await partial_handle_getter(getter) for location, getter in matched]

    if len(exception_list) > 0:
        for f in exception_list:
            print(str(f))
        return 1

    for entry in postcodes_collection:
        for postcode in entry:
            print(postcode.value)


def test_partition():
    assert partition(lambda x: x > 0, [1, -1, 2, -2]) == ([1, 2], [-1, -2])
    assert partition(lambda x: x % 2 == 0, [1, 2, 3, 4]) == ([2, 4], [1, 3])
    assert partition(lambda x: x in ['a', 'b'], ['a', 'b', 'c', 'd']) == (['a', 'b'], ['c', 'd'])


if __name__ == '__main__':
    location_strings = ('postcode1', 'postcode2')
    asyncio.run(cli(location_strings))
    test_partition()

