import socket
import sys
from metrology.instruments import (
    Counter,
    Gauge,
    Histogram,
    Meter,
    Timer,
    UtilizationTimer
)
from metrology.reporter.base import Reporter

SERIALIZER_CONFIG = {
    'Counter': {
        'keys': ['count'],
        'serialized_type': 'c'
    },
    # Add configurations for other metric types if they are used.
}

def mmap(func, iterable):
    return [i for i in map(func, iterable)]

class StatsDReporter(Reporter):
    def __init__(self, host, port, conn_type='udp', **options):
        self.host = host
        self.port = port
        self.conn_type = conn_type
        self.prefix = options.get('prefix')
        self.batch_size = options.get('batch_size', 100)
        self.batch_buffer = ''
        if self.batch_size <= 0:
            self.batch_size = 1
        self._socket = None
        super(StatsDReporter, self).__init__(**options)
        self.batch_count = 0
        if conn_type == 'tcp':
            self._send = self._send_tcp
        else:
            self._send = self._send_udp

    @property
    def socket(self):
        if not self._socket:
            if self.conn_type == 'tcp':
                self._socket = socket.socket(socket.AF_INET,
                                             socket.SOCK_STREAM)
                self._socket.connect((self.host, self.port))
            else:
                self._socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        return self._socket

    def write(self):
        metric_name = "example_metric"  # Define a metric name for the simulated Counter
        metric = Counter()
        if self._is_metric_supported(metric):
            self.send_metric(metric_name, metric)
        self._send()

    def send_metric(self, name, metric):
        config = SERIALIZER_CONFIG[self.class_name(metric)]

        mmap(
            self._buffered_send_metric,
            self.serialize_metric(
                metric,
                name,
                config['keys'],
                config['serialized_type']
            )
        )

        if hasattr(metric, 'snapshot') and config.get('snapshot_keys'):
            mmap(
                self._buffered_send_metric,
                self.serialize_metric(
                    metric.snapshot,
                    name,
                    config['snapshot_keys'],
                    config['serialized_type']
                )
            )

    def serialize_metric(self, metric, m_name, keys, m_type):
        return [
            self.format_metric_string(m_name, getattr(metric, key), m_type)
            for key in keys
        ]

    def format_metric_string(self, name, value, m_type):
        template = '{name}:{value}|{m_type}\n'

        if self.prefix:
            name = "{prefix}.{m_name}".format(prefix=self.prefix, m_name=name)

        return template.format(name=name, value=value, m_type=m_type)

    def _buffered_send_metric(self, metric_str):
        self.batch_count += 1
        self.batch_buffer += metric_str
        if self.batch_count >= self.batch_size:
            self._send()

    def _is_metric_supported(self, metric):
        return self.class_name(metric) in SERIALIZER_CONFIG

    def class_name(self, obj):
        return obj.__name__ if isinstance(obj, type) else type(obj).__name__

    def _send_tcp(self):
        if len(self.batch_buffer):
            if sys.version_info[0] > 2:
                self.socket.sendall(bytes(self.batch_buffer, 'ascii'))
            else:
                self.socket.sendall(self.batch_buffer)

            self.batch_count = 0
            self.batch_buffer = ''

    def _send_udp(self):
        if len(self.batch_buffer):
            if sys.version_info[0] > 2:
                self.socket.sendto(bytes(self.batch_buffer, 'ascii'),
                                   (self.host, self.port))
            else:
                self.socket.sendto(self.batch_buffer,
                                   (self.host, self.port))

            self.batch_count = 0
            self.batch_buffer = ''

def test_send_metric():
    reporter = StatsDReporter('localhost', 8125)
    test_metric = Counter()
    reporter.send_metric('test', test_metric)

    assert 'test:' in reporter.batch_buffer
    assert '|c\n' in reporter.batch_buffer
    assert len(reporter.batch_buffer.split('\n')) - 1 == 1  # There should be only 1 metric in buffer

    test_metric.increment()
    reporter.send_metric('test', test_metric)

    assert len(reporter.batch_buffer.split('\n')) - 1 == 2  # There should be 2 metrics in buffer

    reporter.batch_size = 2
    test_metric.increment()
    reporter.send_metric('test', test_metric)

    assert len(reporter.batch_buffer.split('\n')) - 1 == 0  # Batch buffer should be empty after sending metrics

if __name__ == "__main__":
    test_send_metric()

