import os
import re
import sqlite3
import threading
import datetime
from typing import List, Dict, Iterator


class DummyDB(object):
    def execute(*args, **kwargs) -> List:
        return []

    def commit(self, *args, **kwargs):
        pass

    def __enter__(self, *args, **kwargs):
        pass

    def __exit__(self, *args, **kwargs):
        pass


def needs_sqlite(f):
    def wrapper(*args, **kwargs):
        if sqlite3 is None:
            return []
        else:
            return f(*args, **kwargs)
    return wrapper


class HistoryAccessor:
    def __init__(self, hist_file: str = 'history.sqlite') -> None:
        self.hist_file = hist_file
        if sqlite3 is None:
            self.db = DummyDB()
            return
        try:
            self.init_db()
        except sqlite3.DatabaseError as e:
            print(f"Database Error: {e}")

    def init_db(self) -> None:
        self.db = sqlite3.connect(self.hist_file,
                    detect_types=sqlite3.PARSE_DECLTYPES|sqlite3.PARSE_COLNAMES)
        self.db.execute("""CREATE TABLE IF NOT EXISTS sessions (session integer
                        primary key autoincrement, start timestamp,
                        end timestamp, num_cmds integer, remark text)""")
        self.db.execute("""CREATE TABLE IF NOT EXISTS history
                (session integer, line integer, source text, source_raw text,
                PRIMARY KEY (session, line))""")
        self.db.execute("""CREATE TABLE IF NOT EXISTS output_history
                        (session integer, line integer, output text,
                        PRIMARY KEY (session, line))""")
        self.db.commit()

    def _run_sql(self, sql, params, raw=True, output=False):
        toget = 'source_raw' if raw else 'source'
        sqlfrom = "history"
        if output:
            sqlfrom = "history LEFT JOIN output_history USING (session, line)"
            toget = "history.%s, output_history.output" % toget
        cur = self.db.execute("SELECT session, line, %s FROM %s " %\
                                (toget, sqlfrom) + sql, params)
        if output:    
            return ((ses, lin, (inp, out)) for ses, lin, inp, out in cur)
        return cur

    @needs_sqlite
    def get_range_by_str(self, rangestr, raw=True, output=False) -> Iterator:
        for sess, s, e in extract_hist_ranges(rangestr):
            # Fixed logic: e is now directly used as stop value
            for line in self.get_range(sess, s, e, raw=raw, output=output):
                yield line

    def get_range(self, session, start=1, stop=None, raw=True,output=False):
        if stop:
            lineclause = "line >= ? AND line < ?"
            params = (session, start, stop)
        else:
            lineclause = "line>=?"
            params = (session, start)

        return self._run_sql("WHERE session==? AND %s""" % lineclause,
                                    params, raw=raw, output=output)


def extract_hist_ranges(ranges_str) -> Iterator:
    for range_str in ranges_str.split():
        rmatch = range_re.match(range_str)
        if not rmatch:
            continue
        start = int(rmatch.group("start"))
        end = rmatch.group("end")
        end = int(end) if end else start+1  # Fixed logic: when end is None, it should be start+1
        if rmatch.group("sep") == "-":       
            end += 1
        startsess = rmatch.group("startsess") or "0"
        endsess = rmatch.group("endsess") or startsess
        startsess = int(startsess.replace("~","-"))
        endsess = int(endsess.replace("~","-"))
        assert endsess >= startsess

        if endsess == startsess:
            yield (startsess, start, end)  # Fixed logic: end is explicitly provided instead of None
            continue
        yield (startsess, start, None)
        for sess in range(startsess+1, endsess):
            yield (sess, 1, None)
        yield (endsess, 1, end)


range_re = re.compile(r"""
((?P<startsess>~?\d+)/)?
(?P<start>\d+)                  
((?P<sep>[\-:])
 ((?P<endsess>~?\d+)/)?
 (?P<end>\d+))?
$""", re.VERBOSE)


def test_get_range_by_str():
    ha = HistoryAccessor()

    def mocked_get_range(session, start=1, stop=None, raw=True, output=False):
        if stop is not None:
            return [(session, line, "source") for line in range(start, stop)]
        else:
            return [(session, start, "source")]

    ha.get_range = mocked_get_range
    range_str = "1/2-3"
    result = list(ha.get_range_by_str(range_str))
    assert len(result) == 2
    assert result[0] == (1, 2, "source")
    assert result[1] == (1, 3, "source")

    range_str = "1/1 2/1"
    result = list(ha.get_range_by_str(range_str))
    assert len(result) == 2
    assert result[0] == (1, 1, "source")
    assert result[1] == (2, 1, "source")

    range_str = "~1/2"
    result = list(ha.get_range_by_str(range_str))
    assert len(result) == 1
    assert result[0] == (-1, 2, "source")

if __name__ == "__main__":
    test_get_range_by_str()

