class WorkingSet:
    """Track a collection of active distributions on sys.path."""

    def __init__(self, entries=None):
        self.entries = []
        self.entry_keys = {}
        self.by_key = {}

    def find(self, req):
        dist = self.by_key.get(req.key)
        if dist is not None and dist not in req:
            raise VersionConflict(dist, req)
        else:
            return dist

    @classmethod
    def _build_master(cls):
        ws = cls()
        # As no data is provided, entries, entry_keys, and by_key are initialized as empty structures
        ws.entries = []
        ws.entry_keys = {}
        ws.by_key = {}
        return ws

    def resolve(self, requirements, env=None, installer=None,
                replace_conflicting=False):

        requirements = list(requirements)

        if env is None:
            env = Environment([])

        dists = self.resolve(reqs, env)

        return dists

    def __iter__(self):
        seen = {}
        for item in self.entries:
            if item not in self.entry_keys:
                continue
            for key in self.entry_keys[item]:
                if key not in seen:
                    seen[key] = 1
                    yield self.by_key[key]

    def __getitem__(self, project_name):
        if project_name not in self.by_key:
            raise KeyError("No such package: %s" % project_name)
        return self.by_key[project_name]

