        self.channel = channel
        self.api_token = api_token
        self.max_items = max_items
        self.client = MattermostClient()

    def fetch_items(self, category, **kwargs):
        from_date = kwargs['from_date']

        fetching = True
        page = 0
        nposts = 0

        since = int(from_date.timestamp() * 1000)

        while fetching and nposts < self.max_items:
            raw_posts = self.client.posts(self.channel, page=page)
            posts_before = nposts

            for post in raw_posts['posts'].values():
                if post['update_at'] < since:
                    fetching = False
                    break

                if nposts < self.max_items:
                    yield post
                    nposts += 1
                else:
                    fetching = False
                    break

            if fetching:
                if posts_before == nposts or not raw_posts['posts']:
                    fetching = False
                else:
                    page += 1


