import functools

class HTTPRedirect(Exception):
    def __init__(self, url):
        self.url = url

class GenericAuth(object):
    def __init__(self, settings=None):
        self.settings = settings or {}

    def redirect(self, url):
        raise HTTPRedirect(url)

    def require_setting(self, name, feature="this feature"):
        """Raises an exception if the given app setting is not defined."""
        if name not in self.settings:
            raise Exception("You must define the '%s' setting in your application to use %s" % (name, feature))

def test_require_setting():
    settings_with_db = {"database": "sqlite:///example.db"}
    settings_without_db = {}

    auth_with_db = GenericAuth(settings=settings_with_db)
    auth_without_db = GenericAuth(settings=settings_without_db)

    # Test case 1: Setting is present, so no exception should be raised
    try:
        auth_with_db.require_setting("database", feature="database connection")
    except Exception:
        assert False, "require_setting raised an exception when it should not have."

    # Test case 2: Setting is missing, so an exception should be raised
    caught_exception = False
    try:
        auth_without_db.require_setting("database", feature="database connection")
    except Exception as e:
        caught_exception = True
        assert e.args[0] == "You must define the 'database' setting in your application to use database connection"

    assert caught_exception, "require_setting did not raise an exception when it should have."

    # Test case 3: Setting is present, testing with a different key and feature
    caught_exception = False
    try:
        auth_with_db.require_setting("missing_key", feature="a different feature")
    except Exception as e:
        caught_exception = True
        assert e.args[0] == "You must define the 'missing_key' setting in your application to use a different feature"

    assert caught_exception, "require_setting did not raise an exception for a different missing key when it should have."

if __name__ == '__main__':
    test_require_setting()

