import re
from collections import Iterable
from datetime import date, datetime

import six

RE_UUID = '[a-z0-9]{8}-(?:[a-z0-9]{4}-){3}[a-z0-9]{12}'
RE_UUID_REGEX = re.compile('^{0}$'.format(RE_UUID))
RE_EFFECTS = '(?:[^/]+/)+'  # -/resize/(200x300/)*
UUID_WITH_EFFECTS_REGEX = re.compile('''
    /?
    (?P<uuid>{uuid})  # required
    (?:
        /
        (?:-/(?P<effects>{effects}))?
        ([^/]*)  # filename
    )?
$'''.format(uuid=RE_UUID, effects=RE_EFFECTS), re.VERBOSE)


class File(object):
    """File resource for working with user-uploaded files."""

    def __init__(self, cdn_url_or_file_id):
        matches = UUID_WITH_EFFECTS_REGEX.search(cdn_url_or_file_id)

        if not matches:
            raise ValueError("Couldn't find UUID")

        self._uuid = matches.groupdict()['uuid']
        self.default_effects = matches.groupdict()['effects']

        self._info_cache = None

    @property
    def uuid(self):
        return self._uuid

    @uuid.setter
    def uuid(self, value):
        match = RE_UUID_REGEX.match(value)

        if not match:
            raise ValueError('Invalid UUID: {0}'.format(value))

        self._uuid = match.group(0)

    @classmethod
    def construct_from(cls, file_info):
        """Constructs ``File`` instance from file information."""
        file_ = cls(file_info['uuid'])
        file_.default_effects = file_info.get('default_effects')
        file_._info_cache = file_info
        return file_

def test_construct_from():
    file_info1 = {
        'uuid': '1921953c-5d94-4e47-ba36-c2e1dd165e1a',
    }
    file1 = File.construct_from(file_info1)
    assert file1.uuid == '1921953c-5d94-4e47-ba36-c2e1dd165e1a'
    assert file1.default_effects is None

    file_info2 = {
        'uuid': '1921953c-5d94-4e47-ba36-c2e1dd165e1a',
        'default_effects': 'resize/200x300/',
    }
    file2 = File.construct_from(file_info2)
    assert file2.uuid == '1921953c-5d94-4e47-ba36-c2e1dd165e1a'
    assert file2.default_effects == 'resize/200x300/'

    file_info3 = {
        'uuid': '00000000-0000-0000-0000-000000000000',
    }
    file3 = File.construct_from(file_info3)
    assert file3.uuid == '00000000-0000-0000-0000-000000000000'
    assert file3.default_effects is None

if __name__ == '__main__':
    test_construct_from()

