import collections

from datetime import datetime

# Constants
CATEGORY_COMMIT = 'commit'
DEFAULT_DATETIME = datetime(1970, 1, 1)
DEFAULT_LAST_DATETIME = datetime(datetime.now().year + 1, 1, 1)

# Set up a basic logger
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger()


class GitRepository:
    """Class that represents a Git repository."""

    def __init__(self, uri, gitpath):
        self.uri = uri
        self.gitpath = gitpath

    @staticmethod
    def parse_git_log_from_iter(iterator):
        """Parse a Git log from a given iterator (e.g., subprocess output)."""
        parser = GitParser(iterator)
        for commit in parser.parse():
            yield commit

    def show(self, commits=None):
        """Generator that returns commit data for given commit hashes using `git show`."""
        if commits is None:
            commits = []

        git_cmd = ['git', '-C', self.gitpath, 'show', '--pretty=medium', '--stat']
        git_cmd.extend(commits)

        process = subprocess.Popen(
            git_cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            universal_newlines=True  # Ensures subprocess outputs strings (not bytes)
        )

        for line in iter(process.stdout.readline, ''):
            yield line.strip()

        process.stdout.close()
        process.stderr.close()
        process.wait()


class GitParser:
    """Git log parser."""

    def __init__(self, iterator):
        self.iterator = iterator

    def parse(self):
        """Parse the Git log from the iterator."""
        commit_data = {}
        for line in self.iterator:
            if line.startswith('commit '):
                if commit_data:
                    yield commit_data
                    commit_data = {}
                commit_data['commit'] = line[len('commit '):].strip()
            elif any(line.startswith(field) for field in ('Author:', 'Date:', 'Merge:')):
                field, value = line.split(':', 1)
                commit_data[field.lower()] = value.strip()
            elif commit_data.get('message') is not None:
                commit_data['message'] += line.strip()
            elif not line.strip():
                commit_data['message'] = ''
            else:
                continue
        if commit_data:
            # Yield the last commit
            yield commit_data

def test_show():
    repo_uri = "https://github.com/git/git"  # Example Git repo URI
    repo_path = "/tmp/git"  # Local path to clone the repo

    # Clone repo for testing purposes
    if not os.path.isdir(repo_path):
        subprocess.run(['git', 'clone', repo_uri, repo_path])

    repo = GitRepository(repo_uri, repo_path)
    result = list(repo.show(['HEAD']))
    expected = ["commit", "Author", "Date"]

    assert result[0].startswith(expected[0]), f"Expected substring '{expected[0]}' in first line"
    assert result[1].startswith(expected[1]), f"Expected substring '{expected[1]}' in second line"
    assert result[2].startswith(expected[2]), f"Expected substring '{expected[2]}' in third line"

if __name__ == '__main__':
    test_show()

