import os.path

def dict_merge(lft, rgt):
    """
    Recursive dict merge.

    Recursively merges dict's. not just simple lft['key'] = rgt['key'], if
    both lft and rgt have a key whose value is a dict then dict_merge is
    called on both values and the result stored in the returned dictionary.
    """
    if not isinstance(rgt, dict):
        return rgt
    result = deepcopy(lft)
    for key, val in rgt.items():
        if key in result and isinstance(result[key], dict):
            result[key] = dict_merge(result[key], val)
        else:
            result[key] = deepcopy(val)
    return result

def test_dict_merge():
    # Test when both dictionaries have nested dictionaries
    lft_1 = {'a': 1, 'b': {'c': 2}}
    rgt_1 = {'b': {'d': 3}, 'e': 4}
    expected_1 = {'a': 1, 'b': {'c': 2, 'd': 3}, 'e': 4}
    assert dict_merge(lft_1, rgt_1) == expected_1

    # Test when right dict has a non-dict value that overwrites left dict's value
    lft_2 = {'f': {'g': 5}, 'h': 6}
    rgt_2 = {'f': 7, 'i': 8}
    expected_2 = {'f': 7, 'h': 6, 'i': 8}
    assert dict_merge(lft_2, rgt_2) == expected_2

    # Test when one of the inputs is not a dict
    lft_3 = {'j': {'k': 9}}
    rgt_3 = 'not-a-dict'
    expected_3 = 'not-a-dict'
    assert dict_merge(lft_3, rgt_3) == expected_3

    print("All tests passed!")

if __name__ == '__main__':
    test_dict_merge()

