    test_labels = ["tokyo", "amsterdam", "paris"]
    expected = [2, 0, 1]
    transformed = le.transform(test_labels)
    assert np.array_equal(transformed, expected), "Transformed labels do not match expected values"

    unknown_labels = ["london"]
    raised = False
    try:
        le.transform(unknown_labels)
    except ValueError:
        raised = True
    assert raised, "Transforming unknown labels should raise an error"

    repeated_labels = ["tokyo", "tokyo", "amsterdam"]
    transformed_repeated = le.transform(repeated_labels)
    expected_repeated = [2, 2, 0]
    assert np.array_equal(transformed_repeated, expected_repeated), "Order and repetition of labels not preserved"

if __name__ == '__main__':
