class Client(object):
    '''A client library for the Storage Service.'''
    def __init__(self, client):
        '''
        Args:
           client: the low level api client
        '''
        self.api_client = client

    def get_parent(self, path):
        '''Get the parent entity of the entity pointed by the given path.'''
        if path == "/":
            raise Exception("This method does not accept projects in the path.")

        parent_path = "/".join(path.strip("/").split("/")[:-1])
        if parent_path == "":  # If parent_path is empty, we are looking for the root
            parent_path = "/"
        else:  # Otherwise we prepend "/" to form a valid path
            parent_path = "/" + parent_path
        return self.api_client.get_entity_by_query(parent_path)

