class Var:
    __slots__ = ("_name", "_ns", "_meta")  # Changed "meta" to "_meta" to avoid conflict with the instance variable.

    def __init__(self, ns: "Namespace", name: str) -> None:
        self._ns = ns
        self._name = name
        self._meta = None

    def __repr__(self):
        return f"#'{self.ns.name}/{self.name}"

    @property
    def ns(self) -> "Namespace":
        return self._ns

    @property
    def name(self) -> str:
        return self._name

    @property
    def meta(self):
        return self._meta

    @meta.setter
    def meta(self, meta):
        self._meta = meta

def _new_module(name: str, doc=None) -> types.ModuleType:
    """Create a new empty Python module."""
    mod = types.ModuleType(name, doc=doc)
    mod.__loader__ = None
    mod.__package__ = None
    mod.__spec__ = None
    return mod


class Namespace:
    __slots__ = (
        "_name",
        "_module",
        "_aliases",
    )

    def __init__(self, name: str, module: types.ModuleType = None) -> None:
        self._name = name
        self._module = module

        self._aliases = {}

    @property
    def name(self) -> str:
        return self._name

    @property
    def aliases(self) -> Dict:
        """A mapping between a symbolic alias and another Namespace. The
        fully qualified name of a namespace is also an alias for itself."""
        return self._aliases

    def __repr__(self):
        return f"{self._name}"

    def add_alias(self, alias: str, namespace: str) -> None:
        """Add a string alias for the given Namespace."""
        self._aliases[alias] = namespace

    @classmethod
    def get_or_create(
        cls, name: str, module: types.ModuleType = None
    ) -> "Namespace":
        """Get the namespace bound to the name in the global namespace
        cache, creating it if it does not exist.
        Return the namespace."""
        return cls(name, module)

CORE_NS = "basilisp.core"
NS_VAR_NAME = "*ns*"
ns = Namespace.get_or_create(CORE_NS)
ns.add_alias(NS_VAR_NAME, CORE_NS)

def test_add_alias():
    test_namespace = Namespace('test.namespace')
    test_namespace.add_alias('test_alias', 'alias.to.namespace')
    assert test_namespace.aliases['test_alias'] == 'alias.to.namespace', "Alias not correctly added."

    test_namespace.add_alias('another_alias', 'another.namespace')
    assert len(test_namespace.aliases) == 2, "Incorrect number of aliases after adding second one."
    assert test_namespace.aliases['another_alias'] == 'another.namespace', "Second alias not correctly added."

    test_namespace.add_alias(test_namespace.name, test_namespace.name)
    assert test_namespace.aliases[test_namespace.name] == test_namespace.name, "Namespace name itself should be an alias for itself."

if __name__ == '__main__':
