import threading

class TransferCoordinator(object):
    def __init__(self, transfer_id):
        self.transfer_id = transfer_id
        self.cancelled = False
        self.cancel_msg = None
        self.cancel_exc_type = None

    def cancel(self, msg, exc_type):
        self.cancelled = True
        self.cancel_msg = msg
        self.cancel_exc_type = exc_type

class TransferCoordinatorController(object):
    def __init__(self):
        self._lock = threading.Lock()
        self._tracked_transfer_coordinators = set()

    @property
    def tracked_transfer_coordinators(self):
        with self._lock:
            return copy.copy(self._tracked_transfer_coordinators)

    def add_transfer_coordinator(self, transfer_coordinator):
        with self._lock:
            self._tracked_transfer_coordinators.add(transfer_coordinator)

    def remove_transfer_coordinator(self, transfer_coordinator):
        with self._lock:
            self._tracked_transfer_coordinators.remove(transfer_coordinator)

    def cancel(self, msg='', exc_type=None):
        for transfer_coordinator in self.tracked_transfer_coordinators:
            transfer_coordinator.cancel(msg, exc_type)

def test_cancel():
    transfer_controller = TransferCoordinatorController()
    transfer_coordinators = [TransferCoordinator(i) for i in range(5)]
    for tc in transfer_coordinators:
        transfer_controller.add_transfer_coordinator(tc)

    # Test cancelling when there are TransferCoordinators:
    transfer_controller.cancel("Test Cancel", Exception)
    assert all(tc.cancelled for tc in transfer_coordinators)  # Check they are all cancelled
    assert all(tc.cancel_msg == "Test Cancel" for tc in transfer_coordinators)  # With correct message
    assert all(tc.cancel_exc_type is Exception for tc in transfer_coordinators)  # And correct exception type

    # Test cancelling with no TransferCoordinators to cancel:
    transfer_controller = TransferCoordinatorController()  # No TransferCoordinators added
    try:
        transfer_controller.cancel("Test Cancel", Exception)  # Should not raise
    except Exception as e:
        assert False, "Cancelling with no transfer coordinators should not raise an exception"

if __name__ == "__main__":
    test_cancel()

