class FoldableABC(abc.ABC):
    @abc.abstractmethod
    def fold_left(self, z: Z, f: Callable[[Z, A], Z]) -> Z:
        pass


# An example Foldable class that works with lists
class ListFoldable(FoldableABC):
    def __init__(self, items):
        self.items = items

    def fold_left(self, z: Z, f: Callable[[Z, A], Z]) -> Z:
        result = z
        for item in self.items:
            result = f(result, item)
        return result


class Foldable:
    @staticmethod
    def fold_map(fa: FoldableABC, z: B, f: Callable[[A], B], g: Callable[[Z, B], Z] = operator.add) -> Z:
        ''' map `f` over the Foldable, then fold over the result using the supplied
        initial element `z` and operation `g`, defaulting to addition for the latter.'''
        def map_and_fold(acc, item):
            return g(acc, f(item))
        return fa.fold_left(z, map_and_fold)


def test_fold_map():
    # Test case 1: using square function with sum
    numbers = ListFoldable([1, 2, 3, 4, 5])
