class KillRing:
    def __init__(self):
        self.clear()

    def clear(self):
        self._index = -1
        self._ring = []

    def kill(self, text):
        self._ring.append(text)

    def yank(self):
        self._index = len(self._ring)
        return self.rotate()

    def rotate(self):
        self._index -= 1
        if self._index >= 0:
            return self._ring[self._index]
        return None

class QtKillRing:
    def __init__(self):
        self._ring = KillRing()
        self._prev_yank = None

    def clear(self):
        self._ring.clear()
        self._prev_yank = None

    def kill(self, text):
        self._ring.kill(text)

    def rotate(self):
        if self._prev_yank is not None:
            text = self._ring.rotate()
            if text is not None:
                self._prev_yank = text
        else:
            self._prev_yank = self._ring.yank()

def test_rotate():
    qt_kill_ring = QtKillRing()
    qt_kill_ring.kill("A")
    qt_kill_ring.kill("B")
    qt_kill_ring.kill("C")

    # First rotate should set _prev_yank to "C"
    qt_kill_ring.rotate()
    assert qt_kill_ring._prev_yank == "C", f"Failed: Expected 'C', got {qt_kill_ring._prev_yank}"

    # Second rotate should set _prev_yank to "B"
    qt_kill_ring.rotate()
    assert qt_kill_ring._prev_yank == "B", f"Failed: Expected 'B', got {qt_kill_ring._prev_yank}"

    # Third rotate should set _prev_yank to "A"
    qt_kill_ring.rotate()
    assert qt_kill_ring._prev_yank == "A", f"Failed: Expected 'A', got {qt_kill_ring._prev_yank}"

if __name__ == "__main__":
    test_rotate()

