import re

# Original implementation of CommandChainDispatcher
class CommandChainDispatcher:
    def __init__(self):
        self.commands = []

    def add(self, obj, priority=0):
        self.commands.append((priority, obj))
        self.commands.sort(reverse=True)  # Sort by priority, highest first

    def __iter__(self):
        for priority, obj in self.commands:
            yield (priority, obj)

class StrDispatch(object):
    def __init__(self):
        self.strs = {}
        self.regexs = {}

    def add_s(self, s, obj, priority=0 ):
        """ Adds a target 'string' for dispatching """
        chain = self.strs.get(s, CommandChainDispatcher())
        chain.add(obj, priority)
        self.strs[s] = chain

    def add_re(self, regex, obj, priority=0 ):
        """ Adds a target regexp for dispatching """
        chain = self.regexs.get(regex, CommandChainDispatcher())
        chain.add(obj, priority)
        self.regexs[regex] = chain

    def dispatch(self, key):
        if key in self.strs:
            yield self.strs[key]
        for r, obj in self.regexs.items():
            if re.match(r, key):
                yield obj

    def flat_matches(self, key):
        """ Yield all 'value' targets, without priority """
        for val in self.dispatch(key):
            for el in val:
                yield el[1]

def test_add_re():
    # Create a new StrDispatch instance
    dispatcher = StrDispatch()

    # Add regex and object
    dispatcher.add_re(r'foo\d+', 'matched_foo', priority=1)
    results = list(dispatcher.flat_matches('foo123'))
    assert 'matched_foo' in results

    # Add multiple objects with different priorities to the same regex
    dispatcher.add_re(r'foo\d+', 'high_priority', priority=2)
    dispatcher.add_re(r'foo\d+', 'low_priority', priority=0)
    results = list(dispatcher.flat_matches('foo123'))
    assert results == ['high_priority', 'matched_foo', 'low_priority']

    # Add a regex that does not match any key
    dispatcher.add_re(r'bar\d+', 'matched_bar', priority=1)
    results = list(dispatcher.flat_matches('foo123'))
    assert 'matched_bar' not in results

if __name__ == "__main__":
    test_add_re()

