import collections

class ByteQueue(object):
    def __init__(self):
        self._parts = collections.deque()
        self._len = 0

    def enqueue(self, s):
        self._parts.append(s)
        self._len += len(s)

    def dequeue(self, n):
        if self._len < n:
            raise ValueError("Not enough bytes in the queue")
        self._len -= n

        def part_generator(n):
            remaining = n
            while remaining:
                part = self._parts.popleft()
                if len(part) <= remaining:
                    yield part
                    remaining -= len(part)
                else:
                    yield part[:remaining]
                    self._parts.appendleft(part[remaining:])
                    remaining = 0

        return "".join(part_generator(n))

    def drop(self, n):
        if self._len < n:
            raise ValueError("Not enough bytes in the queue")
        self._len -= n
        remaining = n
        while remaining:
            part = self._parts.popleft()
            if len(part) <= remaining:
                remaining -= len(part)
            else:
                self._parts.appendleft(part[remaining:])
                remaining = 0

    def peek(self, n):
        if self._len < n:
            raise ValueError("Not enough bytes in the queue")

        def part_generator(n):
            remaining = n
            for part in self._parts:
                if len(part) <= remaining:
                    yield part
                    remaining -= len(part)
                else:
                    yield part[:remaining]
                    remaining = 0
                if remaining == 0:
                    break

        return "".join(part_generator(n))

    def all(self):
        return "".join(self._parts)

    def __len__(self):
        return self._len

def test_dequeue():
    queue = ByteQueue()
    queue.enqueue("abc")
    queue.enqueue("def")

    assert queue.dequeue(3) == "abc", "Failed to dequeue the expected string 'abc'"
    assert len(queue) == 3, "Queue length should be 3 after dequeuing 3 bytes"

    queue.enqueue("ghi")
    assert queue.dequeue(5) == "defgh", "Failed to dequeue the expected string 'defgh'"
    assert len(queue) == 1, "Queue length should be 1 after dequeuing 5 more bytes"

    # Enqueue once more to check if dequeue works with a previously dequeued queue
    queue.enqueue("jkl")
    assert queue.dequeue(2) == "ij", "Failed to dequeue the expected string 'ij'"

    try:
        queue.dequeue(10)
        assert False, "Expected a ValueError for dequeuing too many bytes"
    except ValueError:
        assert True, "Correctly raised ValueError when not enough bytes available"

if __name__ == '__main__':
    test_dequeue()

