class Stinespring(QuantumChannel):
    def __init__(self, data, input_dims=None, output_dims=None):
        super().__init__(data, input_dims, output_dims)

    def _tensor_product(self, other, reverse=False):
        data_self = self._data
        data_other = other._data
        input_dims = [self.input_dims[0] * other.input_dims[0]]
        output_dims = [self.output_dims[0] * other.output_dims[0]]
        if reverse:
            return Stinespring(np.kron(data_other, data_self), input_dims, output_dims)
        else:
