class Real:
    """Node for an OPENQASM real number."""

    def __init__(self, value):
        """Create the real node."""
        self.value = value

    def qasm(self, prec=15):
        """Return the corresponding OPENQASM string."""
        if self.value == pi:
            return "pi"

        # Check if it's a rational number and handle it accordingly
        if isinstance(self.value, Rational):
            # Convert the rational number to a floating-point string format
            return str(float(self.value))

        return ccode(self.value, precision=prec)

    def latex(self, prec=15, nested_scope=None):
        """Return the corresponding math mode latex string."""
        return latex(self.value)

    def sym(self, nested_scope=None):
        """Return the correspond symbolic number."""
        return self.value

    def real(self, nested_scope=None):
        """Return the corresponding floating point number."""
        return float(self.value.evalf())

def test_qasm():
    # Test with a value of pi
    real_pi = Real(pi)
    assert real_pi.qasm() == "pi", "qasm() method failed for the value of pi"

    # Test with a simple rational number
    rational_number = Real(Rational(1, 2))
    assert rational_number.qasm() == "0.5", "qasm() method failed for the rational number"

    # Test with a simple integer
    integer_number = Real(5)
    assert integer_number.qasm() == "5", "qasm() method failed for the integer number"

if __name__ == "__main__":
    test_qasm()

