import numpy as np

class HyperLogLog(object):

    def _get_alpha(self, p):
        if not (4 <= p <= 16):
            raise ValueError("p=%d should be in range [4 : 16]" % p)
        if p == 4:
            return 0.673
        if p == 5:
            return 0.697
        if p == 6:
            return 0.709
        return 0.7213 / (1.0 + 1.079 / (1 << p))

    def __init__(self, p=8, reg=None):
        if reg is None:
            self.p = p
            self.m = 1 << p
            self.reg = np.zeros((self.m,), dtype=np.int8)
        else:
            self.m = reg.size
            self.p = _bit_length(self.m) - 1
            if 1 << self.p != self.m:
                raise ValueError("The imported register has incorrect size. Expect a power of 2.")
            self.reg = reg

        self.alpha = self._get_alpha(self.p)

    def clear(self):
        '''
        Reset the current HyperLogLog to empty.
        '''
        self.reg = np.zeros((self.m,), dtype=np.int8)

def test_clear():
    # Create an instance of HyperLogLog with p=8
    hll = HyperLogLog(p=8)

    # Check that the register is initially all zeros
    assert np.all(hll.reg == 0), "The register should be initialized to all zeros"

    # Modify the state of the register to all ones
    hll.reg = np.ones((hll.m,), dtype=np.int8)

    # Assert that the modification is successful
    assert np.all(hll.reg == 1), "The register should have been modified to all ones"

    # Clears the state of the register
    hll.clear()

    # Check that the register is reset to all zeros
    assert np.all(hll.reg == 0), "The register should have been cleared to all zeros"

if __name__=='__main__':
    test_clear()

