class AzureAsyncOperationHttpError(Exception):
    def __init__(self, message, status, result):
        super().__init__(message)  # Initialize the base Exception with the message
        self.message = message
        self.status = status
        self.result = result


class _ServiceManagementClient(object):
    def wait_for_operation_status(self,
                                  request_id, wait_for_status='Succeeded', timeout=30, sleep_interval=5,
                                  progress_callback=None,
                                  success_callback=None,
                                  failure_callback=None):
        loops = timeout // sleep_interval
        start_time = time.time()
        for _ in range(int(loops)):
            result = self.get_operation_status(request_id)
            elapsed = time.time() - start_time
            if result.status == wait_for_status:
                if success_callback is not None:
                    success_callback(elapsed)
                return result
            elif result.error:
                if failure_callback is not None:
                    ex = AzureAsyncOperationHttpError('Error', result.status, result)
                    failure_callback(elapsed, ex)
                return result
            else:
                if progress_callback is not None:
                    progress_callback(elapsed)
                time.sleep(sleep_interval)

        # Instead of preparing an exception, it should be raised
        raise AzureAsyncOperationHttpError('Timeout', 'Failed', Operation(status='Failed', error=True))

    def get_operation_status(self, request_id):
        # This is a dummy method that mimics the intended behavior without making actual API calls.
        if request_id == 'success':
            return Operation(status='Succeeded', error=False)
        elif request_id == 'error':
            return Operation(status='Failed', error=True)
        else:
            return Operation(status='InProgress', error=False)


def test_wait_for_operation_status():
    client = _ServiceManagementClient()

