    else:
        raise TypeError(f"Expected str or bytes, got {type(s).__name__}")

class Client(object):
    def __init__(self, context=None):
        if context is None:
            context = zmq.Context.instance()
        self._context = context

    def send_apply_request(self, socket, f, args=None, kwargs=None, subheader=None, track=False, ident=None):
        args = args if args is not None else []
        kwargs = kwargs if kwargs is not None else {}
        subheader = subheader if subheader is not None else {}

        if not callable(f):
            raise TypeError("f must be callable, not %s" % type(f))
        if not isinstance(args, (tuple, list)):
            raise TypeError("args must be tuple or list, not %s" % type(args))
        if not isinstance(kwargs, dict):
            raise TypeError("kwargs must be dict, not %s" % type(kwargs))
        if not isinstance(subheader, dict):
            raise TypeError("subheader must be dict, not %s" % type(subheader))

        indents = [cast_bytes(ident)] if ident else []

        # Convert the function object f to a string that represents the function name
        func_name = f.__name__ if hasattr(f, "__name__") else str(f)

        req = dict(f=func_name, args=args, kwargs=kwargs, track=track, subheader=subheader)
        json_msg = json.dumps(req)
        socket.send_multipart(indents + [json_msg.encode('utf-8')], flags=zmq.SNDMORE if track else 0)

        if track:
            return socket.getsockopt(zmq.EVENTS)
        else:
            return None

