    # Test 1: Test if the decorator returns a function
    @activate
    def dummy_function():
        return "decorated_function"

    assert callable(dummy_function), "activate should return a callable when used as a decorator."

    # Test 2: Test the decorator with a regular function
    assert dummy_function() == "decorated_function", "The wrapper should return the correct result from the decorated function."

    # Test 3: Test `activate` without using it as a decorator
    assert activate() is None, "activate should return None when not used as a decorator."

if __name__ == '__main__':
