        txt = s
        found = (txt in self._hsig)
        if not found and self.parent is not None:
            if self.state == StateScope.EMBEDDED:
                found = (txt in self.parent._hsig)  # Changed to directly access _hsig of parent (assumption due to absence of get method)
        return found

    def symmetric_difference_update(self, oset: object) -> object:
        skey = set()
        keys = list(self._hsig.keys())
        for k in keys:
            if k in oset._hsig:  # Access other scope's _hsig directly
                skey.add(k)
        for k in oset._hsig.keys():
            if k not in skey:
                self._hsig[k] = oset._hsig[k]  # Assuming get(k) is equivalent to _hsig[k]
