from urllib.parse import urljoin, urlparse, urlunparse, parse_qsl, urlencode

def update_scheme(current, target):
    """
    Take the scheme from the current URL and applies it to the
    target URL if the target URL startswith // or is missing a scheme
    :param current: current URL
    :param target: target URL
    :return: target URL with the current URLs scheme
    """
    target_p = urlparse(target)
    if not target_p.scheme and target_p.netloc:
        return "{0}:{1}".format(urlparse(current).scheme,
                                urlunparse(target_p))
    elif not target_p.scheme and not target_p.netloc:
        return "{0}://{1}".format(urlparse(current).scheme,
                                  urlunparse(target_p))
    else:
        return target

def test_update_scheme():
    assert update_scheme('https://example.com', '//target.com') == 'https://target.com', "Scheme should be applied to target URL"
    assert update_scheme('http://example.com', 'target.com/path') == 'http://target.com/path', "Scheme should be applied with '://' to target URL missing both scheme and netloc"
    assert update_scheme('https://example.com', 'http://already.has.scheme.com') == 'http://already.has.scheme.com', "Target URL with scheme should remain unchanged"

if __name__ == "__main__":
    test_update_scheme()  # Run the test function
    print("All tests passed.")

