def list2dict2(lst, default=''):
    """Takes a list and turns it into a dict.
    Much slower than list2dict, but more versatile. This version can take
    lists with sublists of arbitrary length (including scalars)."""

    dic = {}
    for elem in lst:
        if isinstance(elem, (list, tuple)):  # Corrected from `types.ListType` and `types.TupleType`
            size = len(elem)
            if size == 0:
                pass
            elif size == 1:
                dic[elem[0]] = default  # Fixed the issue; `elem` should be indexed at 0 for dict key when size == 1
            else:
                k, v = elem[0], elem[1:]
                if len(v) == 1: v = v[0]
                dic[k] = v
        else:
            dic[elem] = default
    return dic

