from threading import Event
from queue import Queue

log = logging.getLogger(__name__)

class WebSocketConnection:

    def __init__(self, log_level=None):
        self.connected = Event()
        self.q = Queue()
        self.channel_configs = {}

    def send(self, **kwargs):
        self.q.put(kwargs)


class QueueProcessor:

    def __init__(self, queue, log_level=None):
        self.queue = queue
        self.tickers = {}
        self.books = {}
        self.raw_books = {}
        self.trades = {}
        self.candles = {}
        self.account = {}


class BtfxWss:

    def __init__(self, key=None, secret=None, log_level=None):
        self.key = key if key else ''
        self.secret = secret if secret else ''
        self.conn = WebSocketConnection(log_level=log_level)
        self.queue_processor = QueueProcessor(self.conn.q, log_level=log_level)

    def is_connected(func):
        def wrapped(self, *args, **kwargs):
            if self.conn and self.conn.connected.is_set():
                return func(self, *args, **kwargs)
            else:
                log.error("Cannot call %s() on unestablished connection!", func.__name__)
                return None
        return wrapped

    @is_connected
    def unsubscribe_from_candles(self, pair, timeframe=None, **kwargs):
        valid_tfs = ['1m', '5m', '15m', '30m', '1h', '3h', '6h', '12h', '1D', '7D', '14D', '1M']
        if timeframe:
            if timeframe not in valid_tfs:
                raise ValueError("timeframe must be any of %s" % valid_tfs)
        else:
            timeframe = '1m'

        # Check if pair has prefix 't', if not then add it
        pair = 't' + pair if not pair.startswith('t') else pair
        identifier = ('candles', pair, timeframe)
        key = 'trade:' + timeframe + ':' + pair

        channel_id = self.conn.channel_configs.get(identifier)
        if channel_id is None:
            raise ValueError("No subscription found for the specified pair and timeframe")
        q = {'event': 'unsubscribe', 'chanId': channel_id}
        q.update(kwargs)
        self.conn.send(**q)
        self.conn.channel_configs.pop(identifier)

    def start(self, ):
        self.conn.connected.set()

    def stop(self):
        self.conn.connected.clear()

def test_unsubscribe_from_candles():
    btfx = BtfxWss()
    btfx.start()  # Start the connection to simulate an established connection

    # Pre-configuration to simulate a subscription exists in the system
    test_identifier = ('candles', 'tBTCUSD', '1h')
    test_channel_id = 42
    btfx.conn.channel_configs[test_identifier] = test_channel_id

    # Test unsubscribe works with valid parameters
    btfx.unsubscribe_from_candles("BTCUSD", timeframe="1h")
    assert test_identifier not in btfx.conn.channel_configs

    # Test error raised when unsubscribing with an invalid timeframe
    try:
        btfx.unsubscribe_from_candles("BTCUSD", timeframe="invalid_tf")
    except ValueError as ve:
        assert str(ve) == "timeframe must be any of ['1m', '5m', '15m', '30m', '1h', '3h', '6h', '12h', '1D', '7D', '14D', '1M']"

    # Test error raised when unsubscribing without an existing subscription
    try:
        btfx.unsubscribe_from_candles("BTCUSD", timeframe="1h")
    except ValueError as ve:
        assert str(ve) == "No subscription found for the specified pair and timeframe"

    btfx.stop()  # Stop the connection

if __name__ == "__main__":
