from sqlalchemy.sql.expression import desc
from unittest.mock import MagicMock

class Ordering(object):
    """Helper class for column sorting."""

    def __init__(self, options, selected):
        self.options = options
        if selected in options:
            self._selected = selected
            self.asc = True
        elif selected and selected[0] == '-' and selected[1:] in options:
            self._selected = selected[1:]
            self.asc = False
        else:
            self._selected = None
            self.asc = None

    def reverse(self, col):
        if col in self.options:
            if self.is_selected(col):
                return col if not self.asc else '-{0}'.format(col)
            else:
                return col
        return None

    def dir(self, col, asc='asc', desc='desc'):
        if col == self._selected and self.asc is not None:
            return asc if self.asc else desc
        else:
            return None

    def is_selected(self, col):
        return col == self._selected

    def selected(self):
        if self._selected:
            return self._selected if self.asc else "-{0}".format(self._selected)
        return None

class QueryOrdering(Ordering):
    """Helper class for column sorting based on SQLAlchemy queries."""

    def __init__(self, query, options, selected):
        super(QueryOrdering, self).__init__(options, selected)
        self.query = query

    def items(self):
        if self._selected:
            if self.asc:
                return f"ordered by {self._selected}"
            else:
                return f"ordered by desc({self._selected})"
        return self.query

def test_items():
    # Set up a mock query object
    query_mock = MagicMock()
    query_mock.order_by = MagicMock(side_effect=lambda x: f"ordered by {x}")
    options = ["column1", "column2", "column3"]

    # Test ascending order
    selected = "column2"
    query_ordering = QueryOrdering(query_mock, options, selected)
    assert query_ordering.items() == "ordered by column2"

    # Test descending order
    selected = "-column2"
