import packaging.version as vers

class VersionReleaseChecks(object):
    def __init__(self, versions, strictness='strict'):
        self.versions = versions
        self.strictness = strictness

    @staticmethod
    def _version(version, strictness):
        if strictness == 'strict':
            return version
        elif strictness == 'loose':
            return vers.parse(version).public
        elif strictness == 'base-only':
            return vers.parse(version).base_version
        else:
            raise ValueError("Bad strictness: " + str(strictness))

    def consistency(self, desired_version=None, include_package=False,
                    strictness=None):
        keys_to_check = list(self.versions.keys())
        if not include_package and 'package' in keys_to_check:
            keys_to_check.remove('package')

        if desired_version is None:
            try:
                desired_version = self.versions['setup.py']
            except KeyError:
                desired_version = self.versions[keys_to_check[0]]

        if strictness is None:
            strictness = self.strictness
        desired = self._version(desired_version, strictness)

        error_keys = []
        for key in keys_to_check:
            test = self._version(self.versions[key], strictness)
            if test != desired:
                error_keys += [key]

        msg = ""
        for key in error_keys:
            msg += "Error: desired {d} != {v} ({k})\n".format(
                d=str(desired),
                v=str(self.versions[key]),
                k=str(key)
            )
        return msg

    @staticmethod
    def is_release(version, expected=True):
        version = str(version)
        msg = ""
        if expected is vers.parse(version).is_prerelease:
            msg += "Version " + str(version) + " is "
            if expected:
                msg += "not "
            msg += "a release version\n"

        return msg

def test_consistency():
    # Test case where all versions match
    versions_matching = {
        "setup.py": "1.2.3",
        "file1.py": "1.2.3",
        "file2.py": "1.2.3"
    }
    check = VersionReleaseChecks(versions_matching)
    msg = check.consistency()
    assert msg == "", "All versions should match"

    # Test case where one version does not match
    versions_mismatching = {
        "setup.py": "1.2.3",
        "file1.py": "1.2.4",
        "file2.py": "1.2.3"
    }
    check = VersionReleaseChecks(versions_mismatching)
    msg = check.consistency()
    assert "file1.py" in msg, "file1.py should not match the desired version"

    # Test case with 'base-only' strictness
    versions_base_only = {
        "setup.py": "1.2.3+build1",
        "file1.py": "1.2.3+build2",
        "file2.py": "1.2.3"
    }
    check = VersionReleaseChecks(versions_base_only, strictness='base-only')
    msg = check.consistency()
    assert msg == "", "All versions should match based on base version only"

if __name__ == '__main__':
    test_consistency()

