class UserHandler(object):

    def __init__(self):
        self.user_collection = {}

    def update_user(self, user_obj):
        """Update an existing user."""
        updated_user = self.user_collection[user_obj['_id']] = user_obj
        return updated_user

    def add_user(self, user_obj):
        """Add a user object to the dictionary."""
        if '_id' not in user_obj:
            user_obj['_id'] = user_obj['email']

        if user_obj['_id'] in self.user_collection:
            raise ValueError("User {} already exists in database".format(user_obj['email']))

        self.user_collection[user_obj['_id']] = user_obj

        return user_obj

    def users(self, institute=None):
        """Return all users from the dictionary."""
        if institute:
            res = [user for user in self.user_collection.values() if institute in user['institutes']]
        else:
            res = list(self.user_collection.values())

        return res

    def user(self, email):
        """Fetch a user from the dictionary."""
        user_obj = self.user_collection.get(email)

        return user_obj

    def delete_user(self, email):
        """Delete a user from the dictionary."""
        if email not in self.user_collection:
