import numpy as np
import scipy.interpolate

def amplitude_to_db(S, ref=1.0, amin=1e-05, top_db=80.0):
    S = np.asarray(S)

    if amin <= 0:
        raise Exception('amin must be strictly positive')

    if np.issubdtype(S.dtype, np.complexfloating):
        S = np.abs(S)

    if S.min() < 0:
        raise Exception('Magnitude spectrogram has negative values')

    if np.isscalar(ref):
        ref = float(ref)
        ref_value = np.abs(ref)
        log_spec = 20.0 * np.log10(np.maximum(amin, S / ref_value))  # Fixed from 10.0 to 20.0
    else:
        raise Exception('Spectrogram normalization is only defined in scalar values')

    if top_db is not None:
        if top_db < 0:
            raise Exception('top_db must be non-negative')
        log_spec = np.maximum(log_spec, log_spec.max() - top_db)

    return log_spec

def test_amplitude_to_db():
    assert np.allclose(amplitude_to_db(np.array([2.0]), ref=1.0), 20.0 * np.log10(2.0))
    assert np.allclose(amplitude_to_db(np.array([0.5]), top_db=80.0), 20.0 * np.log10(0.5))
    assert np.allclose(amplitude_to_db(np.array([1e-05]), ref=1.0, amin=1e-05), 20.0 * np.log10(1e-05))

    S = np.array([1e-05, 1e-01, 1e+01])
    S_db = amplitude_to_db(S, ref=1.0, amin=1e-05, top_db=40.0)
    assert np.allclose(S_db, [S_db.max() - 40.0 if s_db < S_db.max() - 40.0 else s_db for s_db in S_db])

if __name__ == '__main__':
    test_amplitude_to_db()

