        self._now_is_event_dependent = is_completly_event_dependent
        self.parentStm = parentStm
        self._inputs = []
        self._outputs = []
        self._enclosed_for = None

        self._sensitivity = sensitivity
        self.rank = 0

    def _discover_enclosure(self) -> None:
        # Assuming enclosure means outputs that are within _enclosed_for set
        self._enclosed_for = set(o for o in self._outputs if o in self._enclosed_for)

    @staticmethod
    def _discover_enclosure_for_statements(statements: List['HdlStatement'],
                                           outputs: List['HdlStatement']):
        result = set()
        drivers_for_outputs = set()

        if not statements:
            return result

        for stm in statements:
            stm._discover_enclosure()

        for o in outputs:
            for stm in statements:
                if o in stm._outputs:
                    # Only add the output to the set if it's not already there (no multiple drivers)
                    if o not in drivers_for_outputs:
                        drivers_for_outputs.add(o)
                        if o in stm._enclosed_for:
                            result.add(o)

        return result

