class NodeOp(Enum):
    CONST = "const"

class ConstType(Enum):
    BOOL = "bool"
    NIL = "nil"
    STRING = "string"
    NUMBER = "number"
    KEYWORD = "keyword"
    SYMBOL = "symbol"
    PY_DICT = "py-dict"
    PY_LIST = "py-list"
    PY_SET = "py-set"
    PY_TUPLE = "py-tuple"
    VECTOR = "vector"
    MAP = "map"
    SET = "set"
    SEQ = "seq"
    REGEX = "regex"
    FRACTION = "fraction"
    DECIMAL = "decimal"
    INST = "inst"
    UUID = "uuid"

class Const:
    def __init__(self, op: NodeOp, type: ConstType, val):
        self.op = op
        self.type = type
        self.val = val

def _const_node_to_py_ast(ctx, lisp_ast: Const) -> ast.AST:
    """Generate Python AST nodes for a :const Lisp AST node."""
    assert isinstance(lisp_ast, Const), "_const_node_to_py_ast only handles Const nodes"

    if lisp_ast.type == ConstType.STRING:
        return ast.Str(s=str(lisp_ast.val))
    elif lisp_ast.type == ConstType.NUMBER:
        return ast.Num(n=lisp_ast.val)
    elif lisp_ast.type == ConstType.BOOL:
        return ast.NameConstant(value=lisp_ast.val)
    elif lisp_ast.type == ConstType.NIL:
        return ast.NameConstant(value=None)
    elif lisp_ast.type == ConstType.PY_LIST:
        return ast.List(elts=[_const_node_to_py_ast(ctx, x) for x in lisp_ast.val], ctx=ast.Load())
    elif lisp_ast.type == ConstType.PY_TUPLE:
        return ast.Tuple(elts=[_const_node_to_py_ast(ctx, x) for x in lisp_ast.val], ctx=ast.Load())
    elif lisp_ast.type == ConstType.PY_DICT:
        return ast.Dict(keys=[_const_node_to_py_ast(ctx, x) for x in lisp_ast.val.keys()],
                        values=[_const_node_to_py_ast(ctx, y) for y in lisp_ast.val.values()])
    elif lisp_ast.type == ConstType.KEYWORD:
        # This case is specific to the context of this Lisp dialect,
        # we would implement keyword handling here
        pass
    elif lisp_ast.type == ConstType.SYMBOL:
        # This case is specific to the context of this Lisp dialect,
        # we would implement symbol handling here
        pass
    # Add cases for other types as needed

    raise NotImplementedError(f"No implementation for ConstType {lisp_ast.type}")

def test__const_node_to_py_ast():
    # Test with a constant string
    str_node = Const(op=NodeOp.CONST, type=ConstType.STRING, val="Hello, World!")
    str_py_ast = _const_node_to_py_ast(None, str_node)
    assert isinstance(str_py_ast, ast.Str) and str_py_ast.s == "Hello, World!"

    # Test with a constant number
    num_node = Const(op=NodeOp.CONST, type=ConstType.NUMBER, val=42)
    num_py_ast = _const_node_to_py_ast(None, num_node)
    assert isinstance(num_py_ast, ast.Num) and num_py_ast.n == 42

    # Test with a constant boolean
    bool_node = Const(op=NodeOp.CONST, type=ConstType.BOOL, val=True)
    bool_py_ast = _const_node_to_py_ast(None, bool_node)
    assert isinstance(bool_py_ast, ast.NameConstant) and bool_py_ast.value == True

