    def internal_xml_to_dict(element):
        dct = {element.tag: {} if element.attrib else None}
        children = list(element)
        if children:
            dd = defaultdict(list)
            for dc in map(internal_xml_to_dict, children):
                for k, v in dc.items():
                    dd[k].append(v)
            dct = {element.tag: {k: v[0] if len(v) == 1 else v for k, v in dd.items()}}
        if element.text:
            text = element.text.strip()
            if children or element.attrib:
                if text:
                    dct[element.tag]['_text'] = text
            else:
                dct[element.tag] = text
        if element.attrib:
            dct[element.tag].update(('@' + k, v) for k, v in element.attrib.items())
        return dct

    tree = ET.fromstring(raw_xml)
    return internal_xml_to_dict(tree)

