    assert not _broker.subscribe('event_one', callback_one), "Double subscription occurred, should return False."

    # Additional test to ensure that different callback for the same event can be registered
    assert _broker.subscribe('event_one', callback_two), "Subscription of different callbacks to the same event should be successful."

    print('All test cases for _Broker.subscribe passed successfully.')

if __name__ == '__main__':
    _broker = _Broker()
    test_subscribe()

