    sys.modules["dummy_extension"] = DummyExtension

    # Test: unload_extension should return "Unloaded successfully."
    result = em.unload_extension("dummy_extension")
    assert result == "Unloaded successfully.", "Failed to unload the extension properly."

    # Test: unloading an extension not in sys.modules should do nothing (no error)
    result = em.unload_extension("non_existent_module")
    assert result is None, "Attempting to unload an extension not in sys.modules should return None."

