    sys.modules["module_without_unload"] = object()
    result = em.unload_extension("module_without_unload")
    assert result is None, "Module without unload_ipython_extension should return None."

    # Cleanup
    for module_str in ["dummy_extension", "module_without_unload"]:
        if module_str in sys.modules:
            del sys.modules[module_str]

