    @contextmanager
    def temp_flags(self, **flags):
        origin_block = self.block
        self.block = flags.get('block', self.block)
        try:
            yield  # This will return control to the block wrapped by the 'with' statement
        finally:
            self.block = origin_block  # This ensures the block is reset when the 'with' block is exited


class RemoteFunction:
    def __init__(self, view, f, block=None, **flags):
        self.view = view
        self.func = f
        self.block = block if block is not None else view.block
        self.flags = flags

    def __call__(self, *args, **kwargs):
        print(f"Calling remote function '{self.func.__name__}' with args={args} and kwargs={kwargs}")
        with self.view.temp_flags(block=self.block, **self.flags):  # No changes needed here since temp_flags now correctly works as a context manager
            return self.view.apply(self.func, *args, **kwargs)


