import math
import numpy as np
import scipy.linalg as la

class Quaternion:
    def __init__(self, data):
        self.data = np.asarray(data, dtype=float)

    def __call__(self, idx):
        return self.data[idx]

    def __mul__(self, r):
        if isinstance(r, Quaternion):
            q = self
            out_data = np.zeros(4, dtype=float)
            out_data[0] = r(0)*q(0) - r(1)*q(1) - r(2)*q(2) - r(3)*q(3)
            out_data[1] = r(0)*q(1) + r(1)*q(0) - r(2)*q(3) + r(3)*q(2)
            out_data[2] = r(0)*q(2) + r(1)*q(3) + r(2)*q(0) - r(3)*q(1)
            out_data[3] = r(0)*q(3) - r(1)*q(2) + r(2)*q(1) + r(3)*q(0)
            return Quaternion(out_data)
        else:
            raise Exception('Multiplication by other not supported.')

    def norm(self):
        return la.norm(self.data)

    def normalize(self, inplace=False):
        if inplace:
            nrm = self.norm()
            self.data /= nrm
            return None
        nrm = self.norm()
        data_copy = np.array(self.data, copy=True)
        data_copy /= nrm
        return Quaternion(data_copy)

def quaternion_from_axis_rotation(angle, axis):
    out = np.zeros(4, dtype=float)
    if axis == 'x':
        out[1] = 1
    elif axis == 'y':
        out[2] = 1
    elif axis == 'z':
        out[3] = 1
    else:
        raise ValueError('Invalid axis input.')
    out *= math.sin(angle/2.0)
    out[0] = math.cos(angle/2.0)
    return Quaternion(out)

def test_quaternion_from_axis_rotation():
    angle = math.pi / 4  # 45 degrees
    axis_x = 'x'
    axis_y = 'y'
    axis_z = 'z'
    invalid_axis = 'w'  # invalid axis

    # Test x-axis quaternion creation
    result_x = quaternion_from_axis_rotation(angle, axis_x)
    assert np.allclose(result_x.data, [math.cos(angle/2), math.sin(angle/2), 0, 0]), "Quaternion for x-axis rotation is incorrect."

    # Test y-axis quaternion creation
    result_y = quaternion_from_axis_rotation(angle, axis_y)
    assert np.allclose(result_y.data, [math.cos(angle/2), 0, math.sin(angle/2), 0]), "Quaternion for y-axis rotation is incorrect."

    # Test z-axis quaternion creation
    result_z = quaternion_from_axis_rotation(angle, axis_z)
    assert np.allclose(result_z.data, [math.cos(angle/2), 0, 0, math.sin(angle/2)]), "Quaternion for z-axis rotation is incorrect."

    # Test invalid axis input
    try:
        quaternion_from_axis_rotation(angle, invalid_axis)
        raise AssertionError("ValueError not raised for an invalid axis")
    except ValueError:
        pass  # This is expected

if __name__=='__main__':
    test_quaternion_from_axis_rotation()

