import csv
from functools import wraps
from importlib import import_module
from math import asin, cos, exp, radians, sin, sqrt

def load_file(filepath):
    with open(filepath) as f:
        for line in f:
            yield line

def load_msgpack_file(filepath):
    import msgpack  # We don't want to make it a required dependency.
    with open(filepath, mode='rb') as f:
        for line in msgpack.Unpacker(f, encoding='utf-8'):
            yield line

def load_csv_file(filepath):
    with open(filepath, newline='') as csvfile:
        dialect = csv.Sniffer().sniff(csvfile.read(1024))
        csvfile.seek(0)
        reader = csv.DictReader(csvfile, dialect=dialect)
        yield from reader

def iter_pipe(pipe, processors):
    """Allow for iterators to return either an item or an iterator of items."""
    if isinstance(pipe, str):
        pipe = [pipe]
    for it in processors:
        pipe = it(pipe)
    yield from pipe

def import_by_path(path):
    """
    Import functions or class by their path. Should be of the form:
    path.to.module.func
    """
    if not isinstance(path, str):
        return path
    module_path, *name = path.rsplit('.', 1)
    func = import_module(module_path)
    if name:
        func = getattr(func, name[0])
    return func

def yielder(func):
    @wraps(func)
    def wrapper(pipe):
        for item in pipe:
            yield func(item)
    return wrapper

def test_import_by_path():
    # Test that the imported function is the correct one
    assert import_by_path('math.sin') == sin
    # Test that the imported function is callable and returns the expected result
    assert import_by_path('math.sqrt')(4) == 2.0
    # Test that providing the module class name returns the appropriate class/type
    assert import_by_path('csv.DictReader') == csv.DictReader

if __name__ == '__main__':
    test_import_by_path()

