class Layout:
    def __init__(self, input_dict=None):
        self._p2v = {}
        self._v2p = {}
        if input_dict is not None:
            self.from_dict(input_dict)

    def from_dict(self, input_dict):
        for key, value in input_dict.items():
            virtual, physical = self.order_based_on_type(key, value)
            self._set_type_checked_item(virtual, physical)

    @staticmethod
    def order_based_on_type(value1, value2):
        if isinstance(value1, int) and isinstance(value2, tuple):
            return value2, value1
        elif isinstance(value2, int) and isinstance(value1, tuple):
            return value1, value2
        else:
            raise ValueError("Invalid key-value pair for layout.")

    def __getitem__(self, item):
        if item in self._p2v:
            return self._p2v[item]
        if item in self._v2p:
            return self._v2p[item]
        raise KeyError(item)

    def __setitem__(self, key, value):
        virtual, physical = self.order_based_on_type(key, value)
        self._set_type_checked_item(virtual, physical)

    def _set_type_checked_item(self, virtual, physical):
        self._p2v.pop(self._v2p.pop(virtual, None), None)
        self._v2p.pop(self._p2v.pop(physical, None), None)
        self._p2v[physical] = virtual
        self._v2p[virtual] = physical

    def add(self, virtual_bit, physical_bit=None):
        if physical_bit is None:
            physical_bit = 0
            while physical_bit in self._p2v:
                physical_bit += 1
        self[virtual_bit] = physical_bit


def test_add():
    qr = QuantumRegister(3, 'qr')
    layout = Layout()
    layout.add((qr, 0), 5)
    assert layout._p2v[5] == (qr, 0) and layout._v2p[(qr, 0)] == 5

    # Testing auto-assign for physical bit
    layout.add((qr, 1))
    assert layout._p2v[0] == (qr, 1) and layout._v2p[(qr, 1)] == 0

    # Adding multiple pairs to ensure integrity of mappings
    layout.add((qr, 2), 3)
    assert layout._p2v[3] == (qr, 2) and layout._v2p[(qr, 2)] == 3
    assert layout._p2v[0] == (qr, 1) and layout._v2p[ (qr, 1)] == 0
    assert layout._p2v[5] == (qr, 0) and layout._v2p[(qr, 0)] == 5

if __name__ == '__main__':
    test_add()
    print("All tests passed.")

