    # Test with md5 algorithm
    hash_object = Hash(data='This is a test.', algorithm='md5')
    md5_result = hash_object._hash_data('md5')
    assert md5_result == hashlib.md5(b'This is a test.').hexdigest(), "MD5 hash does not match"

    # Test with sha1 algorithm
    hash_object = Hash(data='This is a test.', algorithm='sha1')
    sha1_result = hash_object._hash_data('sha1')
    assert sha1_result == hashlib.sha1(b'This is a test.').hexdigest(), "SHA1 hash does not match"

    print("All tests for _hash_data passed successfully.")

if __name__ == "__main__":
    test__hash_data()
    # Optionally, print the hash results using the get method implemented in the Hash class
    hash_object = Hash(data='This is a test.')
