from dateutil import parser

class TaskHandler(object):
    def __init__(self):
        self.steps = []

    def _load_steps(self, raw_steps):
        """ load steps -> basically load all the datetime isoformats into datetimes """
        for step in raw_steps:
            if 'start' in step:
                step['start'] = parser.parse(step['start'], ignoretz=True)
            if 'stop' in step:
                step['stop'] = parser.parse(step['stop'], ignoretz=True)
        return raw_steps

def test__load_steps():
    task_handler = TaskHandler()

    # Test data with both start and stop dates
    raw_steps_full = [
        {"start": "2022-01-01T00:00:00Z", "stop": "2022-01-01T01:00:00Z", "name": "Step 1"}
    ]
    loaded_steps = task_handler._load_steps(raw_steps_full)
    assert loaded_steps[0]["start"] == datetime(2022, 1, 1, 0, 0)
    assert loaded_steps[0]["stop"] == datetime(2022, 1, 1, 1, 0)

    # Test data with only start date
    raw_steps_start_only = [
        {"start": "2022-01-01T02:00:00Z", "name": "Step 2"}
    ]
    loaded_steps = task_handler._load_steps(raw_steps_start_only)
