        idx = list(range(len(self.intervals)))
        thicknesses = [interval.thickness for interval in self.intervals]
        colors = [interval.component.color for interval in self.intervals]

        # Use the lists instead of individual values
        for i, h, c in zip(idx, thicknesses, colors):
