    def __init__(self, **kwargs):
        self.wprogressbar = {
                'n': kwargs.get("progress_n", 0),
                'nmin': kwargs.get("progress_nmin", 0),
                'nmax': kwargs.get("progress_nmax", 100),
        }
        self._label_progressbar_fmt = kwargs.get("label_progressbar", "{percent:.1f}%")
        self.wprogresslabel = {"label": ""}
        self.update_progressbar()

    def update_progressbar(self):
        n = self.wprogressbar['n']
        nmin = self.wprogressbar['nmin']
        nmax = self.wprogressbar['nmax']
        if (nmax - nmin) == 0:
            percent = 0
        else:
            percent = max(min((n - nmin) / (nmax - nmin), 1.), 0.) * 100
        self.wprogresslabel['label'] = self._label_progressbar_fmt.format(n=round(n, 4), nmin=round(nmin, 4), nmax=round(nmax, 4), percent=round(percent, 4))

    @property
    def progress_n(self):
        return self.wprogressbar['n']

    @progress_n.setter
    def progress_n(self, value):
        self.wprogressbar['n'] = value
        self.update_progressbar()

