def swallow_argv(argv, aliases=None, flags=None):
    """strip frontend-specific aliases and flags from an argument list

    For use primarily in frontend apps that want to pass a subset of command-line
    arguments through to a subprocess, where frontend-specific flags and aliases
    should be removed from the list.

    Parameters
    ----------

    argv : list(str)
        The starting argv, to be filtered
    aliases : container of aliases (dict, list, set, etc.)
        The frontend-specific aliases to be removed
    flags : container of flags (dict, list, set, etc.)
        The frontend-specific flags to be removed

    Returns
    -------

    argv : list(str)
        The argv list, excluding flags and aliases that have been stripped
    """

    if aliases is None:
        aliases = set()
    if flags is None:
        flags = set()

    stripped = list(argv)  # copy

    swallow_next = False
    was_flag = False
    for a in argv:
        if swallow_next:
            swallow_next = False
            if not (was_flag and a.startswith('-')):
                stripped.remove(a)
                continue
        if a.startswith('-'):
            split = a.lstrip('-').split('=')
            alias = split[0]
            if alias in aliases:
                stripped.remove(a)
                if len(split) == 1:
                    swallow_next = True
                    was_flag = alias in flags
            elif alias in flags and len(split) == 1:
                stripped.remove(a)

    return stripped

def test_swallow_argv():
    test_argv1 = ["--config=myconfig.py", "--alias1", "value", "--flag1", "extra_arg"]
    test_aliases1 = {"alias1"}
    test_flags1 = {"flag1"}
    assert swallow_argv(test_argv1, aliases=test_aliases1, flags=test_flags1) == ["--config=myconfig.py", "extra_arg"]

    test_argv2 = ["--alias2=value2", "--alias3", "-flag2", "extra_arg"]
    test_aliases2 = {"alias2", "alias3"}
    test_flags2 = {"flag2"}
    assert swallow_argv(test_argv2, aliases=test_aliases2, flags=test_flags2) == ["extra_arg"]

    test_argv3 = ["--keep", "--alias4", "--flag3"]
    test_aliases3 = {"alias4"}
    test_flags3 = {"flag3"}
    assert swallow_argv(test_argv3, aliases=test_aliases3, flags=test_flags3) == ["--keep"]

if __name__ == "__main__":
    # Run the test for the swallow_argv function
    test_swallow_argv()

