import numpy as np

class SegmentTransducer:
    """
    A class representing a segmental transducer that implements a set of weighted
    finite-state transductions (aka, operations) with associated costs.
    """
    def __init__(self, alphabet, operation_costs=None, allow_spaces=False):
        self.alphabet = alphabet
        self.allow_spaces = allow_spaces
        if operation_costs is None:
            self.operation_costs = self._make_default_operation_costs()
        else:
            self.operation_costs = operation_costs
        self._make_reversed_operation_costs()

    def _make_default_operation_costs(self):
        """
        Sets the default cost of 1.0 for replacements, insertions, deletions, and
        transpositions.
        """
        operation_costs = {'': {c: 1.0 for c in self.alphabet}}
        for char in self.alphabet:
            operation_costs[char] = {c: (0.0 if c == char else 1.0) for c in self.alphabet}
            operation_costs[char][''] = 1.0  # cost for deletion
        return operation_costs

    def _make_reversed_operation_costs(self):
        """
        Constructs the reversed operation costs based on the existing operation costs.
        """
        reversed_operation_costs = {}
        for upper, costs in self.operation_costs.items():
            for lower, cost in costs.items():
                if lower not in reversed_operation_costs:
                    reversed_operation_costs[lower] = {}
                reversed_operation_costs[lower][upper] = cost
        self._reversed_operation_costs = reversed_operation_costs

    def get_reversed_operation_costs(self):
        """
        Getter method for accessing the reversed operation costs.
        """
        return self._reversed_operation_costs

def test__make_reversed_operation_costs():
    alphabet_test = ['x', 'y']
    operation_costs_test = {
        '': {'x': 0.5, 'y': 1.5},
        'x': {'': 1.0, 'x': 0.0, 'y': 2.0},
        'y': {'': 0.5, 'x': 1.5, 'y': 0.0}
    }
    expected_reversed_costs = {
        '': {'x': 1.0, 'y': 0.5},
        'x': {'': 0.5, 'x': 0.0, 'y': 1.5},
        'y': {'': 1.5, 'x': 2.0, 'y': 0.0}
    }
    transducer_test = SegmentTransducer(alphabet_test, operation_costs=operation_costs_test)
    reversed_costs_test = transducer_test.get_reversed_operation_costs()

    # Assertion checks:
    assert reversed_costs_test == expected_reversed_costs, "Reversed costs do not match expected values."
    assert reversed_costs_test['x'][''] == 0.5, "Cost for deleting 'x' should be 0.5."
    assert reversed_costs_test['']['y'] == 0.5, "Cost for inserting 'y' should be 0.5."

if __name__ == '__main__':
    test__make_reversed_operation_costs()
