    def _post_resource(self, url, body):
        return body


class CanvasAdmin:
    def __init__(self, data):
        self.data = data


ADMINS_API = "/api/v1/accounts/{}/admins"


class Admins(FakeCanvas):
    def create_admin(self, account_id, user_id, role):
        """
        Flag an existing user as an admin within the account.

        https://canvas.instructure.com/doc/api/admins.html#method.admins.create
        """
        url = ADMINS_API.format(account_id)
        body = {"user_id": unquote(str(user_id)),
                "role": role,
                "send_confirmation": False}

        return CanvasAdmin(data=self._post_resource(url, body))


def test_create_admin():
    admins = Admins()

    # Test normal case
    account_id = 1
    user_id = 42
    role = "test_role"
    admin = admins.create_admin(account_id, user_id, role)
    assert admin.data == {
        "user_id": str(user_id),
        "role": role,
        "send_confirmation": False
    }

    # Test edge case with an empty string for role
    user_id = 100
    role = ""
    admin = admins.create_admin(account_id, user_id, role)
    assert admin.data == {
        "user_id": str(user_id),
        "role": role,
        "send_confirmation": False
    }

    # Test with a special character in the user_id that should be unquoted
    user_id = quote('abc@example.com')
    admin = admins.create_admin(account_id, user_id, role)
    assert admin.data == {
        "user_id": unquote(user_id),
        "role": role,
        "send_confirmation": False
    }


if __name__ == '__main__':
    test_create_admin()

