import socket
from collections import deque

class AutoClosingSharedSocket(object):
    def __init__(self, sock):
        self._closed = False
        self._socket = sock

    def close(self):
        if self._closed:
            return
        self._socket.close()
        self._closed = True

    def __del__(self):
        self.close()

    def __getattr__(self, name):
        return getattr(self._socket, name)


class AbstractClient(object):
    def __init__(self, host, port=8125, prefix=''):
        self._port = port
        self._host = host
        self._remote_address = None
        self._socket = None
        self.prefix = prefix

    @property
    def remote_address(self):
        if self._remote_address is None:
            self._remote_address = (socket.gethostbyname(self._host), self._port)
        return self._remote_address

    def _create_socket(self):
        sock = AutoClosingSharedSocket(socket.socket(socket.AF_INET, socket.SOCK_DGRAM))
        return sock

    def _request(self, data):
        print("Sending data: {}".format(data))

    def __del__(self):
        if self._socket:
            self._socket = None


class BatchClientMixIn(object):
    def __init__(self, batch_size=512):
        self._batch_size = batch_size
        self._batches = deque()

    @property
    def batch_size(self):
        return self._batch_size

    def clear(self):
        self._batches.clear()
        return self

    def flush(self):
        for batch in self._batches:
            print("Sending batch data: {}".format(batch))
        self._batches.clear()


class BatchClient(BatchClientMixIn, AbstractClient):
    def __init__(self, host, port=8125, prefix="", batch_size=512):
        AbstractClient.__init__(self, host, port, prefix)
        BatchClientMixIn.__init__(self, batch_size)

    def unit_client(self):
        client = Client(self._host, self._port, self.prefix)
        return client

    def _request(self, data):
        data = "{}\n".format(data).encode()
        self._prepare_batches_for_storage(len(data))
        self._batches[-1].extend(data)

    def _prepare_batches_for_storage(self, data_size=None):
        batch_size = self._batch_size
        data_size = data_size or batch_size
        if data_size > batch_size:
            self._batches.append(bytearray())
        elif len(self._batches) < 1 or (len(self._batches[-1]) + data_size) >= batch_size:
            self._batches.append(bytearray())


class Client(AbstractClient):
    def batch_client(self, size=512):
        batch_client = BatchClient(self._host, self._port, self.prefix, size)
        return batch_client


def test_unit_client():
    host = "localhost"
    port = 8125
    prefix = "test_prefix"

    batch_client = BatchClient(host, port, prefix)
    client = batch_client.unit_client()

    # Test if the returned client object is an instance of Client
    assert isinstance(client, Client)

    # Test whether the client has the same host as the BatchClient
    assert client._host == host

    # Test whether the client inherits the same prefix as the BatchClient
    assert client.prefix == prefix

if __name__ == '__main__':
    test_unit_client()
    print("All tests passed for the unit_client function.")

