import numpy as np
import tensorflow as tf

def assert_finite(x, data=None, summarize=None, message=None, name=None):
    with tf.name_scope(name or 'assert_finite'):
        x_ = tf.get_static_value(x)
        if x_ is not None:
            if ~np.all(np.isfinite(x_)):
                raise ValueError(message)
            return x
        assertion = tf.compat.v1.assert_equal(
            tf.math.is_finite(x), tf.ones_like(x, tf.bool),
            data=data, summarize=summarize, message=message)
        with tf.control_dependencies([assertion]):
            return tf.identity(x)

def test_assert_finite():
    # Test when all the numbers are finite
    x = tf.constant([1.0, 2.0, 3.0], dtype=tf.float32)
    assert np.all(np.isfinite(assert_finite(x)))

    # Test when max float value is used
    x = tf.constant([1.0, 2.0, float('inf')], dtype=tf.float32)
    try:
        assert_finite(x)
    except ValueError as e:
        assert str(e) == 'None', 'Error message did not match'

    # Test when min float value is used
    x = tf.constant([1.0, 2.0, float('-inf')], dtype=tf.float32)
    try:
        assert_finite(x)
    except ValueError as e:
        assert str(e) == 'None', 'Error message did not match'

if __name__=='__main__':
    test_assert_finite()

